WITH payload AS (SELECT $archive_payload$[{"id":"df530195-d2f9-5232-96fd-7ca4d1ceb439","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلشيش املخدر - محاولة الهرب من الفرقة القابضة -اإلقرار حتقيق ا -تعاطي احلبوب احملظورة -إقامة حد املسكر على متعاطي احلشيش - التعزير بالسجن واجللد والغرامة واملصادرة واملنع من السفر -1املواد ( )38و ( )53و ( )56من نظام مكافحة املخدرات.","document_number":"33335630","case_number":"33179812","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/07/09","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلشيش املخدر - محاولة الهرب من الفرقة القابضة -اإلقرار حتقيق ا -تعاطي احلبوب احملظورة -إقامة حد املسكر على متعاطي احلشيش - التعزير بالسجن واجللد والغرامة واملصادرة واملنع من السفر -1املواد ( )38و ( )53و ( )56من نظام مكافحة املخدرات.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33335630 :‬تاريخه ‪1433/07/09 :‬هـ‬\n                         ‫رقم الدعوى ‪33179812:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34227542‬تاريخه‪1434/05/29 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬تعاطــي احلشــيش املخــدر ‪-‬‬\n      ‫محاولــة الهــرب مــن الفرقــة القابضــة ‪ -‬اإلقــرار حتقيق ـ ًا ‪ -‬تعاطــي‬\n      ‫احلبــوب احملظــورة ‪ -‬إقامــة حــد املســكر علــى متعاطــي احلشــيش ‪-‬‬\n        ‫التعزيــر بالســجن واجللــد والغرامــة واملصــادرة واملنــع مــن الســفر‬\n\n\n\n\n                  ‫‪ -1‬املواد (‪ )38‬و (‪ )53‬و (‪ )56‬من نظام مكافحة املخدرات‪.‬‬\n      ‫‪ -2‬املــادة (‪ )38‬مــن النظــام األساســي للحكــم والتــي تنــص علــى أن ‪:‬‬\n      ‫(العقوبــة شــخصية وال جرميــة وال عقوبــة إال بنــاء علــى نــص شــرعي‬\n      ‫أو نظامــي وال عقــاب إال علــى األعمــال الالحقــة للعمــل بالنــص‬\n                                                                 ‫النظامــي)‪.‬‬\n                          ‫‪ -3‬ما قرره أهل العلم من دخول التعزير يف احلد‪.‬‬\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج ســت حبــات مــن حبــوب‬\n      ‫اإلمفيتامــن املنبــه احملظــور عــن طريــق البيــع وتعاطيــه للحشــيش املخدر‬\n      ‫واحلبــوب احملظــورة و تســتره علــى مصــدر املخــدرات و مقاومتــه لرجــال‬\n      ‫األمــن‪ .‬حيــث توفــرت معلومــات إلدارة مكافحــة املخــدرات مــن أحــد‬\n      ‫املصــادر الســرية عــن قيــام املدعــى عليــه بترويــج احلبــوب احملظــورة ومت‬\n\n‫‪81‬‬\n\f‫وضــع اخلطــة املناســبة مــع املصــدر الســري لإلطاحــة بــه و قــام املصــدر‬\n‫باالتصــال باملدعــى عليــه علــى مســمع مــن أفــراد الفرقــة القابضــة و طلب‬\n‫منــه حبــوب مخــدرة و اســتعد املــروج (املدعــى عليــه ) بذلــك و طلــب مــن‬\n‫املصــدر مقابلتــه يف مــكان محــدد ومت تفتيــش املصــدر و تزويــده باملبلــغ‬\n‫املرقــم وقــام املصــدر بتســليم الفرقــة احلبــوب احملظــورة ‪ ،‬متــت متابعــة‬\n‫املــروج و طلــب منــه التوقــف إال أنــه حــاول الهــرب فتمــت الســيطرة عليــه‬\n‫وعنــد محاولــة إنزالــه شــوهد وهــو يضــع شــيئ ًا مــا يف فمــه يحتمــل أن‬\n‫يكــون مــادة مخــدرة و قــام مبقاومــة الفرقــة حتــى متــت الســيطرة عليــه‬\n‫و تبــن أنــه املدعــى عليــه‪ ،‬طلــب املدعــي العــام إثبــات إدانتــه مبــا أســند‬\n‫إليــه واحلكــم عليــه مبــا تضمنــه نظــام مكافحــة املخــدرات واملقتضــى‬\n‫الشــرعي للتعاطــي وأنكــر املدعــى عليــه ما نســب إليــه ‪ ،‬أحضر املدعى‬\n‫عليــه العــام بينتــه وهــم الفرقــة احملــررة حملضــر القبــض ‪ ،‬وأقــر املدعــى‬\n‫عليــه بعــد ذلــك مبــا نســب إليــه وأبــدى أســفه وندمه‪،‬بنــاء علــى مــا تقــدم‬\n‫حكمــت احملكمــة بإقامــة حــد املســكر و التعزيــر بالســجن واجللــد‬\n‫والغرامــة واملصــادرة واملنــع مــن الســفر وصــدق احلكــم مــن محكمــة‬\n                                                                    ‫االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باخلــرج ‪ /‬املســاعد برقــم ‪ 33179812‬وتاريــخ‬\n‫‪ 1433/03/13‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33473184‬وتاريــخ‬\n‫‪ 1433/03/13‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1433/04/13‬هـ افتتحت‬\n\n                                                                                      ‫‪82‬‬\n\f     ‫اجللســة وفيهــا حضــر املدعــي العــام ‪........‬وادعــى قائــا بصفتــي عضــو‬\n     ‫هيئــة التحقيــق واالدعــاء العــام مبحافظــة اخلــرج أدعــي علــى ‪،........:‬‬\n     ‫ـاء‬\n     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬حيــث أنــه بنـ ً‬\n     ‫علــى معلومــات لــدى فرقــة مــن مكافحــة املخــدرات مبحافظــة اخلــرج‬\n     ‫مــن أحــد املصــادر الســرية عــن قيــام املدعــى عليــه بترويــج احلبــوب‬\n     ‫احملظــورة يف محافظــة اخلــرج فتــم وضــع اخلطــة املناســبة مــع املصــدر‬\n     ‫الســري لإلطاحــة بــه باجلــرم املشــهود وعنــد الســاعة الثانيــة عشــرة مــن‬\n     ‫بعــد ظهــر يــوم الســبت املوافــق ‪1433/2/20‬ه ـ قــام املصــدر الســري‬\n     ‫باالتصــال علــى جــوال املدعــى عليــه رقــم (‪ )........‬ووضــع اجلــوال علــى‬\n     ‫وضــع (الســبيكر) علــى مســمع مــن أفــراد فرقــة مكافحــة املخــدرات‬\n     ‫وطلــب منــه حبــوب مخــدرة مببلــغ (‪ )200‬مائتــي ريــال واســتعد املــروج‬\n     ‫بذلــك ثــم طلــب منــه مقابلتــه يف حــي ‪........‬بالقــرب مــن قصــر ‪........‬‬\n     ‫لالحتفــاالت فتــم تفتيــش املصــدر الســري تفتيش ـ ًا دقيق ـ ًا وزود مببلــغ‬\n     ‫مرقــم قــدره (‪ )200‬مائتــي ريــال واجتــه أمــام الفرقــة علــى قدميــه إلــى‬\n     ‫املــكان احملــدد وبعــد حلظــات شــوهدت ســيارة مــن نــوع (‪)....‬اللــون‬\n     ‫رصاصــي حتمــل اللوحــة رقــم (‪ )........‬وبهــا شــخص يتوقــف عنــد املصــدر‬\n     ‫الســري ويقابلــه وبعــد حلظــات حتركــت الســيارة وأعطــى املصــدر‬\n     ‫الســري اإلشــارة الدالــة إمتــام العمليــة باســتالمه (‪ )6‬ســت حبــات بيضــاء‬\n     ‫حتمــل عالمــة الكبتاجــون ‪ ،‬وقــام بتســليم الفرقــة احلبــوب احملظــورة‬\n     ‫فتمــت متابعــة املــروج وســيارته حتــى توقــف عنــد إشــارة الشــارع رقــم‬\n     ‫(‪ )........‬علــى طريــق األميــر ‪........‬فتــم طلــب توقفــه إال أنــه حــاول الهــرب‬\n     ‫فتمــت الســيطرة عليــه وعنــد محاولــة إنزالــه مــن الســيارة شــوهد وهــو‬\n     ‫يضــع شــيئ ًا مــا يف فمــه يحتمــل أن يكــون مــادة مخــدرة وقــام مبقاومــة‬\n\n\n‫‪83‬‬\n\f‫الفرقــة حتــى متــت الســيطرة عليــه وتبــن أنــه املدعــى عليــه ‪ ،‬وبتفتيشــه‬\n‫عثــر يف جيــب ثوبــه األيســر علــى مبلــغ مالــي قــدره (‪ )200‬مائتــي ريــال‬\n‫وهــو نفــس املبلــغ احلكومــي املرقــم‪ ،‬كمــا عثــر بحوزتــه علــى جــوال نــوع‬\n‫‪ ....‬رقمــه املصنعــي ‪ ..............‬ويتصفــح مكاملاتــه الــواردة تبــن أنــه نفــس‬\n‫اجلــوال املســتخدم يف عمليــة الترويــج ‪ ،‬وقــد أثبــت التقريــر الكيميائــي‬\n‫الشــرعي الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة‬\n‫الشــرعية باملديريــة العامــة للشــئون الصحيــة بالريــاض برقــم (‪)..............‬‬\n‫لعــام ‪1433‬ه ـ إيجابيــة الســت احلبــات املضبوطــة ملــادة االمفيتامــن وهــو‬\n‫مــن املــواد املنبهــة واملدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬وباســتجواب املدعــى عليــه أقــر‬\n‫حتقيق ـ ًا بأنــه قبــض عليــه بتاريــخ ‪1433/2/20‬ه ـ مــن قبــل فرقــة‬\n‫مكافحــة املخــدرات وأن اجلــوال نــوع ‪ ....‬والــذي يحمــل الرقــم (‪)........‬‬\n‫عائــد لــه شــخصي ًا وال يســتخدمه أحــد غيــره وهــو نفــس اجلــوال الــذي‬\n‫عثــر عليــه معــه أثنــاء القبــض عليــه ‪ ،‬كمــا أن الســيارة نــوع ‪ ....‬رقــم‬\n‫اللوحــة ‪ ........‬والتــي قبــض عليــه وهــو يقودهــا تعــود ملكيتهــا لوالــده‬\n‫وقــد أخذهــا منــه صبــاح اليــوم الــذي قبــض عليــه فيــه إلــى أن مت القبــض‬\n‫عليــه ‪ ،‬وقــد أقــر بتعاطيــه للحشــيش املخــدر واحلبــوب احملظــورة منــذ‬\n‫عشــر ســنوات وآخــر مــرة تعاطــى فيهــا احلشــيش املخــدر واحلبــوب‬\n‫احملظــورة قبــل خمســة أيــام تقريب ـ ًا مــن القبــض عليــه ‪ ،‬وأنــه يحصــل‬\n‫علــى احلشــيش املخــدر واحلبــوب احملظــورة مــن أشــخاص ال يعرفهــم‬\n‫مبدينــة الريــاض ‪.‬وقــد انتهــى التحقيــق إلــى توجيــه االتهــام لــه بترويــج‬\n‫(‪ )6‬ســت حبــات مــن حبــوب االمفيتامــن املنبــه احملظــور عــن طريــق‬\n‫البيــع ‪ ،‬وتعاطيــه للحشــيش املخــدر واحلبــوب احملظــورة ‪ ،‬املجرم بالفقرة‬\n\n\n                                                                                       ‫‪84‬‬\n\f     ‫(الثانيــة) مــن املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n     ‫وتســتره علــى مصــدر املخــدرات ‪ ،‬ومقاومتــه لرجــال األمــن ‪ ،‬وذلــك‬\n     ‫لألدلــة والقرائــن التاليــة ‪ -1-:‬محضــر القبــض املنــوه عنــه املــدون يف‬\n     ‫ملــف ضبــط إجــراءات االســتدالل يف قضايــا املخــدرات علــى الصفحــات‬\n     ‫رقــم (‪ )11‬املرفــق علــى اللفــة رقــم (‪ -2 )1‬إقــراره حتقيق ـ ًا املنــوه عنــه‬\n     ‫املرفــق صورتــه علــى اللفــة رقــم (‪ )5 ،1‬مــن دفتــر التحقيــق املرفــق علــى‬\n     ‫اللفــة رقــم (‪ -3 . )17‬التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق‬\n     ‫علــى اللفــة رقــم (‪ . )32‬وبالبحــث عمــا إذا كان لــه ســوابق عثــر لــه علــى‬\n     ‫ســابقة واحــدة وهــي ســرقة ســيارات مقترنــة بســرقة اســطوانة غــاز‬\n     ‫وطعــن شــخص وتهديــد بالســاح ‪ .‬وحيــث إن مــا قــام بــه املدعــى عليــه‬\n     ‫‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه‬\n     ‫شــرع ًا ومجــرم ومعاقــب عليــه نظام ـ ًا ‪ ،‬أطلــب إثبــات إدانتــه مبــا أســند‬\n     ‫إليــه واحلكــم عليــه باآلتــي ‪ -1:‬بحــد املســكر لقــاء تعاطيــه احلشــيش‬\n     ‫املخــدر ‪ -2 .‬بعقوبــة وفق ـ ًا للمــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة املشــار إليــه لقــاء ترويجــه (‪ )6‬ســت حبــات مــن حبــوب‬\n     ‫االمفيتامــن املنبــه احملظــور طريــق البيــع ‪ -3‬بعقوبــة وفقـ ًا للمــادة (‪)41‬‬\n     ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه لقــاء‬\n     ‫تعاطيــه احلبــوب احملظــورة ‪ ،‬مــع إعمــال الفقــرة األولــى مــن املــادة (‪)62‬‬\n     ‫مــن نظــام مكافحــة املخــدرات املشــار إليــه ‪ -4 .‬تشــديد العقوبــة عليــه‬\n     ‫وفق ـ ًا للفقــرة (ج) مــن البنــد (‪ )2‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة‬\n     ‫املخــدرات واملؤثــرات العقليــة املشــار إليــه واســتنادا إلــى برقيــة صاحــب‬\n     ‫الســمو امللكــي وزيــر الداخليــة رقــم (‪2/8346/4/5/1‬ش) وتاريــخ‬\n\n\n‫‪85‬‬\n\f‫‪1427/2/8‬ه ـ ‪ -5.‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد تنفيــذ‬\n‫عقوبــة الســجن بحقــه وفق ـ ًا للفقــرة األولــى مــن املــادة (‪ )56‬مــن نظــام‬\n‫مكافحــة املخــدرات املشــار إليــه ‪ -6‬بعقوبــة تعزيريــة لقــاء تســتره علــى‬\n‫مصــدر احلبــوب املضبوطــة واحلشــيش املخــدر وفــق تعميم صاحب الســمو‬\n‫امللكــي أميــر منطقــة الريــاض بالنيابــة رقــم (‪ )10283‬وتاريــخ‬\n‫‪1430/5/17‬ه ـ ولقــاء مقاومتــه لرجــال األمــن ‪ -7‬مصــادرة جهــاز اجلــوال‬\n‫املضبــوط بحــوزة املدعــى عليــه وهــو مــن نــوع ‪ ....‬ورقمــه التسلســلي‬\n‫(‪ )........‬ويحمــل الرقــم املصنعــي (‪ ، )........‬وشــريحة اجلــوال التــي حتمــل‬\n‫الرقــم (‪ )........‬الســتخدامها مــن قبلــه يف اجلرميــة وفق ـ ًا للفقــرة رقــم (‪)1‬‬\n‫مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثرات العقلية املشــار‬\n‫إليــه ‪ ،‬وإبــاغ الشــركة بعــدم صــرف الشــريحة التــي حتمــل الرقــم‬\n‫(‪ )........‬لنفــس املســتخدم لهــا مــرة أخــرى حــال صــدور احلكــم وفق ـ ًا‬\n‫لتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ‬\n‫‪1428/2/10-9‬ه ـ ثــم رفعــت اجللســة ألخــذ إجابــة املدعــى عليــه يف‬\n‫اجللســة القادمــة ويف جلســة أخــرى حضــر الطرفــان ثــم جــرى عــرض‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه وســؤاله عنهــا فأجــاب قائــا إن‬\n‫مــا ذكــره املدعــي العــام مــن أنــه مت القبــض علــي بتاريــخ ‪1433/2/20‬هـ‬\n‫فهــذا صحيــح ومــا ذكــره مــن محاولتــي الهــرب مــن الفرقــة القابضــة‬\n‫ومقاومتهــم عنــد القبــض علــي فهــذا غيــر صحيــح ولكــن الــذي حصــل‬\n‫منــي أننــي دفعــت شــخصا واحــدا منهــم فقــط عنــد القبــض علــي وذلــك‬\n‫أنهــم يلبســون ثيابــا مدنيــة ولــم أعلــم أنهــم رجــال أمــن ‪ ،‬ومــا ذكــره مــن‬\n‫أننــي قمــت بترويــج ســت حبــات مــن حبــوب الكبتاجــون احملظــورة عــن‬\n‫طريــق البيــع فهــذا غيــر صحيــح أيضــا واملبلــغ الــذي عثــر عليــه بحوزتــي‬\n\n\n                                                                                       ‫‪86‬‬\n\f     ‫عائــد لــي وهــو مــن مالــي اخلــاص وقــد أخــذه منــي رجــال األمــن عنــد‬\n     ‫القبــض علــي ‪ ،‬وبالنســبة ملــا ذكــره املدعــي العــام مــن أننــي أتعاطــى‬\n     ‫احلشــيش املخــدر واحلبــوب احملظــورة قبــل القبــض علــي فهــذا صحيــح‬\n     ‫وفعــا تعاطيــت احلشــيش واحلبــوب قبــل القبــض علــي بخمســة أيــام‬\n     ‫تقريبــا ‪ ،‬وبالنســبة للمصــدر الــذي أشــتري منــه احلشــيش واحلبــوب‬\n     ‫احملظــورة فــا أعرفــه وذلــك أننــي أشــتريها مــن الشــارع ‪ ،‬وبالنســبة‬\n     ‫للســوابق فليســت صحيحــة فليــس لــدي أي ســابقة هــذا مــا لــدي ثــم جرى‬\n     ‫ســؤال املدعــي العــام عــن بينتــه فقــال بينتــي موجــودة يف أوراق املعاملــة‬\n     ‫أطلــب الرجــوع لهــا إضافــة إلــى شــهود القبــض علــى املدعــى عليــه أطلــب‬\n     ‫إمهالــي للجلســة القادمــة مــن أجــل إحضارهــم ويف جلســة أخــرى حضــر‬\n     ‫الطرفــان وبســؤال املدعــي العــام عــن شــهود القبــض قــال لقــد أحضرتهــم‬\n     ‫معــي يف هــذا اليــوم أطلــب ســماع مــا لديهــم عليــه فقــد حضــر كال مــن‬\n     ‫‪ ..............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬والــذي‬\n     ‫يعمــل بــإدارة مكافحــة املخــدرات برتبــة رقيــب أول و ‪ ..............‬ســعود ي‬\n     ‫اجلنســية مبوجب الســجل املدني رقم ‪........‬والذي يعمل بإدارة مكافحة‬\n     ‫املخــدرات برتبــة رقيــب ولــدى ســؤالهما عمــا لديهمــا مــن شــهادة شــهدا‬\n     ‫قائلــن نشــهد هلل تعالــى أنــه يف يــوم الســبت وتاريــخ ‪1433/2/20‬ه ـ‬\n     ‫توفــرت لدينــا معلومــات عــن وجــود شــخص يدعــى ‪ ..............‬والــذي‬\n     ‫اتضــح الحقــا أنــه هــو املدعــى عليــه هــذا احلاضــر يقــوم بترويــج احلبــوب‬\n     ‫احملظــورة واســتعد املصــدر لإلطاحــة بــه فتمــت مقابلــة املصــدر يف‬\n     ‫الســاعة الثانيــة عشــرة ظهــر ًا مــن ذلــك اليــوم ومت االتصــال مــن قبــل‬\n     ‫املصــدر علــى جــوال املدعــو ‪ ..............‬رقــم (‪ )........‬وكان وضــع اجلــوال‬\n     ‫علــى مكبــر الصــوت وطلــب املصــدر مــن املدعــو ‪ ..............‬حبوب ـ ًا‬\n\n\n‫‪87‬‬\n\f‫محظــورة مبائتــي ريالــ‪ 200‬ـ ـ ـ فوافــق املدعــو ‪ ..............‬علــى ذلــك واتفقــا‬\n‫علــى املقابلــة يف موقــع قــرب قصــر ‪ ..............‬يف حــي ‪ ....‬وعلــى الفــور مت‬\n‫تفتيــش املصــدر تفتيش ـ ًا دقيق ـ ًا وزود باملبلــغ احلكومــي املرقــم وقــدره‬\n‫مائتــي ريــال وذهــب املصــدر ملقابلــة املدعــو ‪ ........‬ولــم يغــب عــن أنظارنــا‬\n‫فلمــا وصــل إلــى املوقــع املتفــق عليــه وبعــد عشــر دقائــق تقريبـ ًا حضــرت‬\n‫ســيارة مــن نــوع ‪ ....‬اللــون رصاصــي رقــم اللوحــة (‪ )........‬وتوقــف بجانــب‬\n‫املصــدر وحتدثــا قرابــة خمــس دقائــق وبعدهــا حتــرك صاحــب اجلمــس‬\n‫وكان برفقتــه حــدث يبلــغ مــن العمــر اثنــا عشــر عامـ ًا تقريبـ ًا وبعدهــا‬\n‫أعطــى املصــدر اإلشــارة الدالــة علــى إمتــام العمليــة ومتــت مقابلتــه علــى‬\n‫الفــور واســتالم ســت حبــات يشــتبه أنهــا مــن احلبــوب احملظــورة وأفــاد‬\n‫املصــدر أن املدعــو ‪ ..........‬هــو الــذي قــام بتســليمه إياهــا ولــم نشــاهد‬\n‫عمليــة التســليم واالســتالم وعلــى الفــور متــت متابعــة الســيارة ‪ ....‬ومت‬\n‫القبــض عليــه خــال عشــر دقائــق تقريب ـ ًا وأثنــاء القبــض عليــه حــاول‬\n‫الهــرب وذلــك بالرجــوع إلــى اخللــف ممــا تســبب يف احتــكاك بســيط‬\n‫بســيارة الفرقــة وبعدهــا متــت الســيطرة عليــه بعــد محاولتــه الهــرب‬\n‫والتفلــت مــن الفرقــة وبتفتيشــه شــخصي ًا لــم يعثــر علــى شــيء مــن‬\n‫املمنوعــات معــه وضبــط بحوزتــه املبلــغ احلكومــي املرقــم واجلــوال‬\n‫املســتخدم يف عمليــة الترويــج وهــو مــن نــوع ‪ ....‬ويحمــل الرقــم املشــار إليــه‬\n‫ســابق ًا وبســؤاله مبدئيـ ًا اعتــرف أمــام الفرقــة بقيامــة بترويــج ســت حبات‬\n‫للمصــدر عــن طريــق البيــع علــى املصــدر هــذا مــا لدينــا مــن شــهادة وعليــه‬\n‫نوقــع ‪ .‬وبعــرض الشــاهدين وشــهادتهما علــى املدعــى عليــه قــال ال أقــول‬\n‫يف الشــاهدين شــيئا وهمــا مــن الفرقــة التــي تولــت القبــض علــي‬\n‫وشــهادتهما صحيحــة فقــد قمــت بترويــج احلبــات الســت عــن طريــق البيــع‬\n\n\n                                                                                         ‫‪88‬‬\n\f     ‫وأنــا قــد صليــت الفجــر يف هــذا اليــوم وأعتــرف مبــا ورد يف شــهادتهما‬\n     ‫وأنــا تائــب هلل تعالــى هــذا مــا لــدي عنــد ذلــك طلبــت مــن املدعــي العــام‬\n     ‫تعديــل شــاهديه فأحضــر كال من‪........‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪........‬و‪........‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم ‪........‬واللــذان شــهدا بعدالــة الشــاهدين املذكوريــن وأنهمــا‬\n     ‫ثقتــان مرضيــا الشــهادة وكان قــد جــرى منــا اإلطــاع علــى كامــل‬\n     ‫أوراق املعاملــة فوجــد مــن ضمنهــا محضــر القبــض املــدون علــى محضــر‬\n     ‫ضبــط إجــراءات االســتدالل يف قضايــا املخــدرات املرفــق علــى لفــة رقــم‬\n     ‫(‪ )1‬صحيفــة رقــم (‪ )11‬واملتضمــن كيفيــة القبــض علــى املدعــى عليــه‬\n     ‫كمــا ذكــر املدعــي العــام وبعرضــه علــى املدعــى عليــه قــال إن مــا ورد‬\n     ‫يف هــذا احملضــر صحيــح وأنــا تائــب هلل تعالــى كمــا جــرى اإلطــاع‬\n     ‫علــى إقــرار املدعــى عليــه حتقيقــا املدونــة صــورة منــه علــى الصفحــة رقــم‬\n     ‫(‪ )5-1‬مــن ملــف التحقيــق املرفــق علــى لفــة رقــم (‪ )17‬واملتضمــن إقــراره‬\n     ‫بتعاطــي احلشــيش واحلبــوب احملظــورة وعدم معرفتــه ملصدرها ‪ ،‬وإقراره‬\n     ‫مبلكيتــه للجــوال املقبــوض عليــه معــه وإنــكاره لعمليــة الترويــج‬\n     ‫ومقاومــة الفرقــة القابضــة ومحاولــة الهــرب منهــا وبعرضــه علــى املدعــى‬\n     ‫عليــه قــال الصحيــح مــا ذكرتــه ســابقا فأنــا أتعاطــى احلشــيش املخــدر‬\n     ‫واحلبــوب احملظــورة ومــا ورد يف بيــع للحبــوب احملظــورة فصحيــح أيضــا‬\n     ‫وبالنســبة للمقاومــة فكمــا ذكــرت ســابقا وبالنســبة للمصــدر فأنــا ال‬\n     ‫أعرفــه هــذا مــا لــدي كمــا جــرى اإلطــاع علــى التقريــر الكيميائــي‬\n     ‫الشــرعي الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الشــرعية‬\n     ‫بالريــاض برقــم ‪........‬وتاريــخ ‪1433/3/2‬ه ـ واملتضمــن احتــواء العينــة‬\n     ‫علــى مــادة االمفيتامــن وهــو مــن املــواد املنبهــة واملدرجــة باجلــدول رقــم‬\n\n\n‫‪89‬‬\n\f‫(‪ )2‬فئــة (ب)مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبعرضــه‬\n‫علــى املدعــى عليــه صــادق عليــه كمــا جــرى اإلطــاع علــى صحيفــة‬\n‫ســوابق املدعــى عليــه املرفقــة علــى لفــة رقــم (‪ )24‬فوجــد أنهــا تتضمــن أن‬\n‫املدعــى عليــه عليــه ســابقة عبــارة عــن ســرقة ســيارات واســطوانة غــاز‬\n‫وطعــن شــخص وتهديــد بالســاح وبعرضهــا عليــه قــال ال أتذكرهــا ‪ ،‬ثم‬\n‫جــرى ســؤال الطرفــن هــل لديهمــا مــا يضيفانــه فقــاال ليــس لدينــا مــا‬\n‫نضيفــه فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي العــام ونظــرا ملــا ورد يف‬\n‫إجابــة املدعــى عليــه مــن إقــراره بأنــه مت القبــض عليــه بتاريــخ‬\n‫‪1433/2/20‬ه ـ وأنــه لــم يقــم مبقاومــة الفرقــة القابضــة وإمنــا قــام بدفــع‬\n‫شــخص منهــم وذلــك بســبب لباســهم املدنــي ولــم يعلــم أنهــم مــن رجــال‬\n‫األمــن وإقــراره لدينــا باســتعمال احلشــيش املخــدر واحلبــوب احملظــورة‬\n‫قبــل القبــض عليــه وأنــه يقــوم بشــرائها مــن الشــارع وال يعرف األشــخاص‬\n‫اللذيــن يقومــون ببيعهــا عليــه ‪ ،‬وأنكــر قيامــه بترويــج احلبــوب الســت‬\n‫احملظــورة التــي ذكرهــا املدعــي العــام يف دعــواه ‪ ،‬وبنــاء علــى البينــة‬\n‫املعدلــة شــرعا والتــي أحضرهــا املدعــي العــام وهــي شــاهدي القبــض‬\n‫واللــذان شــهدا هلل تعالــى أنهمــا شــاهدا املدعــى عليــه يقــوم مبقابلــة‬\n‫املصــدر حتــت أنظارهمــا والتحــدث ســويا فتــرة مــن الزمــن ثــم انصــراف‬\n‫املدعــى عليــه بعــد ذلــك وإحضــار املصــدر للحبــوب التــي اتضــح فيمــا بعد‬\n‫أنهــا مــن احلبــوب احملظــورة والقبــض علــى املدعــى عليــه قبــل غيابــه عــن‬\n‫أنظارهــم والعثــور علــى املبلــغ احلكومــي املرقــم بحوزتــه وكذلك اجلوال‬\n‫والشــريحة املســتعملة يف عمليــة الترويــج ونظــرا ملصادقــة املدعــى عليــه‬\n‫مؤخــرا علــى مــا ورد يف شــهادة الشــاهدين املشــار إليهــا ســابقا مــن قيامه‬\n‫بترويــج ســت حبــات مــن احلبــوب احملظــورة عــن طريــق البيــع ‪ ،‬وبعــد‬\n\n\n                                                                                      ‫‪90‬‬\n\f     ‫اإلطــاع علــى التقريــر الكيميائــي الشــرعي املرفــق واملتضمــن إيجابيــة‬\n     ‫العينــة ملــادة االمفيتامــن احملظــورة ‪ ،‬وبنــاء علــى املــادة الثامنــة والثالثــن‬\n     ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وبعــد اإلطــاع علــى‬\n     ‫املــادة الثالثــة واخلمســن والسادســة واخلمســن مــن ذات النظــام‪ ،‬ونظــرا‬\n     ‫لطلــب املدعــي العــام تطبيــق الفقــرة األولــى مــن املــادة احلاديــة واألربعــن‬\n     ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة فيمــا يتعلــق بتعاطــي‬\n     ‫املدعــى عليــه للحشــيش املخــدر واحلبــوب احملظــورة ونظــرا لكــون هــذه‬\n     ‫املــادة قــد نصــت علــى أن العقوبــة الــواردة فيهــا تطبــق يف حــق كل مــن‬\n     ‫ارتكــب أحــد األفعــال اجلرميــة املنصــوص عليهــا يف املادتــن الســابعة‬\n     ‫والثالثــن والثامنــة والثالثــن مــن النظــام املشــار إليــه ‪ ،‬وباالطــاع علــى‬\n     ‫املادتــن املذكورتــن لــم جنــد أن االســتعمال أو التعاطــي قــد ذكــر مــن‬\n     ‫ضمــن األفعــال اجلرميــة فيهمــا ‪ ،‬ومــن املعلــوم أنــه من املقــرر يف العقوبات‬\n     ‫النظاميــة وجــوب االســتناد إلــى نــص نظامــي صريــح يف العقوبــة ‪ ،‬وذلــك‬\n     ‫أن جتــرمي الفعــل والعقــاب عليــه نظامــا البــد أن يكــون بشــكل قاطــع ال‬\n     ‫يحتمــل معــه معنــى آخــر ‪ ،‬ولذلــك فإنــه ال مجــال للعقوبــة علــى جرميــة‬\n     ‫بعقوبــة مقــررة يف النظــام جلرميــة أخــرى ‪ ،‬وحيــث إن االســتعمال لــم يــرد‬\n     ‫لــه نــص عقابــي يف نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬فإنــه‬\n     ‫ال يســوغ االســتناد يف معاقبتــه علــى عقوبــة مقــررة يف األصــل للحيــازة‬\n     ‫والبيــع ونحــوه ‪ ،‬كمــا هــو مضمــون دعــوى املدعــي العــام ‪ ،‬وهــذا األمــر‬\n     ‫مــن املســائل الثابتــة ‪ ،‬بــل إن النظــام األساســي للحكــم نــص يف املــادة‬\n     ‫الثامنــة والثالثــن منــه علــى أن (العقوبــة شــخصية وال جرميــة وال عقوبــة‬\n     ‫إال بنــاء علــى نــص شــرعي أو نــص نظامــي وال عقــاب إال علــى األعمــال‬\n     ‫الالحقــة للعمــل بالنــص النظامــي (ولذلــك فــإن الســند الصحيــح ملعاقبــة‬\n\n\n‫‪91‬‬\n\f‫املدعــى عليــه هــو إقامــة احلــد عليــه فيمــا يتعلــق باســتعمال احلشــيش و‬\n‫التعزيــر فيمــا يتعلــق بتعاطــي احلبــوب احملظــورة املقــرر‪ ،‬وبعــد اإلطــاع‬\n‫علــى املــادة الثانيــة والســتني مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة‪ ،‬وبنــاء علــى مــا قــرره أهــل العلــم مــن دخــول التعزيــر يف احلــد ‪،‬‬\n‫وذلــك فيمــا يتعلــق باســتعمال املدعــى عليــه الســابق للحشــيش واحلبــوب‬\n‫احملظــورة ‪ ،‬وبعــد اإلطــاع علــى محضــر القبــض علــى املدعــى عليــه‬\n‫املرفــق ‪ ،‬ونظــرا لوجــود ســابقة علــى املدعــى عليــه ‪ ،‬ونظــرا لظهور بوادر‬\n‫التوبــة والنــدم علــى املدعــى عليــه ‪ ،‬واعترافــه مؤخــرا مبــا صــدر منــه ‪،‬‬\n‫لــكل مــا تقــدم فقــد ثبــت لــدي قيــام املدعــى عليــه بترويــج ســت حبــات‬\n‫مــن احلبــوب احملظــورة عــن طريــق البيــع للمــرة األولــى ‪ ،‬وتعاطيــه الســابق‬\n‫للحشــيش املخــدر واحلبــوب احملظــورة وتســتره علــى مصدرهمــا ‪،‬‬\n‫ومقاومتــه لرجــال األمــن ومحاولــة الهــرب منهــم ‪ ،‬وقــررت مــا يلي ‪ :‬أوال‪/‬‬\n‫جلــد املدعــى عليــه ثمانــون جلــدة دفعــة واحــدة حــد املســكر أمــام مــأ‬\n‫مــن املســلمني‪ .‬وصــرف النظــر عــن دعــوى املدعــي العــام بتطبيــق املــادة‬\n‫احلاديــة واألربعــن مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫فيمــا يتعلــق بتعاطيــه احلبــوب احملظــورة يف الســابق ‪ .‬ثانيــا‪ /‬تعزير املدعى‬\n‫عليــه لقــاء قيامــه بترويــج احلبــوب احملظــورة بســجنه خمــس ســنوات مــن‬\n‫تاريــخ إيقافــه يف هــذه القضيــة وجلــده خمســمائة جلــدة مفرقــة علــى‬\n‫دفعــات كل دفعــة خمســون جلــدة بــن الدفعــة واألخــرى شــهرا وبغرامــة‬\n‫قدرهــا ألفــا ريالــ‪ . 2000‬ثالثــا‪ /‬تعزيــر املدعــى عليــه لقــاء تســتره علــى‬\n‫مصــدر احلشــيش واحلبــوب احملظــورة بجلــده خمســون جلــدة دفعــة واحــدة‬\n‫‪ .‬رابعــا‪ /‬تعزيــر املدعــى عليــه لقــاء مقاومــة رجــال األمــن ومحاولــة الهــرب‬\n‫منهــم بجلــدة خمســون جلــدة دفعــة واحــدة ‪ .‬خامســا‪ /‬منــع املدعــى عليــه‬\n\n\n                                                                                       ‫‪92‬‬\n\f     ‫مــن الســفر خــارج اململكــة بعــد انتهــاء محكوميتــه مــدة خمــس ســنوات‬\n     ‫‪ .‬سادســا‪ /‬مصــادرة جهــاز اجلــوال مــن نــوع ‪ ....‬ذي الرقــم(‪ )........‬وشــريحة‬\n     ‫اجلــوال ذات الرقــم (‪ )........‬مــع إبــاغ الشــركة بعــدم صــرف الشــريحة‬\n     ‫الســابقة لــذات املشــترك مــرة أخــرى ‪ .‬ســابعا ‪ /‬رد املبلــغ احلكومــي‬\n     ‫املرقــم وقــدره مائتــا ريال ــ‪ . 200‬وبجميــع مــا تقــدم حكمــت وبعرضــه‬\n     ‫علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر املدعــى العــام عدمهــا‬\n     ‫فجــرى إفهامــه بأنــه ســيجري تســليمه نســخة مــن احلكــم بتاريــخ‬\n     ‫‪1433/7/1‬ه ـ إلبــداء معارضتــه عليــه يف مــدة أقصاهــا ثالثــون يومــا مــن‬\n     ‫تاريــخ تســجيله وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر‬\n                                                                 ‫يف ‪1433/06/24‬هـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافق‪1434/02/23‬هـ فتحت‬\n     ‫اجللســة بنــاء علــى خطــاب فضيلــة رئيــس محكمــة االســتئناف بالريــاض‬\n     ‫املســاعد رقــم ‪ 332074192‬وتاريــخ ‪1434/2/13‬ه ـ واملرفــق بــه قــرار‬\n     ‫أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثانيــة رقــم ‪3421522‬‬\n     ‫وتاريــخ ‪1434/1/25‬ه ـ واملتضمــن مانصــه ‪« :‬وبدراســة القــرار وصــورة‬\n     ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا باألكثريــة إعــادة‬\n     ‫املعاملــة لفضيلتــه ملالحظــة أن ماحكــم بــه مــن تعزيــر عــن ترويــج‬\n     ‫احلبــوب احملظــورة كثيــر لقلــة احلبــوب املروجــة فهــي ســت حبــات مــن‬\n     ‫االمفيتامــن فقــط وال تنطبــق عليهــا الفقــرة (ج) مــن البنــد الثانــي مــن‬\n     ‫املــادة (‪ )38‬واألولــى معاملتــه مبوجــب املــادة (‪ )60‬مــن النظــام واهلل‬\n     ‫املوفق»عليــه أجيــب أصحــاب الفضيلــة حفظهــم اهلل تعالــى أن اجلــزاء‬\n     ‫التعزيــري احملكــوم بــه علــى املدعــى عليــه ليــس بكثيــر إذ أنــه كان‬\n     ‫وفقــا للحــد األدنــى مــن العقوبــة املقــررة علــى ترويــج املخــدرات للمــرة‬\n\n\n‫‪93‬‬\n\f‫األولــى ولــم يظهــر لنــا مــا يقتضــي التخفيــف علــى املدعــى عليــه طبقــا‬\n‫للمــادة املذكــورة الســيما وأن املدعــى عليــه مــن أصحــاب الســوابق ‪،‬‬\n‫وجرميــة الترويــج ضررهــا متعــد بخــاف جرميــة االســتعمال ‪ ،‬وال يخفــى‬\n‫علــى أصحــاب الفضيلــة انتشــار هــذه اآلفــة يف املجتمــع بشــكل الفــت‬\n‫للنظــر والشــك أن العقوبــات الرادعــة هــي مــن أكبــر األســباب بعــد‬\n‫توفيــق اهلل للحــد مــن هــذا البــاء وبالتالــي فالزلــت علــى مــا حكمــت بــه‬\n‫وقــررت إعــادة املعاملــة حملكمــة االســتئناف حســب التعليمــات وبــاهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد ‪ .‬حــرر يف ‪1434/2/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة باخلــرج املكلــف برقــم‬\n‫‪ 34/688644‬وتاريــخ ‪1434/3/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪........ /‬املســجل برقــم ‪33335630‬‬\n‫وتاريــخ ‪1433/7/9‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪........ /‬‬\n‫التهامــه بقضيــة مخــدرات علــى النحــو املوضــح بالقــرار املتضمــن‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه وحيــث ســبق دراســة القــرار‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى‬\n‫مــا أجــاب بــه فضيلته على قرارنا رقــم ‪ 3421522‬وتاريخ‪1434/1/25‬هـ‬\n‫قررنــا املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه لذكــر املــدة بــن‬\n‫احلــد والتعزيــر ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه‬\n                                                               ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪94‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":81,"source_page_end":94,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"634119c948ac641baeef730fcc5834ece27f9e0b1441bef436a5cf29c23f762f","normalized_text_hash":"0550e996146710704efb5ad00e8f826b12697acd1ac1680782592883863dc3aa","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p81-33335630"},{"id":"2da2cd18-9c31-57ed-99c7-3b05f2c70480","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -ترويج احلبوب احملظورة - حيازة مسكر -حيازة احلبوب احملظورة بقصد الترويج -شرب املسكر -تعاطي احلبوب احملظورة -تعاطي احلشيش -الشروع يف استالم احلبوب احملظورة -إقامة حد املسكر -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة.","document_number":"33450333","case_number":"33193027","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/10","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -ترويج احلبوب احملظورة - حيازة مسكر -حيازة احلبوب احملظورة بقصد الترويج -شرب املسكر -تعاطي احلبوب احملظورة -تعاطي احلشيش -الشروع يف استالم احلبوب احملظورة -إقامة حد املسكر -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33450333:‬تاريخه ‪1433/11/10 :‬هـ‬\n                          ‫رقم الدعوى‪33193027:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n         ‫االستئناف‪ 3437808:‬تاريخه ‪1434/2/16‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر‪ -‬ترويــج احلبــوب احملظــورة ‪-‬‬\n      ‫حيــازة مســكر ‪ -‬حيــازة احلبــوب احملظــورة بقصــد الترويــج ‪ -‬شــرب‬\n      ‫املســكر ‪ -‬تعاطــي احلبــوب احملظــورة ‪ -‬تعاطــي احلشــيش ‪ -‬الشــروع يف‬\n      ‫اســتالم احلبــوب احملظــورة ‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر بالســجن‬\n                         ‫واجللــد والغرامــة واملنــع مــن الســفر واملصــادرة‪.‬‬\n\n\n\n      ‫‪ -1‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫العقليــة ‪.‬‬\n      ‫‪ -2‬الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫العقليــة ‪.‬‬\n      ‫‪ -3‬الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫العقليــة ‪.‬‬\n      ‫‪ -4‬الفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫العقليــة ‪.‬‬\n      ‫‪ -5‬الفقــرة (‪ )1‬مــن املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫العقليــة ‪.‬‬\n\n\n\n\n‫‪95‬‬\n\f‫ادعــى املدعــي العــام ضــد املدعــى عليهــم ‪ ،‬االول‪ :‬بالشــروع يف اســتالم‬\n‫احلبــوب احملظــورة بقصــد االجتــار و شــرب اخلمــر ‪ ،‬الثانــي‪ :‬وهــو رجــل‬\n‫أمــن يبيــع قطعــة مــن احلشــيش وعــدد مــن حبــوب االمفيتامــن بقصــد‬\n‫االجتــار ‪ ،‬حيــازة عــدد مــن علــب مشــروب غــازي مليئــة باخلمــر بقصــد‬\n‫التعاطــي واالجتــار وشــرب املســكر وحيــازة حشــيش وحبــوب محظــورة‬\n‫بقصــد التعاطــي واالجتــار وتعاطــي احلشــيش واحلبــوب احملظــورة‪.‬‬\n‫الثالــث‪ :‬الشــروع يف اســتالم احلبــوب احملظــورة بقصــد االجتــار‪ .‬حيــث‬\n‫مت القبــض علــى املدعــى عليــه الثانــي بنــاء علــى بــاغ مــن أحــد املصــادر‬\n‫الســرية عــن قيامــه بترويــج احلشــيش املخــدر واحلبــوب املنبهــة احملظــورة‬\n‫واتصــل املصــدر علــى جوالــه واتفــق معــه علــى شــراء كميــة من احلشــيش‬\n‫وعــدد مــن احلبــوب املنبهــة احملظــورة ومتــت عمليــة االســتالم والتســليم‬\n‫للحشــيش وعــدد مــن حبــوب االمفيتامــن‪ ،‬ثــم خــرج املدعــي عليــه الثانــي‬\n‫واســتقل ســيارة فتــم القبــض عليــه وبتفتيشــه عثــر علــى جــزء مــن املبلــغ‬\n‫املرقــم وبتفتيــش الســيارة عثــر علــى علــب كحــول وبالدخــول ملنزلــه عثــر‬\n‫علــى عــدد مــن احلبــوب االمفيتامــن وعــدد مــن علــب مشــروب غــازي‬\n‫مليئــة بالكحــول وبعــد ذلــك ورد اتصــال مــن شــخص آخــر علــى جــوال‬\n‫املدعــي عليــه وطلــب منــه كميــه مــن احلبــوب واخلمر‪،‬واتفــق معــه علــى‬\n‫أن يقابلــه أحــد األشــخاص وعلــى الفــور ثــم االنتقــال للموقــع وحضــر‬\n‫املدعــي عليــه األول علــى ســيارة فتــم القبــض عليــه ويرافقــه املدعــي‬\n‫عليــه الثالــث وهــو الشــخص الــذي تواصــل مــع املتصــل واعتــرف أنــه‬\n‫حضــر للموقــع الســتالم كميــة مــن احلبــوب احملظــورة وطلــب املدعــي‬\n\n                                                                                    ‫‪96‬‬\n\f     ‫العــام إثبــات مــا أســند للمدعــى عليهــم وطلــب احلكــم عليهــم بعقوبــة‬\n     ‫الســجن واجللــد والغرامــة ‪ ،‬التشــديد علــى املدعــي عليــه الثانــي كونــه‬\n     ‫عســكريا ومنعهــم مــن الســفر ومصــادرة الســيارتني ومصــادرة الهاتــف‬\n     ‫اجلــوال املشــار إليــه وعــدم صــرف الشــريحة لنفــس املشــترك ومصــادرة‬\n     ‫املبلــغ املضبــوط مــع املدعــي عليــه األول واحلكــم علــى املدعــى عليــه‬\n     ‫األول والثانــي بحــد املســكر واملطالبــة باملبلــغ املرقــم ‪ ،‬أقــر املدعــى‬\n     ‫عليــه األول بشــرب املســكر ‪ ،‬وأنــه قبــض عليــه يف ســيارته ويرافقــه‬\n     ‫املدعــى عليــه الثالــث حيــث طلــب منــه إيصالــه وقــرر أنــه ال يعلــم عــن‬\n     ‫هــذه احلبــوب أي شــيء وأنــه لــم يحضــر الســتالمها وأجــاب املدعــى عليــه‬\n     ‫الثانــي باملصادقــة علــى الدعــوى ‪ ،‬وقــرر املدعــى عليــه الثالــث أن املدعى‬\n     ‫عليــه األول أوصلــه بســيارته وال يعلــم أنــه كان ذاهــب الســتالم احلبــوب‬\n     ‫‪،‬كمــا جــرى االطــاع علــى محضــر القبــض والضبــط والتفتيــش‬\n     ‫وجــرى ســؤال املدعــى عليــه األول عــن املبلــغ املضبــوط بحوزتــه فقــرر‬\n     ‫أنــه نــاجت عــن بيــع ســيارته وجــرى الرجــوع إلــى اعتــراف املدعــى عليــه‬\n     ‫الثالــث حتقيق ـ ًا ‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر‬\n     ‫املدعــى عليــه االول بالســجن واجللــد وجلــده حــد املســكر ثمانــن جلــدة‬\n     ‫علن ـ ًا مبجمــع مــن النــاس وعــدم اســتحقاق املدعــي العــام ملــا طلبــه مــن‬\n     ‫مصــادرة املبلــغ املضبــوط مــع املدعــى عليــه األول لعــدم وجــود البينــة‬\n     ‫القاطعــة التــي تســتدعي مصادرتــه ‪ ،‬واحلكــم علــى املدعــى عليــه الثانــي‬\n     ‫بحــد املســكر وبتعزيــره بالســجن واجللــد والغرامــة واملنــع مــن الســفر‬\n     ‫ومصــادره ســيارته وهاتفــه اجلــوال وإســقاط شــريحته وإلزامــه بدفــع‬\n     ‫مالــم يعثــر عليــه مــن املبلــغ احلكومــي املرقــم ‪ ،‬احلكــم علــى املدعــى‬\n     ‫عليــه الثالــث بتعزيــره بالســجن واجللــد والغرامــة واملنــع مــن الســفر‬\n\n\n‫‪97‬‬\n\f                                 ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫اجلزائيــة‬\n   ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..‬القاضــي يف احملكمــة‬\n‫بالدمــام و يف يــوم الثالثــاء املوافق‪1433/05/25‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 1.27‬وفيهــا قــدم املدعــي العــام ‪..‬دعــواه ضــد املدعــى عليهــم‬\n‫ا فيهــا باالطــاع علــى محضــر االنتقــال‬     ‫األول ‪ .. :‬و‪.. : ..‬والثالــث ‪ .. :‬قائـ ً‬\n‫والقبــض والتفتيــش املعــد مــن قبــل رجــال مكافحــة املخــدرات تبــن أنــه‬\n‫ـاء علــى بــاغ مــن أحــد‬\n                        ‫بتاريخ‪1433/1/19‬ه ـ مت القبــض علــى املتهــم ‪..‬بنـ ً‬\n‫املصــادر الســرية عــن قيامــه بترويــج احلشــيش املخــدر واحلبــوب املنبهــة‬\n‫واحملظــورة وباتصــال املصــدر علــى جوالــه رقــم( ‪ )..‬اتفــق معــه علــى شــراء‬\n‫كميــة مــن احلشــيش املخــدر مببلــغ مائتــن وخمســن ريــاال وعــدد (‪)25‬‬\n‫خمــس وعشــرين حبــة مــن احلبــوب املنبهــة واحملظــورة فوافقــه علــى ذلــك‬\n‫ومت تكليــف أحــد األعضــاء ملرافقــة املصدر وباالنتقال إلى املوقع املتفق‬\n‫عليــه نــزل املصــدر وتقابــل مــع أحــد األشــخاص ثــم رجــع وســلم املرافــق‬\n‫قطعــة تــزن (‪ )9,8‬تســعة جرامــات وثمانيــة مــن العشــرة مــن اجلــرام وعــدد‬\n‫(‪ )25‬خمســة وعشــرين حبــة أثبــت التقريــر الكيمــاوي الشــرعي رقــم‬\n‫(‪ 314‬ك ش) لعــام ‪1433‬ه ـ إيجابيــة عينــة القطعــة ملــادة احلشــيش املخــدر‬\n‫وعينــة احلبــوب ملــادة األمفيتامــن املنبهــة واحملظــورة ثــم خــرج املذكــور‬\n‫ال ســيارة مــن نــوع ‪ ....‬حتمــل لوحــة (‪ )..-....‬وبالقبــض عليــه اتضــح‬    ‫مســتق ً‬\n‫أنــه ‪ ...‬وبتفتيشــه ُعثــر بجيبــه علــى جــزء مــن املبلــغ املرقــم قــدره (‪)100‬‬\n‫ريــال وبتفتيــش الســيارة ُعثــر علــى عــدد(‪ )312‬ثالثمائــة واثنــا عشــر علبة‬\n‫مليئــة بســائل أثبــت التقريــر الكيمــاوي املشــار إليــه احتــواء عينتهــا علــى‬\n\n                                                                                          ‫‪98‬‬\n\f     ‫مــادة الكحــول اإليثيلــي بنســب ٍة مســكرة ومبناقشــته اعتــرف بوجــود‬\n     ‫كميــة مــن املــواد املخــدرة مبنزلــه وبالدخــول ملنزلــه ُعثــر حتــت الكنــب‬\n     ‫علــى (‪ )337.1‬ثالثمائــة وســبعة وثالثــن جرام ـ ًا وواحــد مــن العشــرة‬\n     ‫مــن اجلــرام أثبــت التقريــر الكيمــاوي الشــرعي إيجابيــة عينتهــا ملــادة‬\n     ‫احلشــيش املخــدر وعــدد (‪ )593‬خمســمائة وثالثــة وتســعني حبــة أثبــت‬\n     ‫التقريــر الكيمــاوي الشــرعي إيجابيــة عينتهــا ملــادة األمفيتامــن املنبهــة‬\n     ‫واحملظــورة وعــدد (‪ )22‬علبــة مشــروب غــازي مليئــة بســائل أثبــت التقرير‬\n     ‫الكيمــاوي الشــرعي احتــواء عينتهــا علــى مــادة الكحــول اإليثيلــي‬\n     ‫بنســب ٍة مســكرة وأنــه مغــرر بــه مــن قبــل شــخص آخــر وأن هــذه املــواد‬\n     ‫تعــود لذلــك الشــخص وبعدهــا ورد اتصــال مــن شــخص يدعــى ‪..‬وطلــب‬\n     ‫منــه حتــت مســمع الفرقــة أن يجهــز(‪ )400‬أربعمائــة حبــة إليصالهــا ألحــد‬\n     ‫األشــخاص وأنــه ســوف يرســل أحــد األشــخاص الســتالم علــب البيبســي‬\n     ‫منــه واتفــق معــه علــى أن يقابلــه أحــد األشــخاص الســتالم احلبــوب‬\n     ‫منــه علــى الشــارع التجــاري بالدمــام علــى ســيارة مــن نــوع ‪ ....‬حتمــل‬\n     ‫اللوحــة رقــم (‪ )..-..‬وعلــى الفــور مت االنتقــال إلــى املوقــع وحضــر ‪..‬علــى‬\n     ‫ســيارة ‪ ....‬فتــم القبــض عليــه ويرافقــه ‪..‬وهــو الشــخص الــذي تواصــل‬\n     ‫مــع ‪..‬وقــد اعتــرف أنــه حضــر إلــى املوقــع الســتالم كميــة مــن احلبــوب‬\n     ‫احملظــورة(‪ -1‬جــرى مخاطبــة شــعبة مكافحــة املخــدرات بخصــوص‬\n     ‫‪..‬و‪ ..‬إلجــراء التحريــات الالزمــة والكافيــة عــن املذكوريــن‪ -2.‬جــرى‬\n     ‫مخاطبــة شــعبة مكافحــة املخــدرات بشــأن القبــض علــى ‪ ..‬مبوجــب‬\n     ‫خطــاب رقــم (……………‪ ).‬وتاريــخ ‪1433/03/06‬ه ـ كــون جرميتــه‬\n                                          ‫مــن اجلرائــم الكبيــرة املوجبــة لإليقــاف ‪.‬‬\n     ‫‪ -3‬مت مخاطبــة شــعبة مكافحــة املخــدرات بشــأن حجــز املبلــغ‬\n\n\n‫‪99‬‬\n\f‫املضبــوط مــع ‪..‬للمطالبــة مبصادرتــه والســيارة ‪ ....‬التــي حتمــل اللوحــة‬\n‫رقــم (‪ )..-..‬مبوجــب خطــاب رقــم ( ‪)11724‬وتاريــخ ‪1433/03/06‬ه ـ )‬\n‫وباســتجوابهم اعتــرف ‪..‬بصحــة واقعــة ضبطــه وتســليمه أحد األشــخاص‬\n‫كميــة مــن احلشــيش املخــدر وعــدد (‪ ) 25‬خمســة وعشــرين حبــة مــن‬\n‫احلبــوب املنبهــة واحملظــورة مقابــل مبلــغ مالــي كمــا اعتــرف بحيــازة‬\n‫مــا ضبــط معــه مــن اخلمــر املســكر واحلشــيش املخــدر وأنهــا عائــدة لــه‬\n‫شــخصي ًا بقصــد االجتــار عــدا احلبــوب املنبهــة فهــي عائــدة ‪ ....‬وقــد طلــب‬\n‫منــه ‪ ....‬تســليمها ألحــد األشــخاص نافي ـ ًا عائديتهــا لــه مضيف ـ ًا تعاطيــه‬\n‫للحشــيش املخــدر يــوم القبــض عليــه والشــراب املســكر واحلبــوب‬\n‫املنبهــة علــى فتــرات متقطعــة وباســتجواب ‪ ..‬أقــر بصحــة واقعــة ضبطــه‬\n‫وأنــه حضــر الســتالم كميــة مــن احلبــوب املنبهــة واحملظــورة ُتقــدر‬\n‫ـاء علــى طلــب مــن املدعــو ‪....‬‬\n                                 ‫بحوالــي(‪ )400‬أربعمائــة حبــة مــن املدعــو ‪..‬بنـ ً‬\n‫وذلــك الســتالم احلبــوب املنبهــة والذهــاب بهــا إلــى منزلــه نافي ـ ًا تعاطيــه‬\n‫أي نــوع مــن املخــدرات وباســتجوابه ‪ ..‬أقــر بصحــة واقعــة ضبطــه وأنــه‬\n‫ـاء علــى طلــب مــن‪ ..‬إليصالــه إلــى الســوبرماركت‬           ‫حضــر إلــى املوقــع بنـ ً‬\n‫فتــم القبــض عليــه نافي ـ ًا حضــوره مــن أجــل اســتالم احلبــوب املنبهــة أو‬\n‫أي نــوع مــن املخــدرات مقــر ًا بشــرب املســكر خــارج اململكــة عنــد‬\n‫ســماع أقوالــه وقــد انتهــى التحقيــق إلــى اتهــام كل مــن ‪../3..../2./1:‬‬\n‫مبــا يلــي‪/1 :‬بيــع ‪..‬مــا وزنــه (‪ )9,8‬تســعة جرامــات وثمانيــة مــن العشــرة‬\n‫مــن اجلــرام مــن احلشــيش املخــدر وعــدد (‪ )25‬خمســة وعشــرين حبــة‬\n‫مــن حبــوب األمفيتامــن املنبهــة واحملظــورة بقصــد االجتار‪/2.‬حيــازة‬\n‫‪..‬عــدد(‪ )312‬ثالثمائــة واثنــا عشــر علبــة وعــدد (‪ )22‬اثنــن وعشــرين‬\n‫علبــة مشــروب غــازي مليئــة باخلمــر املســكر بقصــد التعاطــي واالجتــار‬\n\n\n                                                                                            ‫‪100‬‬\n\f      ‫وشــربه املســكر‪/3.‬حيازة ‪..‬مــا وزنــه (‪ )337.1‬ثالثمائــة وســبعة‬\n      ‫وثالثــن جرام ـ ًا وواحــد مــن العشــرة مــن اجلــرام مــن احلشــيش املخــدر‬\n      ‫بقصــد التعاطــي واالجتار‪/4.‬حيــازة ‪..‬عــدد(‪ )593‬خمســمائة وثالثــة‬\n      ‫وتســعني حبــة مــن احلبــوب املنبهــة واحملظــورة بقصــد االجتــار وتعاطيــه‬\n      ‫للحبــوب املنبهــة واحملظــورة واحلشــيش املخــدر وشــربه للمســكر‪/5 .‬‬\n      ‫شــروع ‪..‬و‪ ..‬يف اســتالم عــدد (‪ )400‬حبــة مــن احلبــوب املنبهــة واحملظــورة‬\n      ‫بقصــد االجتار‪/6.‬شــرب ‪..‬املســكر وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n      ‫‪ -1‬اعترافاتهــم املنــوه عنهــا املرفقــة علــى اللفــة رقــم (‪) 35-28‬بحــق ‪..‬‬\n      ‫و‪ ..‬واعتــراف ‪..‬بشــرب املســكر املــدون علــى الصفحــة (‪ )4‬مــن اللفــة‬\n      ‫(‪ -2.)1‬محضــر االنتقــال والقبــض والتفتيــش املــدون علــى الصفحــة‬\n      ‫(‪ )13-12-11‬علــى ملــف ضبــط اإلجــراءات ‪ -3.‬التقريــر الكيمــاوي‬\n      ‫الشــرعي رقــم ( ‪ -4.)42‬كبــر الكميــة املضبوطــة وتنســيق ‪..‬مــع‬\n      ‫‪..‬بإيقــاف ســيارته وركوبــه معــه وحيــازة ‪..‬ملبلــغ مالــي تزامــن مــع محاولــة‬\n      ‫إمتــام عمليــة االســتالم قرينــة علــى ارتكابــه اجلرميــة ‪ -5.‬مطابقــة الســيارة‬\n      ‫لألوصــاف التــي أعطاهــا ‪..‬ل‪ ..‬قرينــة علــى ارتــكاب‪ ..‬اجلرميــة‪ -6 .‬إقــرار‬\n      ‫‪..‬بــأن ‪..‬يعلــم باجلرميــة قبــل القبــض عليهمــا وفــق اإلقــرار املرفــق علــى اللفة‬\n      ‫(‪ )8‬قرينــة علــى ارتكابــه اجلرميــة وحيــث إن مــا أقــدم عليــه املذكــورون‬\n      ‫ـب عليــه‬ ‫وهــم بكامــل أهليتهــم املعتبــرة شــرع ًا فعــلٌ محــرم ومعاقـ ٌ‬\n      ‫شــرع ًا ونظامـ ًا أطالــب مبــا يلــي أوالً‪ :‬إثبــات مــا ُأســند إلــى ‪..‬و‪ ..‬حيــال بيــع‬\n      ‫‪..‬احلشــيش املخــدر واحلبــوب املنبهــة وحيازتــه للحبــوب املنبهــة واحملظــورة‬\n      ‫بقصــد واالجتــار والترويــج وتعاطيــه للحشــيش املخــدر واحلبــوب املنبهــة‬\n      ‫وشــروع ‪..‬و‪ ..‬يف اســتالم احلبــوب املنبهــة بقصــد االجتــار وفــق الفقــرة (‪)2‬‬\n      ‫مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واحلكــم عليهــم‬\n\n\n‫‪101‬‬\n\f‫مبــا يلــي ‪/1:‬بعقوبــة الســجن واجللــد والغرامــة وفــق الفقــرة ( ‪ ) 1‬مــن‬\n‫املــادة ( ‪) 38‬مــن النظــام وتشــديد العقوبــة علــى ‪..‬وفــق الفقــرة (‪/2‬ج)‬\n‫مــن املــادة (‪ )38‬مــن النظــام واســتناد ًا لتعميــم وزيــر الداخليــة رقــم‬\n‫(‪ 2/8346/4/5/1‬ش) وتاريخ‪1427/2/8‬ه ـ كــون احلبــوب املروجــة‬\n‫مــن مــادة األمفيتامــن املنبهــة واحملظــورة مــع مراعــاة تطبيــق الفقــرة (‪)1‬‬\n‫مــن املــادة (‪ )59‬مــن النظــام بحــق ‪..‬و‪ ..‬واملــادة (‪ )62/1‬بحــق ‪..‬و التشــديد‬\n‫علــى ‪..‬وفــق برقيــة نائــب رئيــس مجلــس الــوزراء ولــي العهــد وزيــر‬\n‫الداخليــة رقــم (‪2/19371/4/5/1‬ش) وتاريــخ ‪1429/3/24‬ه ـ كونــه‬\n‫عســكرياً‪/2.‬منعهم مــن الســفر وفــق الفقــرة (‪)1‬مــن املــادة (‪ )56‬مــن‬\n‫النظــام‪/3 .‬مصــادرة الســيارة التــي حتمــل لوحــة رقــم(‪ )..-..‬والســيارة‬\n‫التــي حتمــل اللوحــة رقــم (‪ )....-..‬مــن نــوع ‪ ....‬الســتخدامهما يف اجلرميــة‬\n‫وفق ـ ًا للفقــرة (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن النظام‪/4.‬مصــادرة جهــاز‬\n‫اجلــوال مــن نــوع ‪ ....‬املشــار إليــه يف الوقائــع الــذي يحمــل الرقــم املصنعــي‬\n‫(‪)....‬لقــاء اســتخدامه يف اجلرميــة وفــق الفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن‬\n‫النظــام وعــدم صــرف الشــريحة لنفــس املشــترك وفــق تعميــم صاحــب‬\n‫الســمو امللكــي النائــب الثانــي لرئيــس مجلــس الــوزراء وزيــر الداخليــة‬\n‫رقــم(‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ‪/5‬مصــادرة املبلــغ املضبــوط مــع‬\n‫‪..‬وقدره(‪)11043‬أحــد عشــر ألــف وثالثــة وأربعــن ريــا ًال وفــق الفقــرة (‪)2‬‬\n‫مــن املــادة (‪ )53‬مــن النظــام‪ .‬ثاني ـاً‪ :‬احلكــم علــى ‪ ..‬و‪ ..‬بحــد املســكر‬\n‫لقــاء اعترافهمــا بشــربه‪ .‬ثالثـاً‪ :‬املطالبــة باملبلــغ املرقــم وفــق تعميــم وزيــر‬\n‫الداخليــة رقــم (‪ )15980/4/5/1‬وتاريــخ ‪1428/10/23-22‬ه ـ وبــاهلل‬\n‫التوفيــق ‪ .‬ويف هــذه اجللســة حضــر املدعــى عليهمــا الثانــي ‪.. :‬ســعودي‬\n‫اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة املــدون بهــا الرقــم ‪ ..‬واملدعــى‬\n\n\n                                                                                          ‫‪102‬‬\n\f      ‫عليــه الثالــث ‪.. :‬ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة‬\n      ‫املــدون بهــا الرقــم ‪..‬وأمــا املدعــى عليــه األول ‪.. :‬فهــو مطلــق بالكفالــة‬\n      ‫ولــم يحضــر وبعــرض دعــوى املدعــي العــام علــى املدعــى عليهمــا الثانــي‬\n      ‫ا ‪ :‬مــا ذكــره املدعــي العــام‬  ‫والثالــث أجــاب املدعــى عليــه الثانــي ‪..‬قائ ـ ً‬\n      ‫يف دعــواه صحيــح فقــد بعــت علــى املصــدر قطعــة احلشــيش املخــدر‬\n      ‫املذكــورة يف الدعــوى وحبــوب األمفيتامــن املذكــورة وعددهــا ( ‪) 25‬‬\n      ‫خمســه وعشــرين حبــة وســلمت هــذه املضبوطــات للمصــدر واســتلمت‬\n                                                        ‫املبلــغ احلكومــي املرقــم وقــدره‬\n      ‫( ‪ ) 250‬مائتــان وخمســون ريــا ًال وصرفــت منــه ( ‪ ) 150‬مائــة وخمســن‬\n      ‫ريــا ًال وبقــي معــه ( ‪ ) 100‬مائــة ريــال مت أخذهــا مــن قبــل مكافحــة‬\n      ‫املخــدرات وقــد اســتخدمت هاتفــي اجلوال املذكور يف الدعوى للتنســيق‬\n      ‫لعمليــة البيــع املذكــورة كمــا اســتخدمت ســيارتي املذكــورة يف‬\n      ‫الدعــوى للحضــور للمصــدر وبيعــه املضبوطــات املذكــورة وصحيـ ٌـح أنــه‬\n      ‫ُعثر معي يف الســيارة على علب حتتوي املســكر وعددها ( ‪ ) 312‬ثالثمائة‬\n      ‫واثنــا عشــر علبــة وحيازتــي لهــا بقصــد الشــرب والترويــج وصحيـ ٌـح أنــه‬\n      ‫ُعثــر يف منزلــي علــى كميــة احلشــيش املخــدر املذكــورة يف الدعــوى‬\n      ‫وحيازتــي لهــا بقصــد التعاطــي والترويــج وصحيـ ٌـح أنــه ُعثــر يف منزلــي‬\n                  ‫علــى حبــوب األمفيتامــن املذكــورة يف الدعــوى البالــغ عددهــا‬\n      ‫( ‪ ) 593‬خمســمائة وثالثــة وتســعني حبــة وحيازتــي لهــا بقصــد الترويــج‬\n      ‫وصحيـ ٌـح أنــه ُعثــر يف منزلــي علــى علــب حتتــوي املســكر املذكــورة يف‬\n      ‫الدعــوى وعددهــا ( ‪ ) 22‬اثنــن وعشــرين علبــة وحيازتــي لهــا بقصــد‬\n      ‫الشــرب والترويــج وقــد شــربت العــرق املســكر قبــل القبــض بحوالــي‬\n      ‫يومــن وتعاطيــت احلشــيش املخــدر يف نفــس يــوم القبــض علم ـ ًا أنــه لــم‬\n\n\n‫‪103‬‬\n\f‫يســبق أن صــدر علــي حكـ ٌـم بحــد املســكر وصحيـ ٌـح أننــي تعاطيــت‬\n‫حبــوب األمفيتامــن قبــل القبــض بحوالــي شــهر وصحيـ ٌـح أنــه وردنــي‬\n‫اتصــال مــن شــخص يدعــى ‪ ..‬طلــب منــي جتهيــز ( ‪ ) 400‬أربعمائــة حبــة‬\n‫مــن حبــوب األمفيتامــن وأنــه ســوف يرســل شــخص الســتالمها ومت‬\n‫الذهــاب للموقــع املتفــق عليــه حضــر املدعــى عليــه ‪..‬ويرافقــه املدعــى‬\n‫عليــه ‪..‬اجلبــور وهــو الشــخص الــذي كان يريــد اســتالم هــذه احلبــوب ‪ .‬ثــم‬\n‫ا ‪ :‬الصحيــح أننــي أتعاطــى حبــوب‬       ‫قــرر املدعــى عليــه الثالــث ‪ ..‬قائ ـ ً‬\n‫األمفتيامــن واتصلــت علــى املدعــو ‪.. :‬وطلبــت منــه حبــوب فأخبرنــي أنهــا‬\n‫توجــد عنــد املدعــى عليــه ‪..‬وقــام ‪..‬باالتصــال علــى املدعــى عليــه ‪..‬عــن‬\n‫طريــق اجلــوال وأدخلنــي يف االتصــال بخاصيــة االتصــال اجلماعي واتفقت‬\n‫أثنــاء هــذا االتصــال علــى اســتالم هــذه احلبــوب مــن املدعــى عليــه ‪..‬ويف‬\n‫اليــوم املتفــق عليــه حضــرت للمدعــى عليــه الثانــي ‪..‬لكــي اســتلم منــه‬\n‫حبــوب األمفيتامــن املذكــورة وعددهــا ( ‪ ) 400‬أربعمائــة حبــة وكان‬\n‫قصــدي مــن ذلــك أن أقــوم بحيــازة هــذه احلبــوب الســتخدامي الشــخصي‬\n‫وغيــر صحيــح اتهامــي بقصــد الترويــج يف شــروعي باســتالمها وعنــد‬\n‫حضــوري الســتالم احلبــوب املذكــورة مت القبــض علــي‪ .‬ثم جــرى االطالع‬\n‫علــى أقــوال املدعــى عليــه الثالــث ‪..‬لــدى مكافحــة املخــدرات بالدمــام‬\n‫املدونــة علــى الصفحــات رقــم ( ‪ ) 3-2‬مــن ملــف التحقيــق املرفق باملعاملة‬\n‫علــى اللفــة رقــم ( ‪ ) 1‬وممــا تضمنتــه إقــراره أنــه تلقــى اتصــال مــن أخيــه‬\n‫‪..‬وطلــب منــه مقابلــة شــخص يدعــى ‪..‬وأن يأخــذ منــه أغــراض بينهــا لــه‬\n‫ســلف ًا بأنهــا حبــوب كمــا تضمنــت أقوالــه مــا نصــه ( مــاذا كان غرضك‬\n‫مــن اســتقبال املخــدرات ومــاذا كنــت تنــوي القيــام بــه ‪ .‬لــم أكــن أنــوي‬\n‫فعــل شــيء حتــى يقــوم أخــي ‪..‬بتوجيهــي ملــن أســلمها ) وبعــرض هــذه‬\n\n\n                                                                                      ‫‪104‬‬\n\f      ‫ا ‪ :‬لقــد اعترفــت بذلــك بســبب‬     ‫األقــوال علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫االرتبــاك وأننــي أريــد أن أخــرج نفســي ولــم أتعــرض يف ذكــري لهــذه‬\n      ‫األقــوال أي إكــراه ‪ .‬ثــم جــرى رفــع اجللســة للتأمــل وتأجلــت مبشــيئة اهلل‬\n      ‫إلــى يــوم األحــد ‪1433/6/8‬ه ـ الســاعة التاســعة والنصــف صباحـ ًا وعلى‬\n      ‫ذلــك حصــل التوقيــع واهلل املوفــق ‪ .‬احلمــد هلل وحــده ويف يــوم اإلثنــن‬\n      ‫املوافق‪1433/11/01‬ه ـ افتتحــت اجللســة الســاعة ‪ 11.15‬وفيهــا حضــر‬\n      ‫املدعــى عليهــم مبــا فيهــم املدعــى عليــه األول ‪..‬مبوجــب بيانــات ســجني‬\n      ‫الصــادر مــن ســجن الدمــام واملــدون بــه رقــم الهويــة ‪..‬وبعــرض دعــوى‬\n      ‫ا ‪ :‬صحيـ ٌـح أننــي‬ ‫املدعــي العــام علــى املدعــى عليــه األول ‪..‬أجــاب قائ ـ ً‬\n      ‫شــربت البيــرة املســكرة يف مملكــة البحريــن قبــل هــذه القضيــة‬\n      ‫بحوالــي ســبعة أشــهر ولــم يســبق أن صــدر علــي حكـ ٌـم بحــد املســكر‬\n      ‫وصحيح أنه قُ بض على يف سيارتي ‪ ....‬املذكورة يف الدعوى ويرافقني‬             ‫ٌ‬\n      ‫املدعــى عليــه ‪..‬حيــث طلــب منــي املدعــى عليــه ‪..‬أن أقوم بإيصاله للســوبر‬\n      ‫ماركــت وبالفعــل ركــب معــي وأوصلتــه لســوبر ماركــت ‪ ....‬وعنــد‬\n      ‫توقفــي مت القبــض علينــا ونحــن يف الســيارة وال أعلــم عــن هــذه احلبــوب‬\n      ‫املذكــورة أي شــيء ولــم أحضــر الســتالمها هــذه إجابتــي ثم قــرر املدعى‬\n      ‫ا بالفعــل لقــد اتصلــت علــى املدعــى عليــه ‪ ..‬لكــي يوصلنــي‬      ‫عليــه ‪..‬قائـ ً‬\n      ‫ـب الســتالم احلبــوب املذكــورة‬    ‫للســوبر ماركــت ولــم أخبــره أننــي ذاهـ ٌ‬\n      ‫يف الدعــوى ثــم جــرى االطــاع علــى إيضاحــات واقعــة القبــض والضبــط‬\n      ‫والتفتيــش املدونــة علــى الصفحــات رقــم (‪ )13-11‬مــن ملــف ضبــط‬\n      ‫إجــراءات االســتدالل يف قضايــا املخــدرات املرفــق علــى اللفــة رقــم ( ‪) 2‬‬\n      ‫مــن طيــات املعاملــة وممــا تضمنــه أنــه مت العثــور مــع املدعــى عليــه ‪..‬علــى‬\n      ‫مبلــغ وقــدره ( ‪ ) 11043‬أحــد عشــر ألفـ ًا وثالثــة وأربعــون ريــا ًال وبعــرض‬\n\n\n‫‪105‬‬\n\f‫ا لقــد كان املبلــغ‬  ‫ا فع ـ ً‬\n                             ‫ذلــك علــى املدعــى عليــه املذكــور أجــاب قائ ـ ً‬\n‫املذكــور معــي وهــو جــزء مــن قيمــة بيعــي لســيارتي ولــدي ‪ ....‬من معرض‬\n‫‪ ....‬الواقــع بالدمــام ُيثبــت ذلــك ثــم جــرى ســؤال املدعــي العــام هــل لديــه‬\n‫بينــة علــى دعــواه فيمــا يخــص املدعــى عليــه األول ‪ ..‬أو يف املبلــغ املضبوط‬\n‫معــه فقــال ‪ :‬ليــس لــدي ســوى مــا ورد يف الئحــة الدعــوى وأوراق املعاملــة‬\n‫ثــم جــرى االطــاع علــى اإلقــرار اخلطــي املرفــق علــى اللفــة رقــم ( ‪ ) 8‬مــن‬\n‫طيــات املعاملــة وممــا تضمنــه إقــرار املدعــى عليــه ‪ ...‬بأنــه تلقــى اتصــال‬\n‫مــن أخيــه ‪ ....‬وطلــب منــه التوجــه إلــى مركــز ‪ ....‬للتقابــل مــع شــخص‬\n‫وســوف يقــوم هــذا الشــخص بتســليمه حبــوب وانــه إذا اســتلمها يتوجــه‬\n‫إلــى املنــزل حلــن االتصــال بــه وإخبــاره إلــى أيــن يوصلهــا كمــا تضمــن‬\n‫اإلقــرار بــأن املدعــى عليــه ‪ ..‬توجــه للموقــع املتفــق عليــه ليقــوم باســتالم‬\n‫كميــة احلبــوب وأثنــاء وصولــه للموقــع مت القبــض عليــه وأن املدعــى عليه‬\n‫‪..‬كان علــى علــم ودرايــة بعمليــة اســتالم كمية احلبــوب املخدرة وبعرض‬\n‫ا ‪ :‬لقــد بصمــت علــى هــذا اإلقــرار‬   ‫ذلــك علــى املدعــى عليــه ‪ ..‬أجــاب قائـ ً‬\n‫واعترفــت مبــا فيــه مبحــض إرادتــي بــدون إجبــار أو إكــراه مــا عــدا أن‬\n‫املدعــى عليــه ‪ ..‬كان علــى علــم ودرايــة بعمليــة اســتالم كميــة احلبــوب‬\n‫كتــب هــذا يف اإلقــرار ثــم‬ ‫املخــدرة فلــم أعتــرف بذلــك وال أعلــم كيــف ُ‬\n‫جــرى االطــاع علــى بيانــات املدعــى عليهــم يف بدايــة الئحــة الدعــوى‬\n‫وممــا تضمنتــه أن علــى املدعــى عليــه الثالــث ‪..‬ســابقتني األولــى ســرقة‬\n‫دراجــات والثانيــة ســطو ‪ -‬النهــب وبعــرض ذلــك علــى املدعــى عليــه‬\n‫ا ‪ :‬الســابقتني املذكورتــن تخصنــي ‪ .‬وبســؤال‬               ‫املذكــور قــرر قائ ـ ً‬\n‫املدعــى عليهــم عــن مهنهــم قــرر املدعــى عليــه األول ‪ ..‬والثالــث ‪ ..‬بعملهمــا‬\n‫يف القطــاع اخلــاص وقــرر املدعــى عليــه الثانــي ‪ ..‬بأنــه عســكري ثــم‬\n\n\n                                                                                        ‫‪106‬‬\n\f      ‫جــرى ســؤال املدعــى عليــه ‪..‬بأنــه ذكــر يف اجللســة املاضيــة بأنــه يتعاطــى‬\n      ‫ا ‪ :‬قبــل القبــض‬   ‫حبــوب األمفتيامــن فمتــى كانــت آخــر مــرة فقــرر قائـ ً‬\n      ‫علــي بحوالــي أســبوع فنظــر ًا ملــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬\n      ‫صــادق املدعــى عليــه الثانــي ‪..‬علــى دعــوى املدعــي العــام وأقــر كذلــك‬\n      ‫ببيــع قطعــة احلشــيش املخــدر وحبــوب األمفيتامــن املذكــورة وأقــر‬\n      ‫باســتخدامه لهاتفــه اجلــوال وســيارته املذكــورة يف عمليــة البيــع املشــار‬\n      ‫إليهــا حســب مــا جــاء يف جوابــه وأقــر كذلــك بحيــازة املضبوطــات التــي‬\n      ‫مفصــل يف جوابــه عــن‬   ‫ُوجــدت يف منزلــه ويف ســيارته حســب مــا هــو ّ‬\n      ‫الدعــوى وأقــر بشــربه للمســكر وتعاطيــه للحشــيش املخــدر وحبــوب‬\n      ‫األمفيتامــن وحيــث أقــر املدعــى عليــه الثالــث ‪..‬باحلضــور للمدعــى عليــه‬\n      ‫الثانــي ‪ ...‬الســتالم حبــوب األمفيتامــن البالــغ عددهــا ( ‪ ) 400‬أربعمائــة‬\n      ‫حبــة وقــرر أنــه كان يريــد مــن حيــازة هــذه احلبــوب االســتخدام‬\n      ‫الشــخصي وحيــث ورد يف أقوالــه لــدى مكافحــة املخــدرات بالدمــام‬\n      ‫املشــار إليهــا يف اجللســة املاضيــة إلــى أنــه لــم يكــن ينــوي فعــل شــيء بهــذه‬\n      ‫احلبــوب حتــى يقــوم أخيــه ‪..‬بتوجيهــه ملــن يســلمها وبــرر هــذا االعتــراف‬\n      ‫مبــا ذكــره يف اجللســة املاضيــة كمــا أقــر يف هــذه اجللســة باعترافــه‬\n      ‫باإلقــرار اخلطــي املشــار إليــه أعــاه مبحــض إرادتــه مــا عــدا مــا اســتثناه‬\n      ‫بعاليــه وحيــث أن يف هــذا االعتــراف املشــار إليــه يف اجللســة املاضيــة‬\n      ‫واإلقــرار اخلطــي املشــار إليــه بعاليــه مــا يثبــت شــروع املدعــى عليــه‬\n      ‫املذكــور يف اســتالم هــذه احلبــوب بقصــد الترويــج وبعــد االطــاع علــى‬\n      ‫طيــات املعاملــة ومــن ضمنهــا التقريــر الكيمــاوي الشــرعي الصــادر مــن‬\n      ‫املركــز اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية برقــم ( ‪314‬ك ش )‬\n      ‫إيجابيــة العينتــن رقــم ( ‪ ) 33/85‬و ( ‪/85‬ج ) ملــادة احلشــيش املخــدر‬\n\n\n‫‪107‬‬\n\f‫وإيجابيــة العينتــن رقــم ( ‪/85‬أ) و ( ‪/85‬د ) ملــادة األمفيتامــن وأن‬\n‫العينتــن رقــم ( ‪/85‬ب ) و( ‪/85‬ه ـ ) عبــارة عــن علبــة مشــروب غــازي مت‬\n‫فتحهــا بطريقــة فنيــة دقيقــة ال ُتالحــظ بالعــن املجـ ّـردة ومت تفريــغ‬\n‫محتواهــا األصلــي مــن املشــروب الغــازي ثــم مت تعبئتهــا بســائل شــفاف‬\n‫وردي فــاحت اللــون حوالــي ‪355‬مــل ثــم مت غلقهــا مــرة أخــرى بطريقــة فنيــة‬\n‫دقيقــة جــد ًا حتــى تبــدو للعــن املجــردة أنهــا لــم ُتفتــح مــن قبــل وثبــت‬\n‫احتــواء الســائل علــى مــادة الكحــول اإليثيلــي وبنســب ٍة مســكرة وبعــد‬\n‫االطــاع علــى إيضاحــات واقعــة القبــض املشــار إليهــا بعاليــه وبعــد‬\n‫االطــاع علــى أقــوال املدعــى عليهــم لــدى هيئــة التحقيــق واالدعــاء العــام‬\n‫املرفقــة علــى اللفــات رقــم (‪ )35-25‬مــن طيــات املتعاملــة واملتضمنــة نحــو‬\n‫أقوالهــم املشــار إليهــا يف الدعــوى ولعــدم وجــود البينــة القاطعــة يف‬\n‫اشــتراك املدعــى عليــه ‪..‬يف الشــروع يف اســتالم حبــوب األمفيتامــن‬\n‫املذكــورة يف الدعــوى ولتوجــه التهمــة لــه يف ذلــك الســيما مــع إحضــاره‬\n‫بســيارته للمدعــى عليــه ‪ ..‬الــذي أقــر بالشــروع يف اســتالم احلبــوب‬\n‫املذكــورة وحيــث تناقضــت أقــوال املدعــى عليــه الثالــث ‪..‬يف علــم‬\n‫املدعــى عليــه األول ‪..‬باســتالم احلبــوب املذكــورة حيــث قــام بالتبصيــم‬\n‫علــى ذلــك يف اإلقــرار اخلطــي لــدى مكافحــة املخــدرات املشــار إليــه‬\n‫أعــاه بينمــا نفــى ذلــك يف أقوالــه يف هــذه اجللســة ويف ذلــك مــا يوجــه‬\n‫التهمــة يف حــق املدعــى عليــه الثالــث ‪..‬يف محاولــة التســتر علــى املدعــى‬\n‫ـاء علــى الفقــرة ( ‪ ) 2‬مــن املــادة رقــم ( ‪3‬‬\n                                             ‫عليــه األول ‪..‬يف هــذا األمــر وبنـ ً‬\n‫) والفقــرة ( ‪ ) 1‬مــن املــادة رقــم ( ‪ ) 38‬والفقــرة ( ‪ ) 1‬مــن املــادة رقــم ( ‪56‬‬\n‫) والفقــرة ( ‪ ) 1‬مــن املــادة رقــم ( ‪ ) 62‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة ولعــدم وجــود ســوابق علــى املدعــى عليــه الثالــث ‪..‬‬\n\n\n                                                                                        ‫‪108‬‬\n\f      ‫تتعلــق باملخــدرات ممــا يســتدعي إعمــال مقتضــى الفقــرة ( ‪ ) 1‬مــن املــادة‬\n      ‫رقــم ( ‪ ) 60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ولكثــرة‬\n      ‫كميــة املضبوطــات احملــازة مــع املدعــى عليــه الثانــي ‪..‬وكونــه رجــل‬\n      ‫أمـ ٍـن وكان األولــى يف حقــه حفــظ األنظمــة ورعايتهــا لذلــك كلــه فقــد‬\n      ‫قــررت مــا يلــي ‪ :‬أوالً‪ -‬لــم يثبــت لــدي إدانــة املدعــى عليه األول ‪..‬بالشــروع‬\n      ‫يف اســتالم احلبوب املذكورة يف الدعوى البالغ عدها ( ‪ ) 400‬أربعمائة‬\n      ‫حبــة لعــدم وجــود البينــة القاطعــة يف ذلــك وقــررت عــدم اســتحقاق‬\n      ‫املدعــي العــام ملــا يطلبــه مــن إيقــاع العقوبــة وفــق مقتضــى الفقــرة ( ‪) 1‬‬\n      ‫مــن املــادة رقــم ( ‪ ) 38‬مــن نظــام مكافحــة املخــدرات أو منعــه من الســفر‬\n      ‫أو مصــادرة ســيارته املشــار إليهــا يف الدعــوى وحيــث أن التهمــة متوجهــة‬\n      ‫يف حقــه يف الشــروع الســتالم هــذه احلبــوب بقصــد الترويــح ملــا ُذكــر مــن‬\n      ‫ـات أعــاه فقــد قــررت تعزيــره لقــاء هــذه التهمــة بســجنه ملــدة ســنة‬   ‫حيثيـ ٍ‬\n      ‫وســتة أشــهر ُيحســب منهــا مــدة إيقافــه علــى ذمــة القضيــة قبــل إطالقــه‬\n      ‫ـداء مــن تاريــخ إيقافــه وجلــده‬\n                                       ‫بالكفالــة وبقيــة مــدة ســجنه تكــون ابتـ ً‬\n      ‫مائتــي جلــدة مفرقــة علــى أربــع دفعــات متســاوية بــن كل دفعــة وأخــرى‬\n      ‫مــا ال يقــل عــن خمســة عشــر يومـ ًا ‪ .‬ثانيـاً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه‬\n      ‫األول ‪..‬بشــرب املســكر وقــررت جلــده حــد املســكر ثمانــن جلــدة دفعـ ًة‬\n      ‫واحــده علن ـ ًا مبجمـ ٍـع مــن النــاس علــى أن ُيفـ ّـرق بــن هــذا اجللــد واجللــد‬\n      ‫الصــادر يف حقــه يف البنــد ( أو ًال ) مبــد ٍة ال تقــل عــن خمســة عشــر يومـ ًا ‪.‬‬\n      ‫ثالث ـاً‪ -‬عــدم اســتحقاق املدعــي العــام ملــا يطالــب بــه مــن مصــادرة املبلــغ‬\n      ‫املضبــوط مــع املدعــى عليــه ‪..‬لعــدم وجــود البينــة القاطعــة التــي تســتدعي‬\n      ‫مصادرتــه ‪ .‬رابع ـاً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه الثانــي ‪..‬ببيــع قطعــة‬\n      ‫احلشــيش املخــدر املذكــورة يف الدعــوى البالــغ وزنهــا ( ‪ ) 9.8‬تســعة‬\n\n\n‫‪109‬‬\n\f‫جرامــات وثمانيــة مــن العشــرة مــن اجلــرام وكذلــك بيــع حبــوب‬\n‫األمفيتامــن املشــار إليهــا يف الدعــوى البالــغ عددهــا ( ‪ ) 25‬خمســه‬\n‫وعشــرين حبــة كمــا ثبــت لــدي إدانتــه بحيــازة كميــة احلشــيش املخــدر‬\n‫املذكــورة يف الدعــوى البالــغ وزنهــا ( ‪ ) 337.1‬ثالثمائــة وســبعه وثالثــن‬\n‫جرامـ ًا وواحــد مــن العشــرة مــن اجلــرام بقصــد الترويــج كمــا ثبــت لــدي‬\n‫إدانتــه بحيــازة حبــوب األمفيتامــن املذكــورة يف الدعــوى البالــغ عددهــا‬\n‫( ‪ ) 593‬خمســمائة وثالثة وتســعني حبة بقصد الترويج وقررت معاقبته‬\n‫ـداء مــن تاريــخ‬\n             ‫علــى ذلــك كلــه مبــا يلــي ‪ :‬أ‪ -‬ســجنه ملــدة ثمــان ســنوات ابتـ ً‬\n‫إيقافــه وجلــده ســبعمائة جلــدة مفرقــة علــى أربعــة عشــر دفعــة بــن كل‬\n       ‫دفعة وأخرى ما ال يقل عن خمسة عشر يوم ًا وتغرميه مبلغ ًا وقدره‬\n‫( ‪ ) 10000‬عشــرة آالف ريــال ‪ .‬ب‪ -‬منعــه مــن الســفر ملــدة ثمــان ســنوات‬\n‫تبــدأ بعــد انتهــاء مــدة الســجن املقــررة يف حقــه يف الفقــرة ( أ ) مــن هــذا‬\n‫البنــد ‪ .‬ج‪ -‬مصــادرة ســيارته املذكــور نوعهــا ورقــم لوحتهــا يف الدعــوى‬\n‫وكذلــك هاتفــه اجلــوال املذكــور نوعــه ورقمــه املصنعــي يف الدعــوى‬\n‫الســتخدامهما يف عمليــة البيــع املذكــورة مــع إســقاط شــريحة الهاتــف‬\n‫اجلــوال وعــدم صرفهــا لنفــس املدعــى عليــه ‪ .‬خامس ـاً‪ -‬إلــزام املدعــى‬\n‫عليــه الثانــي ‪..‬بدفــع مــا لــم ُيعثــر عليــه مــن املبلــغ احلكومــي املرقــم‬\n‫وقــدره ( ‪ ) 150‬مائــة وخمســون ريــا ًال وذلــك للجهــة املختصــة ‪ .‬سادسـاً‪-‬‬\n‫ثبــت لــدي إدانــة املدعــى عليــه الثانــي ‪..‬بحيــازة مــا ُأشــير إليــه يف البنــد‬\n‫( رابع ـ ًا ) مــن قطعــة احلشــيش املخــدر البالــغ وزنهــا ( ‪ ) 337.1‬ثالثمائــة‬\n‫وســبعه وثالثــن جرامـ ًا وواحــد مــن العشــرة مــن اجلــرام بقصــد التعاطــي‬\n‫باإلضافــة للترويــج وعقوبتــه يف ذلــك داخلــة يف العقوبــة الصــادرة يف حقــه‬\n                          ‫ـاء بالعقوبــة األشــد‪.‬‬\n                                                ‫فقــرات البنــد ( رابع ـ ًا ) اكتفـ ً‬\n\n                                                                                         ‫‪110‬‬\n\f      ‫ســابعاً‪-‬ثبت لــدي إدانــة املدعــى عليــه الثانــي ‪..‬بحيــازة علــب املســكر‬\n      ‫املذكــورة يف الدعــوى و التــي ُوجــدت يف ســيارته وعددهــا ( ‪) 312‬‬\n      ‫ثالثمائــة واثنتــا عشــرة علبــة وكذلــك علــب املســكر املذكــورة يف‬\n      ‫الدعــوى والتــي ُوجــدت يف منزلــه وعددهــا ( ‪ ) 22‬اثنــن وعشــرين علبــه‬\n      ‫وذلــك كلــه بقصــد الترويــج والشــرب وعقوبتــه يف ذلــك داخلـ ٌة يف عقوبة‬\n      ‫الســجن واجللــد الصــادرة يف حقــه يف الفقــرة ( أ ) مــن البنــد ( رابع ـ ًا ) ‪.‬‬\n      ‫ثامنـاً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه الثانــي ‪ ..‬بشــرب املســكر وقــررت‬\n      ‫جلــده حــد املســكر ثمانــن جلــدة دفعـ ًة واحــده علنـ ًا مبجمـ ٍـع مــن النــاس‬\n      ‫علــى أن ُيفـ ّـرق بــن هــذا اجللــد واجللــد الصــادر يف حقــه يف الفقــرة ( أ )‬\n      ‫مــن البنــد ( رابعـ ًا ) مبــد ٍة ال تقــل عــن خمســة عشــر يومــا ‪ .‬تاســعاً‪ -‬ثبــت‬\n      ‫لــدي إدانــة املدعــى عليــه الثانــي ‪..‬بتعاطــي احلشــيش املخــدر واكتفيــت‬\n      ‫مبــا صــدر عليــه مــن حــدٍ للمســكر املذكــور يف البنــد ( ثامنـ ًا ) كمــا‬\n      ‫اكتفيــت مبــا صــدر عليــه مــن منـ ٍـع مــن الســفر املذكــور يف الفقــرة‬\n      ‫( ب ) مــن البنــد ( رابع ـ ًا ) ‪ .‬عاشــراً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه‬\n      ‫الثانــي ‪..‬بتعاطــي حبــوب األمفيتامــن واكتفيــت مبــا صــدر عليــه مــن‬\n      ‫حــدٍ للمســكر املذكــور يف البنــد ( ثامنـ ًا )عــن تعزيــره لقــاء ذلــك كمــا‬\n      ‫اكتفيــت مبــا صــدر عليــه مــن منـ ٍـع مــن الســفر املذكــور يف الفقــرة ( ب )‬\n      ‫مــن البنــد ( رابعـ ًا ) حــادي عشــر‪ -‬ثبــت لــدي إدانــة املدعــى عليــه الثالــث‬\n      ‫‪..‬بالشــروع يف اســتالم عــدد ( ‪ ) 400‬أربعمائــة حبــة مــن احلبــوب احملظــورة‬\n      ‫بقصــد الترويــج وقــررت معاقبتــه علــى ذلــك مبــا يلــي ‪ :‬أ‪ -‬ســجنه ملــدة‬\n      ‫ـداء مــن تاريــخ إيقافــه وجلــده أربعمائــة جلــدة مفرقــة‬  ‫أربــع ســنوات ابتـ ً‬\n      ‫علــى ثمــان دفعــات بــن كل دفعــة وأخــرى مــا ال يقــل عــن خمســة عشــر‬\n      ‫يوم ـ ًا وتغرميــه مبلغ ـ ًا وقــدره ( ‪ ) 4000‬أربعــة آالف ريــال ‪ .‬ب‪ -‬منعــه مــن‬\n\n\n‫‪111‬‬\n\f‫الســفر ملــدة أربــع ســنوات تبــدأ بعــد انتهــاء مــدة الســجن الصــادرة يف‬\n‫حقــه يف الفقــرة ( أ ) مــن هــذا البنــد ‪ .‬ثانــي عشــر‪ -‬توجــه التهمــة يف حــق‬\n‫املدعــى عليــه الثالــث ‪ ..‬مبحاولــة التســتر علــى املدعــى عليــه األول ‪..‬يف‬\n‫علمــه باســتالم احلبــوب احملظــورة املشــار إليهــا يف الدعــوى وعقوبتــه يف‬\n‫ذلــك داخلـ ٌة يف عقوبــة الســجن واجللــد الصــادرة يف حقــه يف الفقــرة ( أ )‬\n‫مــن البنــد ( احلــادي عشــر ) ثالــث عشــر ‪ -‬ثبــت لــدي إدانــة املدعــى عليــه‬\n‫الثالــث ‪..‬بتعاطــي حبــوب األمفيتامــن وقــررت تعزيــره لقــاء ذلــك بجلــده‬\n‫خمســه وســبعني جلــد ًة دفعـ ًة واحــده علــى أن ُيفــرق بــن هــذا اجللــد واجللــد‬\n‫الصــادر يف حقــه يف الفقــرة ( أ ) مــن البنــد ( احلــادي عشــر ) مبــد ٍة ال تقــل‬\n‫عــن خمســة عشــر يومـ ًا واكتفيــت مبــا صــدر عليــه مــن منـ ٍـع مــن الســفر‬\n‫املذكــور يف الفقــرة ( ب ) مــن البنــد ( احلــادي عشــر ) وبذلــك أجمــع‬\n‫حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه األول‬\n‫‪..‬والثالــث ‪..‬القناعــة وقــرر املدعــى عليــه الثانــي ‪..‬االعتــراض بالئحــة‬\n‫اعتراضيــة مقدم ـ ًة منــه ف ُأجيــب لطلبــه وجــرى إفهامــه أنــه ســوف يتــم‬\n‫طلبــه يــوم األربعــاء ‪1433/11/10‬ه ـ لتســليمه صــورة مــن احلكــم وأنــه‬\n‫يف التاريــخ املشــار إليــه ســوف يتــم إيــداع القــرار ملــف الدعــوى وســوف‬\n‫يكــون ذلــك اإليــداع مجريـ ًا مليعــاد الثالثــن يومـ ًا يقــدم خاللــه الئحتــه‬\n‫االعتراضيــة وأنــه مبضيهــا دون تقــدمي الالئحــة ســوف يســقط حقــه‬\n‫ويرفــع احلكــم حملكمــة االســتئناف بدونهــا فامتثــل وقــرر‬           ‫يف تقدميهــا ُ‬\n‫املدعــي العــام االعتــراض وطلــب رفــع احلكــم حملكمــة االســتئناف‬\n‫واكتفــى بالئحــة الدعــوى وأوراق املعاملــة عــن تقــدمي الئحـ ٍة اعتراضيــة‬\n‫ف ُأجيــب لطلبــه واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األربعــاء املوافق‪1433/11/10‬ه ـ‬\n\n\n                                                                                         ‫‪112‬‬\n\f      ‫افتتحــت اجللســة الســاعة ‪ 11.15‬وفيهــا حضــر املدعــى عليــه الثانــي‬\n      ‫‪..‬وجــرى تســليمه صــورة مــن احلكــم الصــادر برقــم ‪ 33450333‬يف‬\n      ‫‪1433/11/10‬ه ـ املكــون مــن ( ‪ ) 8‬ثمــان صفحــات وجــرى إفهامــه أنــه‬\n      ‫بتاريــخ اليــوم ســوف يتــم إيــداع القــرار ملــف الدعوى وســوف يكون ذلك‬\n      ‫اإليــداع مجري ـ ًا ملــدة الثالثــن يوم ـ ًا يقــدم خاللهــا الئحتــه االعتراضيــة‬\n      ‫ويرفــع‬\n            ‫وأنــه مبضيهــا دون تقــدمي الالئحــة ســوف يســقط حقــه يف تقدميهــا ُ‬\n      ‫احلكــم حملكمــة االســتئناف بدونهــا فامتثــل واهلل املوفــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪ .‬احلمــد هلل وحــده وبعــد ويف يــوم‬\n      ‫األربعــاء املوافق‪1433/12/01‬ه ـ افتتحــت اجللســة الســاعة ‪ 10.45‬وقــد‬\n      ‫ورددتنــا الالئحــة االعتراضيــة املقدمــة مــن املدعــى عليــه ‪..‬واملكونــة مــن‬\n      ‫ورقــة واحــدة واملرفقــة بخطــاب املدعــى عليــه املذكــور لفضيلــة رئيــس‬\n      ‫هــذه احملكمــة املقيــد برقــم ‪ 332104802‬يف ‪1433/11/24‬ه ـ وقــد‬\n      ‫جــرى االطــاع علــى الالئحــة االعتراضيــة ولــم أجــد فيهــا مــا يوجــب‬\n      ‫الرجــوع عمــا حكمــت بــه وســوف يتــم إرســال املعاملــة حملكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية إلكمــال الزمهــا واهلل املوفــق وصلــى اهلل‬\n                                         ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافق‪1434/03/02‬ه ـ فتحــت‬\n      ‫اجللســة وقــد وردت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫مبوجــب اخلطــاب رقــم ‪ 34193154‬يف ‪1434/02/26‬ه ـ وبرفقهــا قــرار‬\n      ‫أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثانيــة مبحكمة االســتئناف‬\n      ‫باملنطقــة الشــرقية رقــم ‪ 3437808‬يف ‪1434/02/16‬ه ـ املتضمــن‬\n      ‫املصادقــة علــى احلكــم لــذا جــرى إحلاقــه واهلل املوفــق وصلــى اهلل علــى‬\n                                                            ‫نبينــا محمــد وآلــه وســلم ‪.‬‬\n\n\n‫‪113‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":95,"source_page_end":113,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d889c5bc007bafb90fc9da070913bcf6768255f7cae9760b3baf03b09952bee2","normalized_text_hash":"26404a1ea6d08d4461a9c8ec158dd1423d588a240f1a696c0b80c9aaa27f091e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p95-33450333"},{"id":"15113947-2ecf-5f98-a705-15740c932c67","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -التوكيل يف القضايا اجلنائية -قدح يف الشهادة -توجه التهمه بالقرائن -شهادة االستغفال - التعزير بالسجن واجللد وإعادة املبلغ احلكومي .","document_number":"33431140","case_number":"33229721","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/18","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -التوكيل يف القضايا اجلنائية -قدح يف الشهادة -توجه التهمه بالقرائن -شهادة االستغفال - التعزير بالسجن واجللد وإعادة املبلغ احلكومي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33431140:‬تاريخه ‪ 1433/10/18:‬هـ‬\n                    ‫رقم الدعوى ‪33229721:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34196143‬تاريخه‪1434/4/23 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬التوكيــل يف القضايــا اجلنائيــة‬\n ‫‪ -‬قــدح يف الشــهادة ‪ -‬توجــه التهمــه بالقرائــن ‪ -‬شــهادة االســتغفال ‪-‬‬\n                    ‫التعزيــر بالســجن واجللــد وإعــادة املبلــغ احلكومــي ‪.‬‬\n\n\n\n\n        ‫‪ -1‬الصحيح يف املذهب أن شهادة االستغفال صحيحة مقبولة ‪.‬‬\n                       ‫‪ -2‬املادة (‪ )178‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه ببيــع قطعــه مــن احلشــيش املخــدر‬\n ‫بقصــد االجتــار ‪ ،‬حيــث وردت معلومــات تفيــد بــأن املدعــى عليــه يقــوم‬\n ‫بترويــج احلشــيش املخــدر مبنزلــه وأســتعد أحــد املصــادر الســرية لتنفيــذ‬\n ‫عمليــة الشــراء منــه ‪ ،‬حيــث اتصــل املصــدر علــى املدعــى عليــه و طلــب‬\n ‫منــه قطعــه حشــيش فأفــاد املدعــى عليــه بــأن طلبــه موجــود و كان‬\n ‫ذلــك علــى مســمع مــن الفــرد املرافــق ‪ ،‬مت ذهــاب املصــدر مــع العضــو‬\n ‫املرافــق ملنــزل املدعــى عليــه و متــت عمليــة االســتالم والتســليم عنــد بــاب‬\n ‫املدعــى عليــه حتــت انظــار الفــرد املرافــق و بعــد عــدة أيــام مت القبــض‬\n ‫علــى املدعــى عليــه مــن قبــل الفــرد املرافــق ‪ ،‬حيــث طلــب املدعــي العــام‬\n ‫اثبــات مــا أســند للمدعــى عليــه و احلكــم عليــه بعقوبــة الســجن واجللــد و‬\n\n                                                                                       ‫‪114‬‬\n\f      ‫الغرامــة و املنــع مــن الســفر وفــق نظــام مكافحــة املخــدرات ومصــادرة‬\n      ‫اجلــوال املســتخدم يف لعمليــة و مطالبــة الشــركة بإلغــاء الشــريحة‬\n      ‫املشــغلة و إلزامــه بدفــع املبلــغ احلكومــي املرقــم وفــق تعميــم ســمو وزيــر‬\n      ‫الداخليــة ‪ ،‬أنكــر املدعــى عليــه مــا ن ُِســب إليــه ممــا حــدا باملدعــي العــام‬\n      ‫إلحضــار الشــاهد املرافــق للمصــدر و دفــع وكيــل املدعــى عليــه بــأن‬\n      ‫هــذه شــهادة اســتغفال وال تقبــل ‪ ،‬وبنــاء علــى شــهادة الشــاهد ومحضــري‬\n      ‫القبــض والشــراء صــدر احلكــم بعــدم ثبــوت مــا نســب للمدعــى عليــه‬\n      ‫وتعزيــره لقــاء توجــه التهمــة القويــة ضــده بالســجن واجللــد وإعــادة املبلــغ‬\n      ‫احلكومــي وصــرف النظــر عــن طلــب املدعــي العــام تطبيــق املادتــن (‪38‬‬\n      ‫و ‪ )56‬مــن نظــام مكافحــة املخــدرات ومصــادرة اجلــوال وإلغاء الشــريحة‬\n                                        ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬        ‫ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بعرعــر‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بعرعــر برقــم وتاريــخ ‪ 1433/04/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫وتاريــخ ‪ 1433/04/03‬ه ـ ففــي يــوم اإلثنــن املوافــق‪1433/04/05‬‬\n      ‫ا‪:‬‬ ‫ه ـ افتتحــت اجللســة الســاعة ‪ 01 : 56‬وفيهــا حضــر ‪.‬وقــرر قائ ـ ً‬\n      ‫بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة مبنطقــة احلــدود‬\n      ‫الشــمالية أدعــي علــى ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.‬‬\n      ‫فإنــه بتاريــخ ‪1433/2/6‬ه ـ وردت معلومــات تفيــد بــأن املدعــى عليــه‬\n      ‫يقــوم بترويــج احلشــيش املخــدر مبنزلــه بحــي املســاعدية ‪ ،‬وأســتعد أحــد‬\n      ‫املصــادر الســرية لتنفيــذ عمليــة الشــراء منــه مببلــغ (‪ )100‬مائــة ريــال‪،‬‬\n\n‫‪115‬‬\n\f‫حيــث مت االتصــال علــى املدعــى عليــه ‪ ....... /‬علــى الرقــم (‪ ).....‬وطلــب‬\n‫املصــدر منــه قطعــة مــن احلشــيش املخــدر بقيمــة مائــة (‪ )100‬ريــال وكان‬\n‫ذلــك علــى مســمع مــن الفــرد املرافــق ‪ ،‬وأفــاد املدعــى عليــه بــأن طلبــه‬\n‫موجــود ‪ ،‬وطلــب مــن املصــدر احلضــور إليــه عنــد منزلــه بحــي املســاعدية‬\n‫فتــم تفتيــش املصــدر تفتيشــا دقيقــا ومت جتنيــد أحــد رجــال املكافحــة‬\n‫مــع املصــدر ملشــاهدة عمليــة االســتالم والتســليم ‪ ،‬وعنــد وصــول املصــدر‬\n‫إلــى منــزل املدعــى عليــه وجــده واقفــا أمــام بــاب منزلــه ومت الوقــوف‬\n‫بجانبــه وقــام املصــدر بالســام عليــه وإعطائــه املبلــغ احلكومــي املرقــم‬\n‫وقــام املدعــى عليــه بتســليمه قطعــة احلشــيش املخــدر البالــغ وزنهــا (‪)1,5‬‬\n‫واحــد و نصــف جــرام ‪ ،‬وكانــت عمليــة الشــراء أمــام أنظــار الفــرد‬\n‫املرافــق ‪ ،‬وبتاريــخ ‪1433/2/22‬ه ـ مت القبــض عليــه ‪ ،‬وبتفتيشــه عثــر‬\n‫بحوزتــه علــى اجلــوال الــذي مت التنســيق عليــه يف عمليــة الشــراء املســبق و‬\n‫مت التعــرف عليــه مــن قبــل الفــرد املرافــق ‪ .‬وبســماع أقــوال املدعــى عليــه‬\n‫و اســتجوابه‪ /‬أقــر بــأن رقــم اجلــوال (‪ ).....‬عائــد لــه ‪ .‬وقــد أثبــت التقريــر‬\n‫الكيميائــي الشــرعي رقــم (‪641‬م‪/‬م س ت) لعــام ‪1433‬ه ـ الصــادر مــن‬\n‫صحــة تبــوك إيجابيــة العينــة املرســلة ملــادة احلشــيش ‪ ،‬وهــو مــن املــواد‬\n‫املخــدرة اخلاضعــة للرقابــة املنــوه عنهــا باجلــدول فئــة (أ) يف تعميــم صاحب‬\n‫الســمو امللكــي وزيــر الداخليــة برقــم ( ‪ ) -‬وتاريخ‪1426/10/25‬ه ـ ‪.‬‬\n‫وقــد انتهــى التحقيــق إلــى اتهــام ‪ .....‬ببيــع قطعــة مــن احلشــيش املخــدر‬\n‫بلــغ وزنهــا (‪ )1,5‬واحــد و نصــف جــرام بقصــد االجتــار ‪ .‬وذلــك لألدلــة‬\n                                                                  ‫والقرائــن التاليــة ‪:‬‬\n‫‪ -1‬مــا جــاء بأقوالــه املدونــة علــى الصفحــة رقم (‪ )1-2‬مــن دفتر التحقيق‬\n                                                            ‫املرفــق لفة رقم (‪.)6-7‬‬\n\n\n                                                                                           ‫‪116‬‬\n\f      ‫‪ -2‬مــا جــاء مبحضــر الشــراء املــدون علــى الصفحــة رقــم (‪ )11‬مــن دفتــر‬\n                                                       ‫االســتداالل املرفــق لفــة رقــم (‪.)1‬‬\n      ‫‪ -3‬مــا جــاء مبحضــر القبــض املــدون علــى الصفحــة رقــم (‪ )12‬مــن دفتــر‬\n                                                       ‫االســتداالل املرفــق لفــة رقــم (‪.)1‬‬\n      ‫‪ -4‬مــا جــاء بالتقريــر الكيميائــي الشــرعي املرفــق لفــة رقــم (‪.)23‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرعا فعــل محــرم ومعاقــب عليــه شــرعا ومجــرم نظامــا بنــص املــادة‬\n      ‫الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬الصــادر‬\n      ‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب إثبــات‬\n                                           ‫مــا أســند إليــه واحلكــم عليــه مبــا يلــي ‪:‬‬\n      ‫‪ -1‬عقوبــة الســجن واجللــد والغرامــة وفقــا للفقــرة األولــى مــن املــادة (‪)38‬‬\n                                ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n      ‫‪ -2‬عقوبــة املنــع مــن الســفر خــارج اململكــة وفقــا للفقــرة األولــى مــن‬\n                                                        ‫املــادة (‪ )56‬مــن النظــام نفســه‪.‬‬\n      ‫‪ -3‬مصــادرة اجلــوال املســتخدم يف العمليــه وهــو مــن نــوع جاالكســي‬\n      ‫يحمــل الرقــم التسلســلي (‪ )......‬وفقــا للفقــرة األولــى مــن املــادة (‪ )53‬مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬و مطالبــة الشــركة‬\n      ‫بإلغــاء الشــريحة املشــغلة و بعــدم صرفهــا لــه للرقــم (‪ ).‬الســتخدامه يف‬\n      ‫عمليــة الترويــج وفقــا لتعميــم صاحــب الســمو امللكــي النائــب الثانــي‬\n      ‫لرئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم ( ) وتاريخ‪1428/2/10‬هــ‪.‬‬\n      ‫‪ -4‬إلزامــه بدفــع املبلــغ احلكومــي املرقــم وقــدرة مائــة (‪ )100‬ريــال وفقـ ًا‬\n      ‫لبرقيــة صاحــب الســمو امللكــي النائــب الثانــي لرئيــس مجلــس الــوزراء‬\n      ‫وزيــر الداخليــة رقــم ‪1428/10/23-22‬ه ـ ‪ .‬وحتــى حضور املدعى عليه‬\n\n\n‫‪117‬‬\n\f‫رفعــت اجللســة وصلــى اهلل علــى نبينــا محمــد حــرر يف ‪1433/04/05‬ه ـ‬\n                                                         ‫يف متــام الســاعة ‪. 02:00‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.‬القاضــي يف احملكمــة العامــة بعرعــر‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بعرعــر برقــم وتاريــخ ‪ 1433/04/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫وتاريــخ ‪ 1433/04/03‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1433/04/06‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 56‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫ا ‪ :‬مــا‬\n       ‫عليــه وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائـ ً‬\n‫جــاء يف دعــوى املدعــي العــام ضــدي فغيــر صحيــح جملــة وتفصيــا فلــم‬\n‫أقــم ببيــع مــا وزنــه (‪ )1.5‬واحــد ونــص جــرام هكــذا أجــاب وبســؤاله عن‬\n‫اجلــوال رقــم (‪ ).....‬هــل هــو عائــد لــك أجــاب بأنــه عائــد لــه وهــو خــاص بــه‬\n‫وبأســمه هكــذا أجــاب ثــم طلبــت مــن املدعــي العــام البينــه علــى دعــواه‬\n‫فوعــد بإحضارهــا يف اجللســة القادمــة لذلــك قــررت رفــع اجللســة وحــددت‬\n‫للطرفــن موعــد هــو يــوم األربعــاء املوافــق ‪1433/4/14‬ه ـ الســاعة‬\n‫التاســعة صباحـ ًا ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آله وصحبه وســلم ‪ .‬حرر يف ‪ 1433/04/06‬هـ يف متام الســاعة ‪. 10:10‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.‬القاضــي يف احملكمــة العامــة بعرعــر‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بعرعــر برقــم وتاريــخ ‪ 1433/04/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫وتاريــخ ‪ 1433/04/03‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1433/04/14‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 10 : 51‬وفيهــا حضــر املدعــي العــام وبســؤاله‬\n‫ا ‪ :‬لــم‬‫عــن بينتــه التــي وعــد بإحضارهــا يف اجللســة املاضيــة أجــاب قائ ـ ً‬\n‫أســتطع إحضارهــا يف هــذه اجللســة وأطلــب مهلــة إلحضارهــا يف اجللســة‬\n\n\n                                                                                          ‫‪118‬‬\n\f      ‫القادمــة بنــاء عليــه قــررت رفــع اجللســة وحــددت للطرفــن موعــد جديــد‬\n      ‫هو يوم األربعاء املوافق ‪1433 / 4/21‬ه ـ ‪ .‬وباهلل التوفيق ‪ ،‬وصلى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/04/14‬هـ‬\n                                                             ‫يف متــام الســاعة ‪. 11:00‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.‬القاضــي يف احملكمــة العامــة بعرعــر‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بعرعــر برقــم وتاريــخ ‪ 1433/04/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫وتاريــخ ‪ 1433/04/03‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1433/04/21‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 10 : 35‬وفيهــا حضــر املدعــي العــام ‪..‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.‬الوكلــي الشــرعي عــن املدعــى‬\n      ‫عليــه أعــاه مبوجــب الوكالــة الصــادرة مــن كتابة عدل عرعر رقم يف‬\n      ‫‪1433/3/1‬ه ـ املخــول لــه فيهــا حــق املرافعــة واملدافعــة واإلقــرار باملدعى‬\n      ‫بــه وإنــكاره وإحضــار البينــات وردهــا والطعــن فيهــا أو قبولهــا وطلــب‬\n      ‫األميــان وســماعها وردهــا والصلــح واالســتالم والتســليم وتــرك اخلصومــة‬\n      ‫ورفــع احلجــز وتــرك الرهــن مــع بقــاء الديــن واالدعــاء بالتزويــر وقبــول‬\n      ‫احلكــم وطلــب متييــزه واســتالم الصكــوك وتقــدمي اللوائــح اإلعتراضيــة‬\n      ‫والتمــاس إعــادة النظــر باألحــكام وتعيــن اخلبــراء واحملكمني وبســؤال‬\n      ‫املدعــي العــام عــن بينتــه التــي وعــد بإحضارهــا يف اجللســة املاضيــة أجــاب‬\n      ‫قائــا لــم أســتطع إحضارهــا يف هــذه اجللســة وأطلــب مهلــة إلحضارهــا‬\n      ‫يف اجللســة القادمــة فأجبتــه لطلبــه وأفهمتــه بــأن هــذا املوعــد نهائــي‬\n      ‫وأخيــر وأننــي ســأعده عاجــزا عــن إحضــار البينــة إذا لــم يحضرهــا‬\n      ‫يف اجللســة القادمــة ففهــم ذلــك بنــاء عليــه قــررت رفــع اجللســة وحتديــد‬\n      ‫موعــد جديــد هــو يــوم االثنــن القــادم املوافــق ‪1433/4/26‬ه ـ الســاعة‬\n\n\n‫‪119‬‬\n\f‫التاســعة صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/04/21‬ه ـ يف متــام الســاعة ‪11:05‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.‬القاضــي يف احملكمــة العامــة بعرعــر‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بعرعــر برقــم وتاريــخ ‪ 1433/04/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫وتاريــخ ‪ 1433/04/03‬ه ـ ففــي يــوم اإلثنــن املوافــق‪ 1433/04/26‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11 : 23‬وفيهــا حضــر املدعــي العــام ونظــر ًا‬\n‫لضغــط العمــل لدينــا فلــم نتمكــن مــن إبــاغ املدعــي العــام مبــا مت‬\n‫يف اجللســة املاضيــة إال هــذا اليــوم ولــذا قــررت رفــع اجللســة وحتديــد‬\n‫موعــد جديــد لســماع بينــة املدعــي العــام بحيــث يكــون موعــد نهائــي‬\n‫كمــا تقــدم وهــو يــوم األربعــاء املوافق‪1433/5/26‬ه ـ وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                 ‫‪ 1433/04/26‬ه ـ يف متــام الســاعة‪. 11:33‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.‬القاضــي يف احملكمــة العامــة بعرعــر‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بعرعــر برقــم وتاريــخ ‪ 1433/04/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫وتاريــخ ‪ 1433/04/03‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1433/05/26‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11 : 34‬وفيهــا حضــر املدعــي العــام ووكيــل‬\n‫املدعــى عليــه احملامــي ‪.‬وأحضــر املدعــي العــام معــه للشــهادة وادائهــا‬\n‫‪.‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.‬وبســؤاله عمــا لديــه مــن‬\n‫شــهاده أجــاب قائــا أشــهد أنــه صــدر تكليــف لالطاحــة باملدعــى عليــه‬\n‫‪.‬نظــرا لقيامــه ببيــع احلشــيش املخــدر وعلــى ضــوء ذلــك اتصــل املصــدر‬\n‫الســري باملدعــى عليــه وطلــب منــه وأنــا أســمع املكاملــة قطعــت حشــيش‬\n\n\n                                                                                  ‫‪120‬‬\n\f      ‫مببلــغ مائــة ريــال فاســتعد وتواعــدا عنــد منــزل املدعــى عليــه وتوجهنــا‬\n      ‫إليــه باملــكان احملــدد وبعــد توقفنــا وكان املصــدر هــو قائــد الســيارة‬\n      ‫وكنــت أنــا املرافــق لــه وجدنــا املدعــى عليــه واقــف عنــد البــاب فنــزل‬\n      ‫املصــدر وســلم عليــه وأنــا أشــاهد املوقــف فســلم املدعــى عليــه قطعــة‬\n      ‫احلشــيش للمصــدر واســتلم مــن املصــدر املبلــغ احلكومــي ومقــداره مائــة‬\n      ‫ريــال ثــم انصرفنــا وكان ذلــك بتاريــخ ‪1433/2/6‬ه ـ الســاعة السادســة‬\n      ‫مســاء ثــم بعــد فتــرة مت القبــض علــى املدعــى عليــه ولــم يحضــر عمليــة‬\n      ‫االســتالم والتســليم أحــد غيــري ثــم جــرى ســؤال املدعــي العــام هل حضر‬\n      ‫أحــد الواقعــه غيــر هــذا الشــاهد فأجــاب بالنفــي وبعرضــه علــى املدعــى‬\n      ‫عليــه وكالــه أجــاب قائــا أطلــب مهلــة الحضــار جوابــي مكتــوب‬\n      ‫هكــذا أجــاب لذلــك قــررت رفــع اجللســة وحتديــد موعــد جديــد لســماع‬\n      ‫اجابــة املدعــى عليــه يــوم الثالثــاء املوافــق ‪1433/6/3‬ه ـ وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                 ‫‪ 1433/05/26‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.‬القاضــي يف احملكمــة العامــة بعرعــر‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بعرعــر برقــم وتاريــخ ‪ 1433/04/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫وتاريــخ ‪ 1433/04/03‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1433/06/03‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 01 : 33‬وفيهــا حضــر املدعــي العــام والوكيــل‬\n      ‫الشــرعي للمدعــى عليــه وبســؤال وكيــل املدعــى عليــه عــن اجلــواب علــى‬\n      ‫شــهادة الشــاهد الــذي وعــد بتقدميهــا يف هــذه اجللســة قــدم لنــا ورقتــان‬\n      ‫وطلــب ضبطهمــا فاجيــب طلبــة وهــذا نصهــا أو ًال الدفــع ببطــان بعــض‬\n                                                                          ‫اإلجــراءات‬\n\n\n‫‪121‬‬\n\f‫فضيلــة ناظــر القضيــة ‪ :‬مــن املظاهــر الواضحــة للعيــان مــدي التــزام‬\n‫أنظمــة الدولــة يف التقيــد مبــا جــاء بالنظــام ويتجلــى هــذا االلتــزام برقابــة‬\n‫القضــاء علــى نظاميــة اإلجــراءات التــي تخــول جهــة القبــض يف االلتــزام‬\n‫بالنظــام ولقــد قــن نظــام اإلجــراءات اجلزائيــة مجموعة من املــواد تختص‬\n‫بالبطــان كمــا جــاء باملــادة الثامنــة والثمانــون بعــد املائــة ( كل إجــراء‬\n‫مخالــف إلحــكام الشــريعة اإلســامية أو األنظمــة املســتمدة منهــا‬\n                                                                 ‫يكــون باطــا) ‪0‬‬\n‫واملــادة التســعون بعــد املائــة (‪ .......‬إذا كان البطــان راجعــا إلــى عيــب يف‬\n‫اإلجــراءات ميكــن تصحيحــه فعلــى احملكمــة إن تصححــه وان كان‬\n                ‫راجعــا إلــى عيــب ال ميكــن تصحيحــه فتحكــم ببطالنــه )‬\n‫كمــا ال يخفــى علــى فضيلتكــم أن البطــان فعــل إجرائــي يلحــق كل‬\n‫إجــراء معيــب وينســحب علــى اآلثــار املترتبــة عليــه مباشــرة وعلــى كل‬\n‫إجــراء بنــي عليــه ولــو كان صحيحــا والقاعــدة الشــرعية تقــول أن مــا‬\n‫بنــي علــى باطــل فهــو باطــل ومثلهــا القاعــدة النظاميــة التــي تقول(الدليــل‬\n‫الباطــل ال يصــح االعتمــاد عليــة يف اإلثبــات القضائــي وال يصــح أن‬\n                                    ‫يســتند عليــة يف حكــم اإلدانــة إطالقــا)‬\n‫فضيلــة الشــيخ الواقعــة املدعــاة كمــا جــاء بالئحــة الدعــوى يــوم‬\n‫الســبت املوافــق ‪1433/2/6‬ه ـ والقبــض مت بعدهــا مبــا يزيــد علــى ‪14‬‬\n‫يــوم والفــرق بينهمــا خمســة عشــر يومــا آال يدعــوا هــذا للتســاؤل؟‪ .‬ملــاذا‬\n‫لــم يتــم اتخــاذ إجــراء نظامــي خــال هــذه الفتــرة الطويلــة جــدا بالنســبة‬\n‫لقضايــا املخــدرات املماثلــة وحســب األصــول النظاميــة الــواردة بالنظــام‬\n‫يتــم إصــدار مذكــرة قبــض مــن اجلهــة املخولــة بذلــك ‪ -‬هيئــة التحقيــق‬\n‫واالدعــاء العــام‪ -‬هــذا إن ســلمت الواقعــة اجلرميــة مــن شــوائب العيــوب‬\n\n\n                                                                                        ‫‪122‬‬\n\f      ‫اإلجرائيــة بطريــق اســتراق الســمع أو التحريــض علــى ارتــكاب اجلرميــة‬\n      ‫وخالفهــا جــاء باملــادة اخلامســة والثالثــون مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫(يف غيــر حالــة التلبــس ال يجــوز القبــض علــى أي إنســان أو توقيفــه إال‬\n                                              ‫بأمــر مــن الســلطة املختصــة بذلــك ‪).....‬‬\n      ‫ومــا فائــدة ادعائهــم بإعطائهــم املصــدر مائــة ريــال مرقمــة إن لــم يتــم‬\n      ‫القبــض علــي مباشــرة ويكــون املبلــغ املرقــم دليــل إدانــة هــذا يف حالــة‬\n                                                                    ‫ســامة اإلجــراءات ‪.‬‬\n                                                          ‫ثانيا ‪ :‬الدفع بعيب يف الشهادة‬\n      ‫ومــن أهــم الشــروط التــي يجــب توفرهــا بالشــاهد أن يكــون محايــدا ال‬\n                         ‫مصلحــة لــه يف تلــك الشــهادة إال قــول احلــق والشــهادة بــه ‪.‬‬\n      ‫فالشــاهد ال بــأن يكــون محايــدا ليــس لــه عالقــة متيــل كفتهــا ألحــد‬\n                   ‫أطــراف النــزاع ملصلحــة لــه ظاهــرة ممــا يدفعــه لالنحيــاز ‪،‬‬\n      ‫واملشــرع لدينــا فصــل بــن ســلطتي االتهــام والتحقيــق لغايــة ســامية‬\n      ‫ومطلــب نبيــل وهدفــه مــن ذلــك ألنــه لــو مت اجلمــع بــن هاتــن الســلطتني‬\n                 ‫يف جهــة واحــدة يكــون مــن بــاب جمــع صفتــن متعارضتــن‬\n                                   ‫ثاني ًا النقص بالنصاب املعتمد يف مراتب الشهادة‬\n                  ‫فإن نظام املرافعات الشرعية ولوائحه التنفيذية بني يف مواده‬\n      ‫( ‪ )123 -117‬ماهيــة الشــهادة ؛ واألحــوال التــي تقبــل فيهــا بينــة الشــهادة‬\n      ‫وشــروط قبولهــا ‪ ،‬واحلكــم بهــا يف اخلصومــات وشــهادة الفرقــة القابضة‬\n                       ‫ضــد موكلــي شــهادة فيهــا خلــل وتناقــض وهــي كالتالــي ‪:‬‬\n                                                 ‫‪ .1‬الشاهد ‪.‬ناقل للخبر وليس شاهد ‪.‬‬\n      ‫‪ .2‬غالــب القضايــا يف احملكمــة ‪ -‬ولفضيلتكــم التأكــد كيــف‬\n                                           ‫يكــون الشــاهد ‪.‬هــو مــن يشــهد فيهــا ‪.‬‬\n\n\n‫‪123‬‬\n\f‫‪ .3‬اقــر الشــاهد يف مجلــس احلكــم بأنــه هــو والرقيــب من ســمع املكاملة‬\n‫ويف احملضــر املثبــت يف ملــف القضيــة الفرقــة القابضــة كاملــة ســمعت‬\n                                                                       ‫املكاملــة ‪.‬‬\n‫‪ .4‬عــدم معرفــة الوقــت الدقيــق للواقعــة فقــد أفــاد الشــاهد بــأن الواقعــة‬\n‫وقعــت مــع صــاة املغــرب ويف محضــر الفرقة القابضة الســاعة السادســة‬\n‫علمــا بــان وقــت أذان صــاة املغــرب يف تاريــخ ‪1433/2/6‬ه ـ هــو الســاعة‬\n‫(‪5.24‬دقيقــة) ولــم يــرد ملوكلــي أي اتصــال يف هــذا الوقــت ســوى اتصال‬\n                                  ‫مــن أحــد زمالئيــة يف الســاعة (‪6.38‬دقيقــة)‬\n‫‪ .5‬ممــا يســتحيل رؤيــة ‪1.30‬غــرام مــن احلشــيش املخــدر بالعــن املجــردة‬\n‫ولكــن لــو ســلمنا بإمكانيــة رؤيــة احلشــيش فــإن إقــرار الشــاهد مبلــف‬\n‫القضيــة يختلــف عنمــا ذكــر يف مجلــس احلكــم حيــث أفــاد مبلــف‬\n‫القضيــة بــأن قطعــة احلشــيش يف كيــس ملفــوف ويف مجلــس احلكــم‬\n                             ‫أفــاد بأنــه رآهــا يف يــده دون ذكــر الكيــس ‪.‬‬\n‫وحيــث لــم يتــم ذلــك فهــو مدعــاة للتســاؤل عــن صحــة الدعــوى برمتهــا‬\n‫ولثقتنــا يف نزاهــة القضــاء وعــدل القضــاة فإنــي أطلــب مــن فضيلتكــم‬\n‫التأكــد مــن هيئــة االتصــاالت يف طلــب برنــت املكاملــات الــواردة‬\n‫والصــادرة الــوارد ملوكلــي يف يــوم الواقعــة املدعــاة إلظهــار احلقيقــة‬\n‫هكــذا اجــاب فطلبــت مــن املدعــي العــام احضــار مزكــن لشــاهده‬\n                                    ‫فوعــد باحضارهــم يف اجللســة القادمــة ‪.‬‬\n‫لــذا قــررت رفــع اجللســة وحتديــد موعــد جديــد هــو يــوم االحــد املوافــق‬\n‫‪1433/07/06‬ه ـ الســاعة العاشــره صباح ـ ًا وصلــى اهلل علــى نبينــا‬\n              ‫محمــد حــرر يف ‪1433/06/03‬ه ـ يف متــام الســاعة ‪00:02‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.‬القاضــي يف احملكمــة العامــة بعرعــر‬\n\n\n                                                                                      ‫‪124‬‬\n\f      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بعرعــر برقــم وتاريــخ ‪ 1433/04/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫وتاريــخ ‪ 1433/04/03‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1433/08/27‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 00:11‬وفيهــا حضــر املدعــي العــام وبســؤاله‬\n      ‫ال مــن‬\n            ‫عــن املزكــن الذيــن مت طلبهــم يف اجللســة املاضيــة احضــر ك ً‬\n      ‫‪.‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.‬و‪.‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪.‬وبســؤالهما عمــا لديهمــا مــن شــهادة‬\n      ‫ا اشــهد هلل تعالــى بــأن الشــاهد‬    ‫أجــاب كل واحــد منهمــا مبفــرده قائ ـ ً‬\n      ‫أعــاه ثقــة مرضــي الشــهادة هكــذا شــهدا وللتأمــل وإصــدار مــا يلــزم‬\n      ‫قــررت رفــع اجللســة وحتديــد موعــد جديــد هــو يــوم الســبت املوافــق‬\n      ‫‪1433/9/2‬ه ـ الســاعة العاشــرة صباحـ ًا ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/08/27‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.‬القاضــي يف احملكمــة العامــة بعرعــر‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بعرعــر برقــم وتاريــخ ‪ 1433/04/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫وتاريــخ ‪ 1433/04/03‬ه ـ ففــي يــوم الســبت املوافــق‪ 1433/09/02‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11:30‬وفيهــا حضــر املدعــي العــام ولــم يحضــر‬\n      ‫املدعــى عليــه وال مــن ينــوب عنــه وقــد اعتــذر وكيلــه ‪.‬املــدون مــا يــدل‬\n      ‫علــى هويتــه يف جلســة ســابقة باخلطــاب املرســل إلينــا هــذا اليــوم واملــؤرخ‬\n      ‫يف ‪1433/08/29‬ه ـ واملرفــق باملعاملــة ويعتــذر فيــه عــن احلضــور بســبب‬\n      ‫وجــود جلســة لــه يف مدينــة الريــاض ‪ .‬بنــاء عليــه قــررت رفــع اجللســة‬\n      ‫وحتديــد موعــد جديــد هــو يوم الســبت املوافق ‪1433/09/09‬هـ الســاعة‬\n      ‫‪ 11:30‬وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1433/09/02‬ه ـ‬\n\n\n‫‪125‬‬\n\f                                                     ‫يف متــام الســاعة ‪. 12:00‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.‬القاضــي يف احملكمــة العامــة بعرعــر‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بعرعــر برقــم وتاريــخ ‪ 1433/04/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫وتاريــخ ‪ 1433/04/03‬ه ـ ففــي يــوم اإلثنــن املوافــق‪ 1433/09/11‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 02:00‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليــه املــدون مــا يــدل عليهمــا يف جلســة ســابقة وبعــرض مــا ذكــره‬\n‫وكيــل املدعــى عليــه مــن قــوادح يف شــهادة الشــاهد علــى املدعــي العــام‬\n‫قــال أجيــب عــن ذلــك باآلتــي‪ :‬أو ًال ‪ :‬مــا ذكــره وكيــل املدعــي مــن أن‬\n‫الشــاهد ناقــل للخبــر وليــس بشــاهد غيــر صحيــح ألن لفــظ الشــهادة‬\n‫صريــح ‪ .‬ثانيـ ًا ‪ :‬ليــس يف شــهادة الشــاهد أعــاه أنــه قــد ســمع املكاملــة‬\n‫هــو والرقيــب فقــط ‪ ،‬وبالتالــي فــإن مــا ذكــره وكيــل املدعــى عليــه‬\n‫غيــر صحيــح حيــث ذكــر بــأن الشــاهد شــهد يف مجلــس احلكــم بأنــه‬\n‫هــو والرقيــب مــن ســمع املكاملــة وبالرجــوع إلــى نــص الشــهادة لــم أجــد‬\n‫هــذا ‪ .‬ثالث ـ ًا ‪ :‬مــا ذكــر مــن عــدم معرفــة الشــاهد للوقــت بالدقــة غيــر‬\n‫صحيــح حيــث إن الشــاهد ذكــر يف شــهادته أعــاه بــأن وقــت احلادثــة‬\n‫كان بتاريــخ ‪1433/2/6‬ه ـ الســاعة السادســة مســاء وهــو موافــق ملــا يف‬\n‫محضــر الشــراء املــدون علــى الصفحــة رقــم (‪ )11‬مــن ملــف االســتدالل‬\n‫لفــة رقــم (‪ . )1‬رابعـ ًا ‪ :‬مــا ذكــره وكيــل املدعــى عليــه مــن أن الشــاهد‬\n‫ذكــر أن قطعــة احلشــيش رآهــا يف يــده غيــر صحيــح حيــث جــاء يف نــص‬\n‫شــهادة الشــاهد املدونــة أعــاه بأنــه شــاهد املدعــى عليــه ســلم قطعــة‬\n‫حشــيش للمصــدر واســتلم مــن املصــدر املبلــغ احلكومــي وليــس فيهــا‬\n‫أن قطعــة احلشــيش كانــت يف كيــس نايلــون أو لــم تكــن يف كيــس ‪.‬‬\n\n\n                                                                                    ‫‪126‬‬\n\f      ‫خامسـ ًا ‪ :‬مــا ذكــره وكيــل املدعــى عليــه مــن طلــب التأكــد مــن هيئــة‬\n      ‫االتصــاالت وذلــك مــن خــال طلــب برنــت للمكاملــات الــواردة والصــادرة‬\n      ‫ملوكلــه ‪ ،‬أجيــب بأنــه ال حاجــة لذلــك ألننــا لــم نذكــره كدليــل مــن‬\n      ‫األدلــة حتــى نقبــل الطعــن فيــه ‪ .‬وبســؤال املدعــى عليــه أصالــة هــل يوجــد‬\n      ‫ا ‪ :‬نعــم يوجــد علـ ّـي ســابقة واحــده‬  ‫عليــك أي ســوابق مســجلة أجــاب قائـ ً‬\n      ‫وبســؤاله عــن نوعهــا قــال هــي ســابقة أخالقيــة وحكمــت عليهــا عشــرة‬\n      ‫أيــام ومت جلــدي عليهــا ســتني جلــده هكــذا أجــاب ‪ .‬وبســؤال الطرفــن‬\n      ‫هــل لديكمــا مزيــد مرافعــة أجابــا بأننــا نكتفــي مبــا مت ضبطــه فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى وإجابــة املدعــى عليــه باإلنــكار حســب‬\n      ‫إجابتــه املرصــودة بعاليــة وبنــاء علــى التقريــر الكيمائــي الشــرعي بعالية‬\n      ‫املتضمــن إيجابيــة العينــة املضبوطــة ملــادة احلشــيش املخــدر وملــا جــاء يف‬\n      ‫محضــر الشــراء املــدون علــى الصفحــة رقــم (‪ )11‬مــن ملــف االســتدالل‬\n      ‫لفــة رقــم (‪ )1‬ومحضــر القبــض املــدون علــى الصفحــة رقــم (‪ )12‬مــن‬\n      ‫ملــف االســتدالل لفــة رقــم (‪ )1‬وملــا جــاء يف شــهادة الشــاهد املعدلــة‬\n      ‫شــرع ًا املتضمنــة الشــهادة علــى التنســيق واملواعــدة ومشــاهدة االســتالم‬\n      ‫والتســليم ولوجــود ســابقة مســجلة علــى املدعــى عليــه ليســت مــن جنــس‬\n      ‫هــذه القضيــة وجلميــع مــا تقــدم فلــم يثبــت لــدي ثبوت ـ ًا قطعي ـ ًا إدانــة‬\n      ‫املدعــى عليــه مبــا نســب إليــه يف دعــوى املدعــي العــام وإمنــا تتوجــه التهمــة‬\n      ‫القويــة ضــده بقيامــه مبــا نســب إليــه وحكمــت عليــه لقــاء ذلــك تعزيــر ًا‬\n      ‫بالســجن مــدة ســنتني ونصــف مــن تاريــخ إيقافــه وجلــده ثالثمائــة جلــده‬\n      ‫مفرقــة علــى ســت دفعــات كل دفعــة خمســن جلــده ويفصــل بــن كل‬\n      ‫إيقــاع والــذي يليــه بعشــرة أيــام ويكلــف تعزيــر ًا بإعــادة املبلــغ احلكومــي‬\n      ‫البالــغ مائــة ريــال وصرفــت النظــر عــن طلــب املدعــي العــام تطبيــق‬\n\n\n‫‪127‬‬\n\f‫املادتــن (‪ )38،56‬وكذلــك مصــادرة اجلــوال وإلغــاء الشــريحة وذلــك‬\n‫كلــه لعــدم الثبــوت القطعــي وبذلــك حكمــت وبعــرض احلكــم علــى‬\n‫الطرفــن قــررا عــدم القناعــة واســتعدا بتقــدمي الئحــة اعتراضيــة فتــم‬\n‫تســليمهم نســخة مــن احلكــم يف نفــس اجللســة ومت افهامهــم بتعليمــات‬\n‫التمييــز وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1433/09/11‬ه ـ‬\n                                                      ‫يف متــام الســاعة ‪02:30‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.‬القاضــي يف احملكمــة العامــة بعرعــر‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بعرعــر برقــم وتاريــخ ‪ 1433/04/03‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫وتاريــخ ‪ 1433/04/03‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1433/12/21‬ه ـ‬\n‫افتتحــت اجللســة الســاعة وقــد وردتنــا الالئحــة االعتراضيــة املقدمــة مــن‬\n‫املدعــى عليــه برقــم يف ‪1433/11/9‬ه ـ قدمــت يف املهلــة احملــددة حيــث‬\n‫ان طباعــة القــرار تأخــرت الــى مــا بعــد إجــازة رمضــان وكانــت طباعــة‬\n‫القــرار بتاريــخ ‪1433/10/18‬ه ـ ومت تســليم نســخة مــن القــرار للطرفــن‬\n‫بعــد الطباعــة مباشــرة أي بتاريــخ ‪1433/10/18‬ه ـ وقــد قــدم املدعــى‬\n‫عليــه الالئحــة االعتراضيــة مبوعدهــا وأمــا املدعــي العــام فلــم يقــدم‬\n‫شــيئا حتــى اآلن لــذا فقــد قــررت قبــول الالئحــة املقدمــة مــن املدعــى‬\n‫عليــه واســقاط حــق املدعــي العــام يف االعتــراض بنــاء ‪ 178‬مــن نظــام‬\n‫املرافعــات الشــرعية وقــد جــرى منــي االطــاع علــى الالئحــة املقدمــة مــن‬\n‫املدعــى عليــه واملكونــة مــن تســع صفحــات وقرأتهــا قــراءه متأنيــة ولــم‬\n‫اجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه حيــث ذكــر وكيــل املدعــي‬\n‫بــأن هــذه اجلرميــة جرميــة حتريضيــه لكــون ذهــن املدعــى عليــه كان‬\n‫خالي ـ ًا منهــا فتــم حتريضــه مــن قبــل املصــدر الســري للوقــوع يف هــذه‬\n\n\n                                                                                  ‫‪128‬‬\n\f      ‫اجلرميــة وهــذا بعيــد وال ميكــن تنزيلــه علــى هــذه الواقعــة وذلــك ألن جرميــة‬\n      ‫الترويــج ال ميكــن أن تتــم إال عــن شــخص لــه بــاع طويــل يف املخــدرات‬\n      ‫ا‬\n      ‫والتعامــل معهــا واال فــإن مجــرد حيازتــه للمخــدرات يعتبــر جرميــة فضـ ً‬\n      ‫عــن بيعهــا وهــذا يعتبــر اعتــراف ضمنــي باحليــازة والترويــج ‪ .‬وأمــا مــا‬\n      ‫ذكــره وكيــل املدعــى عليــه مــن ان الدعــوى قائمــة علــى األخــذ بشــهادة‬\n      ‫الشــاهد وأنــه غيــر محايــد وان هــذه الشــهادة شــهادة اســتغفال والروايــة‬\n      ‫الثابتــة يف املذهــب هــو عــدم قبولهــا وأنــه قــام بارتــكاب مخالفــة نظاميه‬\n      ‫فكيــف تقبــل شــهادته فأمــا مــا ذكــره مــن أن الشــاهد غيــر محايــد‬\n      ‫ا وأمــا مــا ذكــره مــن أنهــا شــهادة‬\n                                             ‫فإنــه مجــرد ادعــاء لــم يقــدم عليــه دليـ ً‬\n      ‫اســتغفال فغيــر صحيــح ألن شــهادة االســتغفال هــي تخفــي الشــهود عــن‬\n      ‫املشــهود عليــه والشــهادة هنــا ال يوجــد فيهــا تخفــي كمــا تقــدم بــل أن‬\n      ‫الشــاهد كان مع املصدر الســري أثناء عملية البيع والشــراء واالســتالم‬\n      ‫والتســليم لذلــك فهــذه الشــهادة ليســت شــهادة اســتغفال ولــو ســلمنا انهــا‬\n      ‫شــهادة اســتغفال فالصحيــح يف املذهــب انهــا شــهادة صحيحــه مقبولــة‬\n      ‫هــذا علــى فــرض التســليم بصحــة مــا ذكــره لذلــك فإنــي علــى مــا‬\n      ‫حكمــت بــه أعــاه وقــد تأخــرت يف الــرد علــى هــذه الالئحــة لكونهــا‬\n      ‫قــد قدمــت بتاريــخ ‪1433/11/9‬ه ـ وكان اخــر يــوم عمــل لــي هــو يــوم‬\n      ‫األربعــاء ‪1433/11/10‬ه ـ ولكونــي يف دوره ومــن بعدهــا إجــازة إلــى‬\n      ‫إجــازة عيــد األضحــى وحتــى ال يخفــى وال يلتبــس جــرى التنبيــه وصلــى‬\n      ‫اهلل علــى نبينــا محمــد ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/12/21‬هــ‪.‬‬\n      ‫احلمــدهلل وحــده وبعــد ‪ ...‬فقــد أطلعنــا نحــن قضاة الدائــرة اجلزائية الثانية‬\n      ‫لتمييــز القضايــا اجلزائيــة مبحكمــة اإلســتئناف باجلــوف علــى املعاملــة‬\n\n\n‫‪129‬‬\n\f‫الــواردة مــن رئيــس احملكمــة العامــة بعرعر الشــيخ ‪. /‬برقم‪34628270‬‬\n‫وتاريــخ ‪1434/4/6‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪./‬‬\n‫املســجل برقــم‪ 33431140‬يف ‪1433/10/18‬ه ـ اخلــاص بدعــوى املدعــي‬\n‫العــام ضــد‪../‬يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه‬\n‫مبــا هــو مــدون و مفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة تقــرر باألكثريــة املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‬\n ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪130‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":114,"source_page_end":130,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6b7c29e1bcddd56c8fb21d13b50c1863042d92afea9c45f2d84c7eb87db69198","normalized_text_hash":"407c2359ce406494850329c594a54e047d158399f2cb0af8d5287a9895ea9c06","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p114-33431140"},{"id":"bd60054e-6d45-564d-b9d5-9e4407e42b12","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -اإلقرار -التعزير للشبهة - إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واملنع","document_number":"33302883","case_number":"33296114","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/06/17","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -اإلقرار -التعزير للشبهة - إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واملنع","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33302883 :‬تاريخه ‪1433/06/17 :‬هـ‬\n                          ‫رقم الدعوى ‪33296114:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3416192‬تاريخه‪1434/01/19 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬ترويــج احلشــيش املُخــدر ‪ -‬اإلقــرار ‪ -‬التعزيــر للشــبهة ‪-‬‬\n       ‫إقامــة حــد املســكر علــى متعاطــي احلشــيش ‪ -‬التعزيــر بالســجن واملنــع‬\n                                                                    ‫مــن الســفر ‪.‬‬\n\n\n\n\n       ‫‪ -1‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                            ‫العقليــة‬\n       ‫‪ -2‬الفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                             ‫العقليــة‬\n       ‫‪ -3‬الفقــرة (‪ )1‬مــن املــادة ‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                            ‫العقليــة‬\n       ‫‪ -4‬قــال شــيخ اإلســام رحمــه اهلل ‪ ( :‬والصحيــح أن احلشيشــة ُمســكرة‬\n       ‫كالشــراب وأن آكلهــا يحــد منهــا فهــي َخمــر ) ‪ .‬الفتــاوى (‪.)135/29‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج ثــاث جرامــات مــن‬\n       ‫احلشــيش املخــدر وتعاطيــه للحشــيش املخــدر وطلــب املدعــي العــام‬\n       ‫إثبــات إدانــة املدعــى عليــه بترويــج قطعــة مــن احلشــيش املخــدر وتعاطيــه‬\n       ‫للحشــيش واحلكــم عليــه بالســجن واجللــد والغرامــة واملنــع مــن الســفر‬\n\n‫‪131‬‬\n\f‫ومصــادرة هاتفــه اجلــوال وإلزامــه بــرد املبلــغ احلكومــي املرقــم تطبيق ـ ًا‬\n‫ألحــكام مكافحــة املخــدرات ‪،‬حيــث أنــه ورد بــاغ مــن أحــد املصــادر‬\n‫الســرية لشــعبة مكافحــة املخــدرات عــن قيــام املدعــى عليــه بترويــج‬\n‫احلشــيش املخــدر وأنــه يســتخدم جوالــه يف برنامــج احملادثــة للترويــج‬\n‫ومت متكــن املصــدر مــن االتصــال علــى جــوال املدعــى عليــه عــن طريــق‬\n‫برنامــج احملادثــة ومت االتفــاق علــى الشــراء ‪ ،‬مت تفتيــش املصــدر و‬\n‫تزويــده باملبلــغ املرقــم ورافــق املصــدر أحــد أعضــاء الفرقــة وتوجهــا ملنــزل‬\n‫املدعــى عليــه ومتــت عمليــة االســتالم والتســليم أمــام أنظــار الفــرد املرافــق‬\n‫للمصــدر وأنكــر املدعــى عليــه الترويــج وأقــر بالتعاطــي ‪ ،‬فأحضــر‬\n‫املدعــي العــام للشــهادة وأدائهــا الفــرد املرافــق مــع املصــدر وجــرى رصــد‬\n‫الشــهادة وتعديــل الشــاهد ‪ ،‬بنــاء علــى مــا تقــدم ولعــدم اكتمــال البينــة‬\n‫صــدر احلكــم بإقامــة حــد املســكر وتعزيــر املدعــى عليــه بالســجن‬\n        ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬       ‫واملنــع مــن الســفر ‪ُ ،‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ ........‬القاضــي باحملكمــة اجلزئيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n‫مــن هيئــة التحقيــق واإلدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n‫‪ 33804190‬وتاريــخ ‪1433/4/27‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزئيــة بالدمــام برقــم ‪ 33296114‬وتاريــخ ‪1433/4/27‬ه ـ‬\n‫افتتحــت اجللســة يف يــوم الســبت ‪1433/5/15‬ه ـ الســاعة احلاديــة عشــرة‬\n‫ا فيهــا بصفتــي مدعي ـ ًا‬     ‫وفيهــا قــدم املدعــي العــام ‪........‬دعــواه قائ ـ ً‬\n‫عام ـ ًا بدائــرة اإلدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪........ /‬‬\n\n                                                                                        ‫‪132‬‬\n\f      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬حيــث إنــه بتاريــخ‬\n      ‫‪1433/3/12‬ه ـ ورد بــاغ مــن أحــد املصــادر الســرية لشــعبة مكافحــة‬\n      ‫املخــدرات بالدمــام عــن قيــام املتهــم بترويــج احلشــيش املخــدر وأنــه‬\n      ‫يســتخدم جهــاز جوالــه ‪ ......‬يف برنامــج احملادثــة للترويــج واســتعد‬\n      ‫املصــدر لإلطاحــة بــه باجلــرم املشــهود ومت االنتقــال إلــى حــي املريكبــات‬\n      ‫بالدمــام ملقابلــة املصــدر ومت متكينــه مــن االتصــال علــى جهــاز املتهــم عــن‬\n      ‫طريــق برنامــج احملادثــة حيــث قــال املصــدر للمتهــم (وينــك احلــن) ورد‬\n      ‫املتهــم (بالبيــت) ثــم قــال املصــدر (يف أم ميــة) ورد املتهــم (طيــب وينــك‬\n      ‫احلــن) ورد املصــدر (أنــا قريــب) وقــال املتهــم (خــاص تعــال البيــت) ومت‬\n      ‫ـراء للذمــة ومت تزويــده باملبلــغ املرقــم‬\n                                                ‫تفتيــش املصــدر تفتيش ـ ًا دقيق ـ ًا إبـ ً‬\n      ‫ورافــق املصــدر أحــد أفــراد الفرقــة وتوجهــوا إلــى منــزل املتهــم حيــث‬\n      ‫جــاء املتهــم وســلم قطعــة بلــغ وزنهــا (‪ )3‬ثالثــة جرامــات أثبــت التقريــر‬\n      ‫الكيمــاوي رقــم (‪ )........‬وتاريــخ ‪1433/3/28‬ه ـ إيجابيــة عينتهــا ملــادة‬\n      ‫احلشــيش املخــدر وكانــت عملية االســتالم والتســليم أمــام أنظار املرافق‬\n      ‫للمصــدر والفرقــة تشــاهد احتــكاك املتهــم باملصــدر مــن بعيــد ولــم يتــم‬\n      ‫القبــض علــى املتهــم خوفـ ًا على حياة املصدر وحفاظا للســرية ومت تســليم‬\n      ‫القطعــة املروجــة للمرافــق للمصــدر وجــرى رصــد منــزل املتهــم ألكثــر‬\n      ‫مــن أســبوع إال أنــه لــم يظهــر وتبــن أنــه خــارج املنطقــة وجــرى التعميــم‬\n      ‫عنــه برقــم (‪ )........‬وتاريــخ ‪1433/3/22‬ه ـ وبتاريــخ ‪1433/4/10‬ه ـ قــام‬\n      ‫املتهــم بتســليم نفســه وباســتجواب املتهــم نفــى قيامــه بالبيــع وأفــاد أن‬\n      ‫املصــدر صديقــه وأنــه اشــترى القطعــة مــع املصــدر وأن املصــدر أخــذ‬\n      ‫قطعــة صغيــرة وأنــه هــو أخــذ الباقــي وأن املصــدر بعــد ذلك ذهــب واتصل‬\n      ‫عليــه بعــد ذلــك وطلــب منــه القطعــة وأنــه ســلم املصــدر القطعــة وأقــر أنــه‬\n\n\n‫‪133‬‬\n\f‫يتعاطــى احلشــيش املخــدر وقــد انتهــى التحقيــق إلــى اتهامــه ببيــع (‪)3‬‬\n‫ثالثــة جرامــات مــن احلشــيش املخــدر بقصــد االجتــار وتعاطيــه احلشــيش‬\n‫املخــدر وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬مــا ورد بأقوالــه املدونــة‬\n‫واملرفقــة علــى اللفــات رقــم (‪13‬ـ ‪ )15‬وأقوالــه املدونــة علــى الصفحــة‬\n‫رقــم (‪ )2‬مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم (‪ -2 )2‬محضــر‬\n‫القبــض املــدون علــى الصفحتــن رقــم (‪ )11 ،2‬مــن دفتــر التحقيــق‬\n‫املرفــق علــى اللفــة رقــم (‪ -3)1‬التقريــر الكيمــاوي املرفــق علــى اللفــة‬\n‫رقــم (‪ )16‬وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق وحيــث إن مــا‬\n‫أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم‬\n‫ومعاقــب عليــه شــرع ًا ونظام ـ ًا أطلــب إثبــات بيعــه (‪ )3‬ثالثــة جرامــات‬\n‫مــن احلشــيش املخــدر بقصــد االجتــار وتعاطيــه احلشــيش املخــدر وفــق‬\n‫الفقــرة (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واحلكــم‬\n‫عليــه مبــا يلي‪/1:‬عقوبــة الســجن واجللــد والغرامــة وفــق الفقــرة (‪ )1‬مــن‬\n‫املــادة (‪ )38‬مــن النظــام مــع مراعــاة مــا تقضــي بــه املــادة (‪ )62‬مــن النظــام‬\n‫بشــأن العقوبــة األشــد ومــا تقضــي بــه املــادة (‪ )218‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة اســتناد ًا لبرقيــة صاحــب الســمو امللكــي وزيــر الداخليــة رقــم‬\n‫(‪ )66884/4/5/1‬وتاريــخ ‪1428/8/25‬ه ـ لكونــه طالب ـ ًا ‪/2‬منعــه‬\n‫مــن الســفر وفــق الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن النظــام ‪ -3‬مصــادرة‬\n‫هاتفــه اجلــوال املوصــوف بالوقائــع وفــق الفقــرة رقــم (‪ )1‬مــن املــادة (‪)53‬‬\n‫مــن النظــام وعــدم صــرف الشــريحة لنفــس املتهمــن وفــق تعميــم وزيــر‬\n‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ‪ -4‬إلزامــه بســداد‬\n‫املبلــغ املرقــم الــذي لــم يتــم العثــور عليــه وفــق تعميــم وزيــر الداخليــة رقــم‬\n‫(‪ )15980/4/5/1‬وتاريــخ ‪1428/10/23-22‬هــ‪ -5‬املقتضــى الشــرعي‬\n\n\n                                                                                            ‫‪134‬‬\n\f      ‫لقــاء تعاطيــه احلشــيش املخــدر هكــذا ادعــى وبعــرض الدعــوى علــى‬\n      ‫ا مــا ذكــره املدعــي العــام غيــر صحيــح فلــم‬       ‫املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫أقــم ببيــع احلشــيش والصحيــح أن املصــدر اتصــل علــي مغــرب ذلــك اليــوم‬\n      ‫وطلــب منــي الذهــاب معــه فقمــت مبرافقتــه وقــام هــو بشــراء احلشــيش‬\n      ‫مــن حــي ‪........‬بالدمــام مــن أحــد املنــازل ثــم رجعنــا إلــى منزلــي وأعطانــي‬\n      ‫قطعــة مــن احلشــيش ثــم ذهبــت وبعــد العشــاء قــام باالتصــال علــي عــن‬\n      ‫طريــق احملادثــة وطلــب منــي القطعــة وقمــت مبواعدتــه يف منزلــي لكــي‬\n      ‫يأخــذ القطعــة وبعدهــا حضــر وســلمته القطعــة ولــم أســتلم منــه أي‬\n      ‫مبلــغ هكــذا أجــاب وبعــرض ذلــك علــى املدعــي العــام قــال مــا ذكــره‬\n      ‫املدعــى عليــه غيــر صحيــح والصحيــح مــا ذكــرت يف دعــواي هكــذا‬\n      ‫أجــاب ثــم جــرى ســؤال املدعــي العــام البينــة علــى دعــواه فقــال أطلــب‬\n      ‫مهلــة إلحضارهــا ولــذا رفعــت اجللســة ويف يــوم األثنــن ‪1433/06/16‬‬\n      ‫ه ـ افتتحــت اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر الطرفــان‬\n      ‫ثــم جــرى ســؤال املدعــي العــام عمــا طلــب االســتمهال ألجلــه فقــل إننــي‬\n      ‫أحضــرت معــي أحــد الشــهود وأطلــب ســماع شــهادته وهــو هــذا احلاضــر‬\n      ‫معــي‪ ........ /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n      ‫وبســؤال الشــاهد عمــا لديــه مــن شــهادة قــال‪( :‬أشــهد بــاهلل أننــي كنــت‬\n      ‫مــع املصــدر حيــث ذهبنــا إلــى منــزل املدعــى عليــه ثــم خــرج املدعــى عليــه‬\n      ‫مــن املنــزل وســلم املصــدر قطعــة احلشــيش املخــدر واســتلم مــن املصــدر‬\n      ‫املبلــغ وقــدره مائــة ريــال وكان ذلــك أمامــي ) هكــذا شــهد ثــم جــرى‬\n      ‫ســؤال املدعــي العــام هــل لديــه زيــادة بينــة فقــال التوجــد لــدي زيــادة بينــة‬\n      ‫وأطلــب الرجــوع إلــى املعاملــة هكــذا أجــاب ثــم جــرى عــرض الشــاهد‬\n      ‫وشــهادته علــى املدعــى عليــه فقــال شــهادته غيــر صحيحــة وأمــا الشــاهد‬\n\n\n‫‪135‬‬\n\f‫فــا أعرفــه هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام املزكــن‬\n‫ال مــن‪........ /‬ســعودي اجلنســية‬  ‫للشــاهد فقــال إننــي أحضــرت معــي ك ً‬\n‫مبوجــب الســجل املدنــي رقــم ‪........‬و‪........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪........‬وأطلــب ســماع مــا لديهمــا وبســؤالهما عمــا‬\n                      ‫لديهمــا مــن شــهادة قــال كل واحــد منهمــا مبفــرده ‪:‬‬\n‫( أشــهد بــاهلل أننــي أعــرف ‪........‬وهــو رجــل ثقــة عــدل مقبــول الشــهادة‬\n‫يف الديــن واملــروءة ) هكــذا شــهدا ونظــر ًا لطلــب انصــراف الشــهود‬\n‫جــرى التوقيــع ويف يــوم األثنــن ‪ 1433/06/16‬ه ـ افتتحــت اجللســة‬\n‫الســاعة احلاديــة عشــرة وفيهــا حضــر الطرفــان ثــم جــرى ســؤال املدعــى‬\n‫عليــه هــل قــام بتعاطــي احلشــيش فقــال إننــي أتعاطــى احلشــيش منــذ‬\n‫فتــرة قريبــة قبــل القبــض علــي بحوالــي شــهرين هكــذا أجــاب ثــم جــرى‬\n‫اإلطــاع علــى املعاملــة فوجــدت علــى لفــة رقــم (‪ )1‬ملــف ضبــط إجــراءات‬\n‫االســتدالل ص (‪ )11‬محضــر واقعــة القبــض والضبــط والتفتيــش وهــو‬\n‫طبــق مــا ذكــر املدعــي العــام يف دعــواه كمــا وجــدت علــى لفــة رقــم‬\n‫(‪ )16‬تقريــر كيمــاوي شــرعي رقــم (‪ )........‬املتضمــن ايجابيــة العينــة‬\n‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n                                         ‫املرســلة ملــادة احلشــيش املخــدر فبنـ ً‬\n‫العــام وإجابــة املدعــى عليــه ونظــر ًا لعــدم اكتمــال البينــة مــن املدعــي‬\n‫ـاء علــى شــهادة الشــاهد املعــدل التعديــل الشــرعي‬  ‫العــام علــى دعــواه وبنـ ً‬\n‫ومبــا أن املدعــى عليــه لــم يكــن بحوزتــه وقــت القبــض عليه أي شــيء من‬\n‫املمنوعــات ولــم يكــن بحوزتــه املبلــغ احلكومــي املرقــم ونظــر ًا لوجــود‬\n‫ـاء علــى‬\n       ‫الشــبهة وقــوة القرائــن وعــدم وجــود ســوابق للمدعــى عليــه وبنـ ً‬\n‫إقــرار املدعــى عليــه بتعاطــي احلشــيش املخــدر وحيازتــه وهــو بكامــل‬\n‫ـاء علــى الفقــرة (‪ )2‬مــن املــادة (‪ )3‬والفقــرة‬\n                                                 ‫أهليتــه املعتبــرة شــرع ًا وبنـ ً‬\n\n                                                                                       ‫‪136‬‬\n\f      ‫(‪ )1‬مــن املــادة (‪ )41‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة ومبــا أن احلشــيش مســكر حيــث ذكــر‬\n      ‫شــيخ اإلســام ابــن تيميــة يف مجمــوع الفتــاوى مــا نصــه‪( :‬والصحيــح أن‬\n      ‫احلشيشــة مســكرة كالشــراب وأن آكلهــا يحــد منهــا فهــي خمــر )‬\n                                     ‫(ج‪/29‬ص‪ )135‬أو ًال ســجنه ملــدة ســنتني ابتـ ً‬\n      ‫ـداء مــن تاريــخ إيقافــه لقــاء‬\n      ‫حيــازة احلشــيش وشــبهة البيــع‪ .‬ثانيـاً‪ :‬منعــه مــن الســفر خــارج البــاد ملــدة‬\n      ‫ســنتني تبــدأ بعــد انتهــاء فتــرة الســجن املقــررة يف البنــد ثانيـاً‪ .‬ثالثـاً‪ :‬جلده‬\n      ‫ثمانــن جلــدة دفعــة واحــدة حــد املســكر ويكــون التنفيــذ يف مــكان‬\n      ‫عــام يحضــره جمــع مــن النــاس وبذلــك حكمــت وبعــرض احلكــم علــى‬\n      ‫الطرفــن قــرر املدعــى عليــه القناعــة باحلكــم وأمــا املدعــي العــام فقــرر‬\n      ‫االعتــراض علــى احلكــم وطلــب االســتئناف بالئحــة يقدمهــا فجــرى‬\n      ‫إفهامــه باملراجعــة غــد ًا الســتالم نســخة مــن احلكــم لتقــدمي الالئحــة‬\n      ‫االعتراضيــة خــال ثالثــن يوم ـ ًا يكــون حقــه يف االعتــراض بعدهــا‬\n      ‫ســاقط ًا ففهــم ذلــك وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n                                                              ‫حــرر يف ‪1433/06/17‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت ‪1433/7/19‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة احلاديــة عشــرة والربــع وحيــث أن املدعــي العــام لــم يقــدم‬\n      ‫اعتراضــه علــى احلكــم وقــد مضــت املــدة النظاميــة لالعتــراض لــذا‬\n      ‫فقــد ســقط حقــه يف االعتــراض وأمــرت برفــع املعاملــة إلــى محكمــة‬\n      ‫االســتئناف وذلــك بنــاء علــى املــادة (‪ )195‬مــن نظــام اإلجــراءات اجلزائيــة‬\n              ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1433/11/21‬ه ـ‬\n      ‫احلمد هلل وحده وبعد ففي يوم األحد ‪1433/11/21‬هـ الساعة الواحدة‬\n      ‫والربــع افتتحــت اجللســة وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n\n\n‫‪137‬‬\n\f‫باملنطقــة الشــرقية وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة األولــى‬\n‫برقــم ‪ 33435965‬يف ‪1433/10/23‬ه ـ املتضمــن (لوحــظ أنــه يوجــد‬\n‫ســقط يف احلكــم يف القــرار عمــا يف صــورة الضبــط ملالحظــة ماذكــر‬\n‫وإكمــال الــازم) عليــه فقــد مت إكمــال الــازم وأمــرت برفــع املعاملــة‬\n‫إلــى محكمــة االســتئناف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                            ‫محمــد‪ .‬حــرر يف ‪1433/11/21‬ه ـ‬\n‫احلمــدهلل وحــده وبعــد ففــي يــوم الســبت ‪1434/02/09‬ه ـ الســاعة‬\n‫التاســعة والربــع افتتحــت اجللســة وفيهــا وردتنــا املعاملــة مــن محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار الصــادر مــن الدائــرة‬\n‫اجلزائيــة األولــى برقــم ‪ 3416192‬يف ‪1434/01/19‬ه ـ املتضمــن‬\n‫املصادقــة علــى احلكــم وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                         ‫محمــد ‪ .‬حــرر يف ‪1434/02/09‬ه ـ‬\n\n\n\n\n                                                                                      ‫‪138‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":131,"source_page_end":138,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3ffc8eb7ab08fd84357d5ddf93f1e2e471bf0df40b0dc7eb470ea45b928537b5","normalized_text_hash":"eb03853405462673defe3706869bffe820dcb9418de72c2849c23fe9a895057d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p131-33302883"},{"id":"ddb60e65-11c0-5a6e-b2de-dd00019a1492","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج سيجارة مخلوطة باحلشيش املخدر عن طريق اإلهداء -تعاطي احلشيش املخدر -حيازة سيجارة مخلوطة باحلشيش املخدر بقصد التعاطي -تستر على مصدر املخدرات- إقرار حتقيق ا -رجوع عن اإلقرار -إثبات إدانة مبوجب إقرار حتقيق ا- إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد واملنع من السفر.","document_number":"33260798","case_number":"33301404","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/23","year":"1434","subject":"مخدرات -ترويج سيجارة مخلوطة باحلشيش املخدر عن طريق اإلهداء -تعاطي احلشيش املخدر -حيازة سيجارة مخلوطة باحلشيش املخدر بقصد التعاطي -تستر على مصدر املخدرات- إقرار حتقيق ا -رجوع عن اإلقرار -إثبات إدانة مبوجب إقرار حتقيق ا- إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33260798:‬تاريخه ‪1434/05/23 :‬هـ‬\n                          ‫رقم الدعوى‪33301404:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 33310804‬تاريخه‪1433/6/23 :‬هـ‬\n\n\n       ‫مخــدرات‪ -‬ترويــج ســيجارة مخلوطــة باحلشــيش املخــدر عــن طريــق‬\n       ‫اإلهــداء‪ -‬تعاطــي احلشــيش املخــدر‪ -‬حيــازة ســيجارة مخلوطــة‬\n       ‫باحلشــيش املخــدر بقصــد التعاطــي‪ -‬تســتر علــى مصــدر املخــدرات‪-‬‬\n       ‫إقــرار حتقيقـ ًا‪ -‬رجــوع عــن اإلقــرار‪ -‬إثبــات إدانة مبوجب إقــرار حتقيق ًا‪-‬‬\n       ‫إقامــة حــد املســكر علــى متعاطــي احلشــيش‪ -‬التعزيــر بالســجن واجللد‬\n                                                                ‫واملنــع مــن الســفر‪.‬‬\n\n\n\n\n            ‫املواد ‪ 38‬و ‪ 41‬و ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــى العــام ضــد املدعــى عليهمــا بتعاطــي احلشــيش املخــدر‬\n       ‫وترويــج األول لســيجارة مخلوطــة باحلشــيش عــن طريــق اإلهــداء للثانــي‬\n       ‫وحيــازة الثانــي لســيجارة مخلوطــة باحلشــيش بقصــد التعاطــي ‪ ،‬وطلــب‬\n       ‫املدعــي العــام إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بحــد املســكر‬\n       ‫لقــاء تعاطيهمــا احلشــيش املخــدر وبعقوبــة األول وفق ـ ًا للمــادة (‪ )38‬مــن‬\n       ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وتعزيــره لقــاء تســتره علــى‬\n       ‫مصــدر املخــدرات ‪ ،‬وعقوبــة الثانــي وفقـ ًا للمــادة (‪ )41‬مــن ذات النظــام‬\n       ‫لقــاء حيازتــه ســيجارة مخلوطــة باحلشــيش بقصــد التعاطــي ومنــع املدعــى‬\n\n‫‪139‬‬\n\f‫عليهمــا مــن الســفر ‪ ،‬حيــث أنــه مت القبــض علــى املدعــى عليهمــا بعــد‬\n‫االشــتباه بهما من قبل الدوريات وبتفتيشــهما عثر على موقع نزول أحد‬\n‫املدعــى عليهمــا علــى عقــب ســيجارة ُمدخنــة يشــتبه احتوائهــا علــى مــادة‬\n‫احلشــيش املخــدر ‪ ،‬أقــر املدعــى عليهمــا بتعاطــي احلشــيش وإنكارهمــا‬\n‫الترويــج واحليــازة ‪ ،‬كمــا أقــر املدعــى عليهمــا لــدى جهــة التحقيــق حيــث‬\n‫أقــر األول بأنــه أهــدى للثانــي ســيجارة مخلوطــة باحلشــيش وإقــرار الثاني‬\n‫بحيــازة ســيجارة مخلوطــة باحلشــيش ‪ ،‬حيــث ثبــت إدانتهمــا مبــا نســب‬\n‫إليهمــا ‪ -‬بنــاء علــى مــا ســبق حكمــت احملكمــة بإقامــة حــد املســكر‬\n‫علــى املدعــى عليهمــا وبتعزيــر املدعــى عليهمــا بالســجن واجللــد واملنــع‬\n                    ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬   ‫مــن الســفر ُ‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باخلرج‪/‬املســاعد برقــم ‪ 33301404‬وتاريــخ‬\n‫‪ 1433/05/01‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33819190‬وتاريــخ‬\n‫‪ 1433/05/01‬ه ـ ففــي يــوم الســبت املوافــق‪ 1433/05/22‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي العــام ‪ .......‬وادعــى علــى احلاضــر‬\n‫معــه ‪ .......‬ســعودي مبوجــب الســجل املدنــي رقــم ‪ ......‬و ‪ .......‬ســعودي‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .....‬قائــا يف دعــواه عليــه ‪ :‬أنــه بتاريــخ‬\n‫‪1433/3/27‬ه ـ وأثنــاء قيــام إحــدى فــرق دوريــات األمــن مبحافظة اخلرج‬\n‫بعملهــا شــاهدت ســيارة ‪ ....‬نــوع (‪ ).....‬متوقفــة عنــد مستشــفى امللــك‬\n‫خالــد وبداخلهــا املدعــى عليهمــا وعنــد وقــوف الفرقــة نــزل املدعــى عليــه‬\n\n                                                                                   ‫‪140‬‬\n\f      ‫الثانــي مــن الســيارة وبتفتيشــه لــم يعثــر معــه علــى شــيء وعثــر مبوقــع‬\n      ‫نزولــه علــى عقــب ســيجارة مدخنــه بلــغ وزنهــا (‪ )0.5‬نصــف جــرام يشــتبه‬\n                                                          ‫بهــا فتــم القبــض عليهمــا ‪.‬‬\n      ‫وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪/3438‬س) إيجابيــة‬\n      ‫مســتخلص التبــغ ملــادة احلشــيش وهــو مــن املــواد املخــدرة واملدرجــة‬\n      ‫باجلــدول رقــم (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                             ‫العقليــة ‪.‬‬\n      ‫وبإعــادة اســتجواب األول ‪ :‬أقــر بأنــه كان يقــود الســيارة ويوجــد معــه‬\n      ‫ســيجارتان مخلوطتــان مبــادة احلشــيش فقــام باملــرور علــى الثانــي وقــدم‬\n      ‫لــه احــدى الســيجارتني هديــة للثانــي ليدخنهــا فقامــا بتعاطيهمــا فلمــا‬\n      ‫حضــرت فرقــة الدوريــات قــام ببلــع باقــي ســيجارة احلشــيش وقــام الثانــي‬\n      ‫برميهــا وهــي التــي عثــر عليهــا مــن قبــل الفرقــة وأفــاد بأنــه ال يعــرف‬\n                                                                ‫مصــدر الســيجارتني ‪.‬‬\n      ‫وباســتجواب الثانــي ‪ :‬أقــر بــأن األول قــد قــام باملــرور عليــه بســيارته‬\n      ‫فركــب معــه بعدهــا قــدم األول لــه ســيجارة حشــيش مخــدر كهديــة‬\n      ‫ودخــن األول ســيجارة حشــيش فلمــا حضــرت الفرقــة قــام األول ببلــع‬\n      ‫الباقــي مــن الســيجارة والثانــي رماهــا وقــد ضبطــت مــن قبــل الفرقــة‬\n      ‫كمــا أقــر بــأن أخــر مــرة تعاطــى فيهــا احلشــيش املخــدر قبــل شــهرين‬\n      ‫تقريب ـ ًا ‪ .‬وقــد انتهــى التحقيــق معهمــا إلــى اتهــام ‪ :‬األول ‪ /‬بترويــج‬\n      ‫ســيجارة مخلوطــة مبــادة احلشــيش املخــدر بلــغ وزنهــا (‪ )0.5‬نصــف جــرام‬\n      ‫عــن طريــق اإلهــداء وتعاطيــه لنوعــه ‪ ،‬وللثانــي بحيــازة عقــب ســيجارة‬\n      ‫بلــغ وزنهــا (‪ )0.5‬نصــف جــرام مخلوطــة مبــادة احلشــيش املخــدر بقصــد‬\n      ‫التعاطــي وتعاطيهــا لنوعــه املجــرم باملــادة (‪ )2/3‬مــن نظــام مكافحــة‬\n\n\n‫‪141‬‬\n\f‫املخــدرات واملؤثــرات العقليــة‪ .‬وتســتر االول علــى مصدرهــا املعاقــب‬\n                               ‫عليــه شــرع ًا وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪-1‬مــا جــاء يف إقراريهمــا املشــار إليهــا واملدونــة علــى اللفــة رقــم (‪)24‬‬\n                                                  ‫رقــم الصفحــات (‪ 1‬حتــى ‪. )4‬‬\n               ‫‪-2‬محضر القبض املشار إليه واملدون على اللفة رقم (‪. )1‬‬\n‫‪-3‬مــا جــاء يف التقريــر الكيميائــي الشــرعي املشــار إليــه واملــدون علــى‬\n                                                                        ‫اللفــة (‪. )41‬‬\n‫وبالبحــث عــن ســوابقهما لــم يعثــر لهمــا علــى أي ســابقة حتــى تاريخــه‬\n                                  ‫وأقــر األول بوجــود ســابقة مخــدرات عليــه‪.‬‬\n‫وحيــث أن مــا أقــدم عليــه املدعــى عليهمــا وهمــا بكامــل أهليتهمــا‬\n‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب اثبــات‬\n                     ‫إدانتهمــا مبــا اســند إليــه واحلكــم عليهمــا مبــا يلــي ‪:‬‬\n                           ‫‪ .1‬بحد املسكر لقاء تعاطيهما احلشيش املخدر ‪.‬‬\n‫‪ .2‬بعقوبــة لــأول وفقـ ًا للمــادة (‪ )38‬مــن ذات النظــام لقــاء قيامه بالترويج‬\n                                                              ‫عــن طريــق االهداء ‪.‬‬\n‫‪ .3‬بعقوبــة للثانــي وفقـ ًا للمــادة (‪ )41‬مــن ذات النظــام لقاء حيازة ســيجارة‬\n                                      ‫مخلوطــة مبــادة احلشــيش بقصد التعاطي ‪.‬‬\n‫‪ .4‬منعهمــا مــن الســفر خــارج اململكــة وفق ـ ًا للمــادة (‪ )56‬مــن ذات‬\n                                                                            ‫النظــام‪.‬‬\n‫‪ .5‬بعقوبــة تعزيريــة لــأول لقــاء تســتره علــى مصــدر املخــدرات‬\n‫اســتناد ًا لتعميــم أميــر منطقــة الريــاض باإلنابــة رقــم (‪ )10272‬وتاريــخ‬\n                                           ‫‪1430/5/17‬ه ـ ‪ .‬واهلل املوفــق‪،،،‬‬\n‫وبســؤال املدعــى عليهمــا عــن دعــوى املدعــي العــام أجــاب املدعــى عليــه‬\n\n\n                                                                                         ‫‪142‬‬\n\f      ‫االول ‪ ....‬بقولــه ‪ :‬ال صحــه ملــا جــاء يف دعــوى املدعــي العــام أنــي قمــت‬\n      ‫بإهــداء املدعــى عليــه الثانــي ‪ ....‬ســيجارة حشــيش ( صــاروخ ) والصحيــح‬\n      ‫أننــي كنــت أدخــن ســيجارة حشــيش داخــل الســيارة وهــي متوقفــة وانــا‬\n      ‫خلــف مقــود الســيارة ويركــب معــي املدعــى عليــه الثانــي ‪ ....‬وحــن‬\n      ‫حضــرت الشــرطة مــن جهتــي أطفــأت الســيجارة ومــن ثــم رميتهــا علــى‬\n      ‫زميلــي ‪ ......‬ليتخلــص منهــا مــن جهتــه فرماهــا علــى األرض مباشــرة ولــم‬\n      ‫أتســتر علــى مصــدر املخــدرات حيــث بينــت جلهــة التحقيق أنني اشــتريتها‬\n      ‫مــن شــخص ال أعرفــه يف البطحــاء مبدينــة الريــاض هكــذا أجــاب‬\n      ‫املدعــى عليــه ‪ .‬وأجــاب املدعــى عليــه الثانــي بقولــه ‪ :‬صحيــح أننــي كنــت‬\n      ‫أركــب مــع زميلــي ‪ ....‬وكان يدخــن ســيجارة حشــيش وحــن حضــرت‬\n      ‫الشــرطة مــن جهتــه رمــى بالســيجارة علــي ألتخلــص منهــا فرميتهــا مــن‬\n      ‫جهتــي علــى األرض ولــم أدخــن احلشــيش يف ذلــك اليــوم وســبق أن دخنتــه‬\n      ‫قبــل تلــك القضيــة بثالثــة أشــهر أو أربعــة أشــهر هكــذا أجــاب ‪ .‬وبعرضه‬\n      ‫علــى املدعــي العــام قــال الصحيــح مــا ذكرتــه وليــس لــدي ســوى مــا يف‬\n      ‫أوراق املعاملــة ‪ .‬ثــم جــرى اعــادة مناقشــة املدعــى عليــه األول عــن مــا‬\n      ‫نســب اليــه مــن اهــداء املدعــى عليــه الثانــي ســيجارة احلشــيش فقــال أن‬\n      ‫معــي ســيجارة واحــدة فقــط دخنــت منهــا وبعــد أن حضــرت الشــرطة‬\n      ‫رميتهــا علــى زميلــي ‪ .....‬ليرميهــا مــن جهتــه وقــال احملقــق ان هــذا اهــداء‬\n      ‫وأصــر علــي فقلــت اهــداء والصحيــح مــا ذكرتــه كمــا جــرى مناقشــة‬\n      ‫املدعــى عليــه الثانــي أنــه أقــر لــدى جهــة التحقيــق أن املدعــى عليــه مــر‬\n      ‫عليــه بســيارته فركبــت معــه ومعــه ســيجارتي حشــيش واعطــاه واحــده‬\n      ‫وأبقــى معــه ســيجارة يدخنهــا وبعدهــا حضــرت الشــرطة قــام األول‬\n      ‫ببلــع الباقــي ورمــى هــو الباقــي فقــال صحيــح أن املدعــى عليــه األول‬\n\n\n‫‪143‬‬\n\f‫بعــد أن ركبــت معــه أعطانــي ســيجارة ومعــه ســيجارة فدخــن ســيجارته‬\n‫ودخنــت ســيجارتي وبعــد أن حضــرت الشــرطة ابتلــع ‪ ...‬باقــي الســيجارة‬\n‫وأنــا رميــت الباقــي وأنــا مســتخدم فقــط ومــا وجــد يف االرض فهــو مــن‬\n‫الســيجارة التــي كانــت معــي هكــذا أجــاب ‪ .‬ثــم جــرى منــا االطــاع‬\n‫علــى أوراق املعاملــة ومــن ضمنهــا كــرت الســوابق اجلنائــي للمدعــى عليه‬\n‫األول ‪ ....‬املبــن وجــود ســابقة حيــازة مخــدرات يف ‪1432/1/19‬ه ـ ومــن‬\n‫بينهــا كــرت الســوابق للمدعــى عليــه الثانــي املبــن عــدم وجــود ســوابق‬\n‫علــى املدعــى عليــه ‪ .‬ومــن ضمــن أوراق املعاملــة التقريــر الكيميائــي رقم‬\n‫‪/3438‬س يف ‪1433/4/5‬ه ـ املبــن ثبــوت ايجابيــة املرســل ملســتخلص‬\n‫التبــغ ملــادة احلشــيش وهــو مــن املــواد املخــدرة ‪ .‬فبنــاء علــى مــا تقــدم مــن‬\n‫دعــوى املدعــي العــام واجابــة املدعــى عليهمــا وحيــث اقــر كل واحــد مــن‬\n‫املدعــى عليهمــا باســتعمال احلشــيش املخــدر وحيــث أنكــر املدعــى عليــه‬\n‫االول أنــه أهــدى املدعــى عليــه الثانــي ســيجارة احلشــيش وســبق إقــراره‬\n‫لــدى جهــة التحقيــق أنــه أهــدى املدعــى عليــه الثانــي وأقــر لــدي أنــه أقــر‬\n‫لــدى جهــة التحقيــق فــا يقبــل رجوعــه ‪ .‬وحيــث أقــر املدعــى عليــه الثانــي‬\n‫أنــه ركــب مــع املدعــى عليــه األول وافــاد أن زميلــه أعطــاه ســيجارة‬\n‫حشــيش ودخنهــا وأنــه رمــى الباقــي وبنــاء علــى التقريــر الكيميائــي‬\n‫الشــرعي املثبــت إيجابيــة املرســل ملســتخلص التبــغ وبنــاء علــى املــادة‬\n‫الثامنــة والثالثــن واحلاديــة واالربعــن واملادة الســتني مــن نظام مكافحة‬\n‫املخــدرات واملؤثــرات العقليــة ونظــرا لقلــة الكميــة املضبوطــة وألنــه ال‬\n‫ســوابق مســجلة علــى املدعــى عليــه الثانــي لذلــك كلــه فقــد حكمــت‬\n‫باآلتــي ‪ )1 :‬أن يجلــد كل واحــد مــن املدعــى عليهمــا حــد املســكر‬\n‫ثمانــن جلــدة دفعــة واحــدة علنــا ‪ )2‬ثبــت لــدي ادانــة املدعــى عليــه األول‬\n\n\n                                                                                          ‫‪144‬‬\n\f      ‫‪ ....‬باهــداء املدعــى عليــه الثانــي‪ ....‬ســيجارة حشــيش ليقــوم بتدخينهــا‬\n      ‫‪ .‬ثبــت احتــواء مســتخلصها ملــادة احلشــيش املخــدر ونظــرا لصغــر ســن‬\n      ‫املدعــى عليــه ‪ ...‬وقلــة الكميــة املضبوطــة فقــد قــررت تعزيــره عــن ذلــك‬\n      ‫بــأن يســجن ســتة أشــهر حتتســب منهــا مــدة التوقيــف وان يجلــد مائــة‬\n      ‫وخمســن جلــدة مفرقــة علــى ثــاث دفعــات متســاوية بينهــن خمســة أيــام‬\n      ‫وبينهــا وبــن جلــد احلــد عشــرة ايــام وأن مينــع مــن الســفر ملــدة ســنتني‬\n      ‫بعــد خروجــه مــن الســجن ‪ ) 3‬ثبــت لــدي حيــازة املدعــى عليــه الثانــي ملــا‬\n      ‫ضبــط يف القضيــة ووزنــه خمســة أعشــار اجلــرام ثبــت احتــواء مســتخلص‬\n      ‫التبــغ فيهــا ملــادة احلشــيش بقصــد االســتعمال وألنــه الباقــي مــن املســتعمل‬\n      ‫فــا أرى مايوجــب تعزيــره عليــه اكتفــاء بحــد املســكر ‪ - 4‬أن مينــع‬\n      ‫املدعــى عليــه الثانــي مــن الســفر ملــدة ســنتني بعــد خروجــه مــن الســجن‬\n      ‫وبــه حكمــت حتريــرا ‪1433/5/22‬ه ـ وبعرضــه علــى املدعــي العــام‬\n      ‫قــرر رغبتــه يف رفعــه حملكمــة االســتئناف بــدون ال ئحــة وقــرر املدعــى‬\n                                    ‫عليهمــا القناعــة وصلــى اهلل علــى نبينــا محمــد ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1434/01/10‬ه ـ‬\n      ‫افتتحــت اجللســة بعــد ان عــادت الينــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫وبرفقهــا القــرار الشــرعي رقــم ‪ 33310804‬يف ‪1433/6/23‬ه ـ وجــاء‬\n      ‫فيــه بعــد املقدمــة وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫قررنــا باألكثريــة إعادتهــا ملالحظــة اآلتــي ‪ :‬أوال ‪ :‬اثبــت فضيلتــه إدانــة‬\n      ‫املدعــى عليــه األول ‪ ....‬إهــداءه ســيجارة حشــيش للمدعــى عليــه الثانــي‬\n      ‫ليقــوم بتدخينهــا وهــذا محــل نظــر ألن املدعــى عليــه منكــر وال بينــة‬\n      ‫للمدعــي العــام ‪ .‬ثانيــا ‪ :‬أثبــت فضيلتــه حيــازة املدعــى عليــه الثانــي ‪ ...‬ملــا‬\n      ‫وزنــه خمســة أعشــار اجلــرام ملــادة احلشــيش املخــدر بقصــد االســتعمال‬\n\n\n‫‪145‬‬\n\f‫ولــم يجــازه حيــال ذلــك وهــذا فيــه نظــر والبــد مــن معاقبــة املدعــى عليــه‬\n‫حســب املــادة رقــم ( ‪ ) 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة ‪ .‬ثالثــا ‪ :‬طالــب املدعــى العــام بتعزيــر املدعــى عليــه األول ‪ ...‬لقــاء‬\n‫تســتره علــى مصــدر املخــدرات ولــم جنــد فضيلتــه تعــرض لذلــك بشــيء‬\n‫يف حكمــه فعلــى فضيلتــه إعــادة النظــر والتأمــل وإجــراء مــا يلــزم ‪ .‬واهلل‬\n‫املوفــق ‪ .‬أ ‪ -‬ه ـ وجوابــا عليــه ‪ .‬فعلــى الفقــرة األولــى أن املدعــى عليــه ‪...‬‬\n‫أقــر لــدى جهــة التحقيــق ابتــداءا أنــه أهــدى زميلــه املدعــى عليــه الثانــي‬\n‫كمــا أقــر لــدي ان االقــرار صــدر منــه لــدى جهــة التحقيــق ويعضــد هــذا‬\n‫كذلــك افــادة زميلــه املدعــى عليــه الثانــي أنــه حــن ركــب مــع املدعــى‬\n‫عليــه األول كان معــه ســيجارتني حشــيش وأعطــاه واحــدة وأبقــى معــه‬\n‫واحــدة وهــذا كاف يف صفــة االهــداء فليــس معاوضة حتتاج إلى إيجاب‬\n‫وقبــول ‪ .‬وعلــى الثانيــة أن الكميــة قليلــة جــدا وهــي أشــبه بالباقــي مــن‬\n‫املســتعمل ويكــون التعزيــر عنهــا داخــل يف عقوبــة اقامــة احلــد ‪ .‬وعلــى‬\n‫الثالثــة ولتوجــة تهمــة تســتر املدعــى عليــه األول ‪ ...‬علــى مصــدر املخدرات‬\n‫فيكــون تعزيــره عنهــا داخــل يف التعزيــر أعــاه ‪ .‬وبذلــك متــت االجابــه‬\n                                 ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة باخلــرج املكلــف برقــم‬\n‫‪ 331289685‬وتاريــخ ‪1434/1/12‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ .... /‬املســجل برقــم ‪33260798‬‬\n‫وتاريخ‪1433/5/23‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد كل مــن‪/‬‬\n‫‪ .....-2 .....-1‬التهامهمــا بقضيــة مخــدرات علــى النحــو املوضــح بالقــرار‬\n\n\n                                                                                          ‫‪146‬‬\n\f      ‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‪ .‬وحيــث ســبق‬\n      ‫دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب‬\n      ‫بــه فضيلتــه علــى قــرار الدائــرة رقــم ‪ 33310804‬يف ‪1433/6/23‬ه ـ‬\n      ‫قررنــا باألكثريــة أنــه لــم يظهــر مــا يوجــب نقــض احلكــم بعــد اإلجــراء‬\n      ‫األخيــر‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                 ‫وصحبــه أجمعــن‪.‬‬\n\n\n\n\n‫‪147‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":139,"source_page_end":147,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"14517e8e5e25b015b486f69606ac57126105c18e093ba1d256731b33fed4e8a0","normalized_text_hash":"cd39e6116f85533fb7903c0883534fe1b683b813fb79246c61bb220af4c81bb3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p139-33260798"},{"id":"fb1f5b03-6702-557c-b4ee-f47b4bfc444c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج قات -تعاطي القات -إقرار -التستر على مصدر القات -التعزير بالسجن واجللد .","document_number":"33266415","case_number":"33345475","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/05/25","year":"1434","subject":"مخدرات -ترويج قات -تعاطي القات -إقرار -التستر على مصدر القات -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33266415 :‬تاريخه ‪1433/05/25:‬هـ‬\n                   ‫رقم الدعوى ‪33345475:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 34262265‬تاريخه‪1434/7/8:‬هـ‬\n\n\n ‫مخــدرات‪ -‬ترويــج قــات ‪ -‬تعاطــي القــات ‪ -‬إقــرار ‪ -‬التســتر علــى مصــدر‬\n                                      ‫القــات ‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n                         ‫‪ -1‬قرار مجلس الوزراء رقم (‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n ‫‪ -2‬املادة الثالثة من القرار الوزاري رقم (‪ )2057‬وتاريخ ‪1404/05/26‬هـ‬\n ‫‪ -3‬الفقــرة (ب) مــن املــادة اخلامســة مــن القــرار الــوزاري رقــم (‪)2057‬‬\n                                                 ‫وتاريــخ ‪1404/05/26‬ه ـ ‪.‬‬\n ‫‪ -4‬األمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/09‬ه ـ برقيــة‬\n ‫ســمو ولــي العهــد وزيــر الداخليــة برقــم ‪ 80719‬وتاريــخ ‪1432/12/25‬ه ـ ‪.‬‬\n\n\n\n\n ‫أدعــى املدعــي العــام ضــد املدعــى عليــه بتســليم مائتــن واثنــن وثالثــن‬\n ‫جرامـ ًا وعشــر اجلــرام مــن نبــات القــات احملظور بقصــد الترويج واالجتار‬\n ‫‪ ،‬وتعاطيــه للقــات احملظور‪،‬حيــث وردت معلومــات لشــعبة مكافحــة‬\n ‫املخــدرات مــن أحــد مصادرهــا عــن قيــام املدعــى عليــه بترويــج القــات‬\n ‫واتصــل املصــدر علــى املدعــى عليــه و طلــب حزمــة مــن القــات فوافــق‬\n ‫املدعــى عليــه علــى ذلــك ومت تزويــد املصــدر باملبلــغ املرقــم ورافقــه أحــد‬\n ‫أعضــاء الفرقــة ويف املــكان احملــدد حضــر املدعــى عليــه وســلم املصــدر‬\n\n                                                                                      ‫‪148‬‬\n\f      ‫حزمــة القــات فتــم القبــض عليــه ‪ ،‬وطلــب املدعــي العــام إثبــات إدانــة‬\n      ‫املدعــى عليــه مبــا نســب إليــه و احلكــم عليــه بعقوبــة تعزيريــة علــى ضــوء‬\n      ‫القــرار الــوزاري املشــار إليــه ‪ ،‬وبعقوبــة تعزيريــة لقــاء تســتره علــى مصدر‬\n      ‫مــا ضبــط ‪ ،‬كمــا أقــر املدعــى عليــه مبــا نســب إليــه و أبــدى ندمــه‬\n      ‫وتوبتــه ‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n      ‫للمــادة الفعالــة لنبــات القــات ‪ ،‬وملــا تقــدم حكمــت احملكمــة بإثبــات‬\n      ‫إدانــة املدعــى عليــه مبــا نســب إليــه و تعزيــره بالســجن و اجللــد وصــرف‬\n      ‫النظــر عــن طلــب املدعــي العــام مصــادرة الهاتــف اجلــوال وإلغــاء الشــريحة‬\n                                       ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33345475‬وتاريــخ ‪ 1433/05/18‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33942366‬وتاريــخ ‪ 1433/05/18‬ه ـ ففــي يــوم‬\n      ‫االثنــن املوافــق ‪ 1433/05/24‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 40‬‬\n      ‫وفيهــا حضراملدعــي العــام ‪ ... /‬وادعــى علــى ‪ ، .... /‬البالــغ مــن العمــر‬\n      ‫(‪ )43‬ســنة‪ ،‬ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة رقــم (‪-)...‬‬\n      ‫متــزوج ‪ ،‬موظــف قطــاع خــاص‪ ،‬متعلــم ‪ ،‬يقيــم مبدينــة الريــاض ‪ ،‬أوقــف‬\n      ‫بتاريــخ ‪ 1433/4/12‬ه ـ وأحيــل إلــى شــعبة ســجن امللــز مبوجــب اإلحالــة‬\n      ‫ومتديــد التوقيــف رقــم (ه ـ ر‪ )43941/5/1‬وتاريــخ‪1433/4 /15‬ه ـ‬\n      ‫اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي على‬\n                                      ‫املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n\n‫‪149‬‬\n\f‫حيــث إنــه بتاريــخ ‪ 1433/4/12‬ه ـ قبــض علــى املذكــور مــن قبــل‬\n‫إحــدى فــرق شــعبة املكافحــة والبحــث والتحــري التابعــة لــإدارة العامــة‬\n‫ملكافحــة املخــدرات مبنطقــة الريــاض حيــث وردت معلومــات مــن أحــد‬\n‫املصــادر الســرية عــن قيــام املذكــور بترويــج القــات املخــدر ويتواجــد‬\n‫علــى اجلــوال رقــم (‪ ) ...‬وأســتعد املصــدر بالشــراء منــه واإلطاحــة بــه ومت‬\n‫االيعــاز للمصــدر باالتصــال علــى املــروج وطلــب منــه حزمــة مــن نبــات‬\n‫القــات احملظــور مببلــغ مالــي وقــدره (‪ )350‬ثالثمائــة وخمســون ريــا ًال‬\n‫فوافــق املــروج علــى ذلــك وطلــب مــن املصــدر احلضــور إلــى مخــرج (‪)17‬‬\n‫بالقــرب مــن محطــة محروقــات ومت اإليعــاز للفرقــة باالنتقــال إلــى املوقــع‬\n‫احملــدد وبرفقهــم املصــدر ومت تفتيــش املصــدر وســيارته تفتيش ـ ًا دقيق ـ ًا‬\n‫وزود باملبلــغ املرقــم املتفــق عليــه وبوصــول الفــرد واملصــدر للموقــع حضــر‬\n‫املذكــور واحتــك بســيارة املصــدر عندهــا ترجــل املصــدر مــن ســيارته‪،‬‬\n‫وقــام املــروج بتســليم املصــدر حزمــة بهــا أوراق خضــراء اللــون يشــتبه أن‬\n‫تكــون نبــات القــات احملظــور تــزن (‪ )232،1‬مائتــن واثنــان وثالثــون‬\n‫جرام ـ ًا وعشــر اجلــرام وقبــل تســلم املــروج املبلــغ املرقــم املتفــق عليــه‬\n‫أحــس بوجــود رجــال املكافحــة فحــاول الهــرب فتــم ضبطــه وبتفتيشــه‬\n‫عثــر معــه علــى هاتــف نقــال مــن نــوع (‪ )....‬يحمــل الرقــم املصنعــي‬\n   ‫(‪ )..................‬وهوالهاتــف الــذي مت مــن خاللــه امتــام عمليــة الترويــج ‪.‬‬\n‫وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة‬\n‫الســموم والكيميــاء الطبيــة الشــرعية املرفــق رقــم (‪/4038‬س) لعــام‬\n‫‪ 1433‬إيجابيــة عينــة النبــات األخضــر املضبــوط للمــواد الفعالــة لنبــات‬\n‫القــات املــدرج باجلــدول رقــم (‪ )4‬امللحــق بنظــام مكافحــة املخــدرات‬\n                                                             ‫واملؤثــرات العقليــة‪.‬‬\n\n\n                                                                                         ‫‪150‬‬\n\f      ‫وبســماع أقــوال املذكــور األوليــة اعتــرف بحيــازة نبــات القــات احملظــور‬\n      ‫بقصــد التعاطــي وباســتجوابه اعتــرف بالتفــاوض مــع املصــدر وأنــه‬\n      ‫ذهــب إلــى املصــدر لكــي يســلمه نبــات القــات احملظــور وقبــل تســليمه‬\n      ‫إيــاه مت القبــض عليــه كمــا أعتــرف بتعاطــي القــات احملظــور ودون لــه‬\n      ‫إقــرار بذلــك‪ .‬وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام ل‪... /‬‬\n      ‫بتســليم ماوزنــه (‪ )232،1‬مائتــن واثنــان وثالثــون جرامـ ًا وعشــر اجلــرام‬\n      ‫مــن نبــات القــات احملظــور بقصــد الترويــج واالجتــار وتعاطيــه القــات‬\n      ‫احملظــور املعاقــب علــى ذلــك مبوجــب قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n      ‫لعــام ‪1374‬ه ـ ‪،‬وتســتره علــى مصــدر مــامت تســليمه املعاقــب علــى ذلــك‬\n                                               ‫شــرعاً‪ .‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫ا علــى‬ ‫‪ .1‬مــا تضمنــه اعترافــه حتقيق ـ ًا املنــوه عنــه املــدون تفصي ـ ً‬\n      ‫الصفحــات رقــم (‪ )2-1‬مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم‬\n                                                                                         ‫( ‪.)15‬‬\n      ‫‪ .2‬ماتضمنــه اقــراره املنــوه عنــه املــدون علــى الصفحــة رقــم ( ‪) 3‬مــن دفتــر‬\n                                                         ‫التحقيــق املرفــق لفــة رقــم ( ‪.) 15‬‬\n      ‫‪ .3‬ماتضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة املنــوه عنــه املــدون‬\n      ‫ا علــى الصفحــة رقــم (‪ )2‬مــن ملــف ضبــط أجــراءات قضيــة‬                     ‫تفصي ـ ً‬\n                                               ‫مخــدرات املرفــق علــى اللفــة رقــم (‪.) 2‬‬\n      ‫ا علــى الصفحــة‬   ‫‪ .4‬مــا تضمنــه محضــر القبــض املنــوه عنــه املــدون تفصيـ ً‬\n      ‫رقــم (‪ )2‬مــن ملــف ضبــط إجــراءات قضيــة مخــدرات املرفــق علــى اللفــة‬\n                                                                                      ‫رقــم (‪.)1‬‬\n      ‫‪ .5‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق علــى‬\n                                                                           ‫اللفــة رقــم (‪.)43‬‬\n\n\n‫‪151‬‬\n\f‫وببحــث ســوابقه تبــن عــدم وجــود ســوابق مســجلة مســجلة عليــه حتــى‬\n‫تاريخــه وعثــر لــه علــى قضيــة مخــدرات قيــد اإلجــراء برقــم (‪)26/694‬‬\n‫وأحيلــت إلــى احملكمــة اجلزئيــة مبوجــب اخلطــاب رقــم (‪ )30046‬وتاريــخ‬\n‫ـب‬\n ‫ـرم ومعاقـ ٌ‬ ‫‪1427/5/3‬هــ‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور فعــل محـ ٌ‬\n‫عليــه شــرع ًا ونظامـاً‪ ،‬لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم‬\n‫عليــه باالتــي‪-1 :‬بعقوبــة تعزيريــة علــى ضــوء القــرار الــوزاري املشــار‬\n                                                                              ‫إليــه ‪.‬‬\n                ‫‪-2‬بعقوبة تعزيرية بحقه لقاء تستره على مصدر ما ضبط ‪.‬‬\n‫‪ -3‬مصــادرة هاتفــه النقــال مــن نــوع (‪ )....‬ذي الرقــم املصنعي (‪)..............‬‬\n                                                           ‫الســتخدامه يف اجلرمية‪.‬‬\n‫‪-4‬إلغــاء الشــريحة املســتخدمة يف اجلرميــة‪ ،‬وعــدم صرفهــا لنفــس‬\n‫املشــترك يف حــال صــدور احلكــم باإللغــاء‪ ،‬وإبــاغ الشــركة مصــدرة‬\n‫الشــريحة بذلــك بعــد صــدور احلكــم باإللغــاء وفقـ ًا لتعميــم ســمو النائــب‬\n‫الثانــي وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪ . 1428/2/10-9‬هــذه‬\n‫دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب بقولــه‪:‬‬\n‫مــا ذكــره املدعــي العــام مــن أننــي تفاوضــت مــع املصــدر علــى بيــع حزمــة‬\n‫قــات مقابــل مبلــغ مالــي فهــذا صحيــح‪ ،‬إال أننــي ال أروج القــات بشــكل‬\n‫مســتمر وإمنــا املصــدر أعرفــه مــن قبــل‪ .‬وعندمــا تقابلنــا قبــض علــي‬\n‫بعــد أن ســلمته القــات وقبــل أن أســتلم منــه املبلــغ‪ .‬وأنــا نــادم علــى مــا‬\n‫فعلــت وتائــب إلــى اهلل‪ .‬واجلــوال الــذي ذكــره املدعــي العــام هــو جوالــي‪.‬‬\n‫وأنــا ســبق وأن تعاطيــت القــات قبــل القبــض‪ .‬ومصــدر القــات شــخص‬\n‫صومالــي ال أعرفــه ‪ .‬هكــذا أجــاب‪ .‬وبالرجــوع إلــى املعاملــة وجــدت بــن‬\n‫طياتهــا علــى اللفــة رقــم‪ )43( :‬التقريــر الكيميائــي الشــرعي الصــادر‬\n\n\n                                                                                         ‫‪152‬‬\n\f      ‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية املرفــق‬\n      ‫رقــم (‪/4038‬س) لعــام ‪ 1433‬ويتضمــن إيجابيــة عينــة النبــات األخضــر‬\n      ‫املضبــوط للمــواد الفعالــة لنبــات القــات املــدرج باجلــدول رقــم (‪ )4‬امللحــق‬\n                                   ‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‪ ،‬وملصادقــة املدعــى عليــه‬\n      ‫علــى بيعــه وتســليمه للقــات احملظــور مبقابــل مــادي‪ .‬ونظــرا ملــا تضمنــه‬\n      ‫التقريــر الكيميائــي الشــرعي املذكــور بعاليــه‪ .‬ونظــرا ملــا أبــداه املدعى‬\n      ‫عليــه مــن النــدم والتوبــة‪ .‬ولضألــة الكميــة املضبوطــة واعتــراف املدعــى‬\n      ‫عليــه‪ .‬ممــا يوجــب تخفيــف العقوبــة‪ .‬ونظــرا ألن أحــكام املصــادرة‬\n      ‫الصــادرة بنظــام مكافحــة املخــدرات وتعميــم ســمو ولــي العهــد هــي‬\n      ‫خاصــة بالقضايــا املعاقــب عليــه مبوجــب نظــام مكافحــة املخــدرت وال‬\n                       ‫تســري يف قضايــا القــات احملظــور‪ .‬فبنــاء علــى مــا تقــدم‪.‬‬\n      ‫فقــد ثبــت لــدي إدانــة املدعــى عليــه‪ ... /‬بتســليم ماوزنــه (‪)232،1‬‬\n      ‫مائتــن واثنــان وثالثــون جرامـ ًا وعشــر اجلــرام مــن نبــات القــات احملظــور‬\n      ‫بقصــد الترويــج واالجتــار وتعاطيــه القــات احملظــور املعاقــب علــى‬\n      ‫ذلــك مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ‪،‬وتســتره‬\n      ‫علــى مصــدر مــامت تســليمه‪ .‬وقــررت مــا يلــي‪ :‬أوال‪ :‬النــزول علــى احلــد‬\n      ‫األعلــى مــن العقوبــة املقــررة يف املــادة الثالثــة مــن القــرار الــوزاري رقــم‪:‬‬\n      ‫‪ 2057‬بتاريــخ‪1404/5/26 :‬ه ـ إعمــاال للفقــرة (ب) مــن املــادة اخلامســة‬\n      ‫مــن القــرار الــوزاري املذكــور‪ .‬وذلــك بســجن املدعــى عليــه ملــدة ســنة‬\n      ‫تبــدأ مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة‪ .‬لقــاء ترويجــه القــات‬\n      ‫وتعاطيــه لــه‪ .‬ثانيــا‪ :‬جلــد املدعــى عليــه أربعــن جلــدة دفعــة واحــدة‬\n      ‫تعزيــرا لقــاء تســتره علــى مصــدر القــات‪ .‬ثالثــا‪ :‬صــرف النظــر عــن طلــب‬\n\n\n‫‪153‬‬\n\f‫املدعــي العــام مصــادرة هاتفــه النقــال مــن نــوع (‪ )....‬ذي الرقــم املصنعــي‬\n‫(‪ )......................‬الســتخدامه يف اجلرميــة‪ .‬وإلغــاء الشــريحة املســتخدمة‬\n‫يف اجلرميــة‪ ،‬وعــدم صرفهــا لنفــس املشــترك يف حــال صــدور احلكــم‬\n‫باإللغــاء‪ ،‬وإبــاغ الشــركة مصــدرة الشــريحة بذلــك بعــد صــدور‬\n‫احلكــم باإللغــاء وفقـ ًا لتعميــم ســمو النائــب الثانــي وزيــر الداخليــة رقــم‬\n‫(‪ )9798‬وتاريــخ ‪ . 1428/2/10-9‬لعــدم قيــام موجبــه‪ .‬وبــه حكمــت‪.‬‬\n‫وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة باحلكــم وقــرر‬\n‫املدعــي االعتــراض علــى احلكــم مكتفيــا بالئحــة الدعــوى كالئحــة‬\n‫اعتراضيــة‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                              ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/05/24‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33345475‬وتاريــخ ‪ 1433/05/18‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33942366‬وتاريــخ ‪ 1433/05/18‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافــق‪ 1433/11/03‬ه ـ افتتحــت اجللســة الســاعة وفيهــا‬\n‫عــادت العاملــة مــن محكمــة األســتئناف بالريــاض وبرفقهــا القــرار‬\n‫رقــم (‪ )33399028‬وتاريــخ ‪1433/9/2‬ه ـ واملتضمــن « وبدراســة القــرار‬\n‫وصــورة ضبطــه واوراق املعاملــة لوحــظ أن مــا أجــراه فضيلتــه مــن تقريــر‬\n‫العقوبــة بنــاء علــى القــرار الــوزاري برقــم ‪2057‬محــل نظــر وخــاف مــا‬\n‫ورد يف خطــاب املقــام الســامي رقــم ‪/601‬م وتاريــخ ‪1433/3/17‬ه ـ‬\n‫واملبلــغ بالتعميــم برقــم ‪63/5/8‬وتاريــخ ‪1410/4/14‬ه ـ باعتمــاد مافيــه‬\n‫بخصــوص القــات ونصــت الفقــرة الثالثــة بــأن أختصــاص احملاكــم هــو‬\n‫االكتفــاء بإثبــات اإلدانــة شــرعا كمــا يخالــف التعميم رقــم ‪/12/51‬ت‬\n\n\n                                                                                      ‫‪154‬‬\n\f      ‫وتاريــخ ‪1400/4/28‬ه ـ التصنيــف ج ـ ‪ . 492 __490/3‬وهــو نــص يف‬\n      ‫القــات ايضــا بــأن تقتصــر احملاكــم علــى تقريــر اإلدانــة ووصــف اجلــرم‬\n      ‫وهــذه التعاميــم بنيــت علــى أوامــر عليــا وهــي ناســخة ملــا يتعــارض معهــا‬\n      ‫« ‪ ..........‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                    ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/03‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33345475‬وتاريــخ ‪ 1433/05/18‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33942366‬وتاريــخ ‪ 1433/05/18‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافــق‪ 1434/01/10‬ه ـ افتتحــت اجللســة الســاعة ‪11.30‬‬\n      ‫بعــد عودتــي مــن املشــاركة يف البرنامــج التدريبــي القضائــي والــذي‬\n      ‫اســتمر ملــدة شــهرين ابتــداء مــن تاريــخ‪1433/10/06 :‬ه ـ ‪ .‬وقــد عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف بالريــاض وبرفقهــا القــرار الصــادر‬\n      ‫مــن الدائــرة األولــى لتمييــز القضايــا اجلزائيــة رقــم‪ 33399028 :‬بتاريــخ‪:‬‬\n      ‫‪1433/09/02‬ه ـ واملتضمــن مالحظــة أصحــاب املعالــي ما يلي‪« :‬لوحظ‬\n      ‫أن مــا أجــراه فضيلتــه مــن تقريــر العقوبــة بنــاء علــى القــرار الــوزاري‬\n      ‫برقــم ‪2057‬محــل نظــر وخــاف مــا ورد يف خطــاب املقــام الســامي رقــم‬\n      ‫‪/601‬م وتاريــخ ‪1433/3/17‬ه ـ واملبلــغ بالتعميــم برقــم ‪63/5/8‬وتاريــخ‬\n      ‫‪1410/4/14‬ه ـ باعتمــاد مافيــه بخصــوص القــات ونصت الفقــرة الثالثة‬\n      ‫بــأن أختصــاص احملاكــم هــو االكتفــاء بإثبــات اإلدانــة شــرعا كمــا‬\n      ‫يخالــف التعميــم رقــم ‪/12/51‬ت وتاريــخ ‪1400/4/28‬ه ـ التصنيــف ج ـ‬\n      ‫‪ . 492 -490/3‬وهــو نــص يف القــات ايضــا بــأن تقتصــر احملاكــم علــى‬\n      ‫تقريــر اإلدانــة ووصــف اجلــرم وهــذه التعاميــم بنيــت علــى أوامــر عليــا‬\n\n\n‫‪155‬‬\n\f‫وهــي ناســخة ملــا يتعــارض معهــا « عليــه أجيــب أصحــاب املعالــي قضــاة‬\n‫الدائــرة أن مــا مت إجــراءه مــن إثبــات إدانــة املدعــى عليــه وحتديــد العقوبــة‬\n‫هــو األمــر الســامي الكــرمي رقــم‪ 59633 :‬بتاريــخ‪1432/12/09 :‬ه ـ‬\n‫واملعمــم ببرقيــة ســمو ولــي العهــد وزيــر الداخليــة رقــم‪ 80719 :‬بتاريــخ‪:‬‬\n‫‪1432/12/25‬ه ـ واملتضمــن أن تطبــق احملاكــم علــى مرتكبــي جرائــم‬\n‫القــات العقوبــات املعمــول بهــا قبــل نفــاذ نظــام مكافحــة املخــدرات‬\n‫الــواردة يف قــرار مجلــس الــوزراء رقــم‪ 11 :‬لعــام ‪1374‬ه ـ وقــرار مجلــس‬\n‫الــوزراء رقــم‪ 172 :‬بتاريــخ‪1400/9/23 :‬ه ـ ‪ .‬وهــو متأخــر عمــا ذكــر‬\n‫بقــرار معاليكــم مــن تعاميــم‪ .‬وعليــه فأنــا علــى مــا حكمــت بــه‪ ،‬وقررت‬\n‫إعــادة رفــع املعاملــة إلــى محكمــة االســتئناف بالريــاض ليقــرر أصحــاب‬\n‫املعالــي مــا يرونــه‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/10‬ه ـ يف الســاعة الثانيــة‬\n                                                                     ‫عشــر ظهــرا‪.‬‬\n‫احلمــد هلل وحــده أطلــع قضــاة الدائــرة اجلزائيــة األولــى علــى املعاملــة‬\n‫الــواردة مــن احملكمــة اجلزائيــة بالريــاض برقــم‪ 34659512‬وتاريــخ‬\n‫‪1434/5/29‬ه ـ واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪ ... /‬برقــم ‪ 33266415‬وتاريــخ ‪1433/5/25‬ه ـ‬\n‫واخلــاص بدعــوى املدعــي العــام ضــد ‪ ... /‬موضوعهــا ترويــج قــات وبعــد‬\n‫التدقيــق يف إجابــة فضيلــة ناظــر القضيــة وفقــه اهلل علــى قــرار محكمــة‬\n‫االســتئناف الســابق تقــرر املصادقــة علــى احلكــم لعــدم موجــب املالحظة‬\n                                ‫وصلــى اهلل علــى نبينــا محمــد واهلل املوفــق‪.‬‬\n\n\n\n\n                                                                                        ‫‪156‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":148,"source_page_end":156,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2b982e47e8ca4db9b02bf404f52ebe53accab6ed9b7f1aa0adf2f4373a145866","normalized_text_hash":"2c9321b0f9386eac3d359c4e18e6cf0646fc43ed1e4b8b8a832392e3ddcbfe6d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p148-33266415"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

